INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('dp-b9', 'dp', 'Observer', 56, 15, '[{"k":"p","t":"Observer وابستگی انتشار/اشتراک می‌سازد؛ وقتی موضوع تغییر کند همه ناظرانش خبردار می‌شوند — پایه رویدادها و معماری واکنشی."},{"k":"h","t":"Observer؛ خبر دادن به جای پرسیدن"},{"k":"p","t":"وقتی یک شیء تغییر می‌کند و چند شیء دیگر باید از آن باخبر شوند، راه ساده این است که شیء تغییرکننده همه آن‌ها را مستقیم صدا بزند — ولی این وابستگی سفتی می‌سازد و با هر ناظر جدید، کدش عوض می‌شود. Observer این را برعکس می‌کند: ناظرها خودشان را «ثبت» می‌کنند و شیء موضوع فقط یک لیست از ناظرها دارد و هنگام تغییر، به همه‌شان خبر می‌دهد — بدون اینکه بداند آن‌ها چه‌اند یا چه می‌کنند. این پایه رویدادها در UI و معماری واکنشی است."},{"k":"h","t":"انتشار/اشتراک و جداسازی"},{"k":"p","t":"قدرت Observer در جداسازی است: موضوع (subject) نمی‌داند چند ناظر دارد و ناظرها هم از هم بی‌خبرند؛ فقط می‌دانند یک موضوع هست که خبر می‌دهد. این باعث می‌شود بتوانی ناظر جدید اضافه کنی بدون هیچ تغییری در موضوع. نسخه غیرمتمرکزش (pub/sub با یک واسطه) این جداسازی را بیشتر می‌کند؛ چون حتی موضوع و ناظرها همدیگر را نمی‌شناسند و فقط با یک broker ارتباط دارند — همان چیزی که در سیستم‌های پیام‌رسانی مثل Kafka می‌بینی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","صدازدن مستقیم","Observer"],"rows":[["وابستگی","موضوع همه ناظرها را می‌شناسد","موضوع فقط یک لیست ثبت‌نام دارد"],["افزودن ناظر","تغییر کد موضوع","فقط ثبت‌نام، بدون تغییر"],["آگاهی ناظرها از هم","ممکن","بی‌خبر از هم"]]},{"k":"warn","title":"دام رایج","t":"مراقب فراموش‌کردن لغو ثبت‌نام باش؛ اگر یک ناظر دیگر لازم نیست ولی از لیست موضوع حذف نشود، هم خبرهای بیهوده می‌گیرد و هم ممکن است موضوع را در حافظه نگه دارد (نشت). همیشه هنگام نابودی ناظر، unregister کن."},{"k":"tip","title":"نکته منتور","t":"هر جا در کدت دیدی یک تابع بعد از انجام کاری، چند تابع دیگر را «خبر» می‌کند یا لیستی از callbackها را صدا می‌زند، داری عملاً از Observer استفاده می‌کنی؛ شناخت این الگو به تو کمک می‌کند آن را آگاهانه و تمیز طراحی کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["موضوع لیست ناظرها را نگه می‌دارد","با تغییر، به همه notify می‌شود","ناظرها مستقل‌اند و می‌توانند بیایند و بروند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"observer.py","code":"class Store:\n    def __init__(self): self.subs = []\n    def subscribe(self, o): self.subs.append(o)\n    def set_price(self, p):\n        self.price = p\n        for o in self.subs: o.update(p)\n\nstore.subscribe(UI())\nstore.subscribe(Analytics())"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: موضوع لیست ناظرها را نگه می‌دارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت Observer بر صدا زدن مستقیم است؟","opts":["سرعت","ناشر لازم نیست بداند چه کسانی گوش می‌دهند؛ اشتراک‌ها بدون تغییر ناشر اضافه و کم می‌شوند","کمتر کد","اجباری"],"ans":1,"why":"اگر ناشر مستقیم UI و Analytics را صدا بزند، به هر دو میخکوب است؛ Observer اشتراک را پویا و ناشر را ساده نگه می‌دارد."},{"q":"Observer چه وابستگی‌ای را حذف می‌کند؟","opts":["وابستگی به دیتابیس","وابستگی سفتِ موضوع به ناظرها؛ موضوع فقط به یک لیست ثبت‌نام خبر می‌دهد و نمی‌داند ناظرها چه‌اند","وابستگی به شبکه","هیچ"],"ans":1,"why":"به‌جای اینکه موضوع همه ناظرها را بشناسد و مستقیم صدا بزند، ناظرها خودشان ثبت‌نام می‌کنند و موضوع فقط خبر می‌دهد؛ پس افزودن/حذف ناظر کد موضوع را تغییر نمی‌دهد."},{"q":"چرا هنگام نابودی ناظر باید unregister کرد؟","opts":["برای سرعت","تا خبر بیهوده نگیرد و موضوع را در حافظه نگه ندارد (جلوگیری از نشت)","اجباری است","برای کاهش ترافیک"],"ans":1,"why":"اگر ناظرِ حذف‌نشده در لیست بماند، موضوع همچنان نگهش می‌دارد و به آن خبر می‌دهد؛ پس هم منابع هدر می‌رود و هم ممکن است نشت حافظه پیش بیاید."}]'::jsonb),
('dp-b10', 'dp', 'Command', 56, 16, '[{"k":"p","t":"Command درخواست را به یک شیء تبدیل می‌کند؛ پس می‌توان آن را در صف گذاشت، لاگ کرد و مهم‌تر از همه، لغو کرد (undo)."},{"k":"h","t":"Command؛ درخواست به‌عنوان یک شیء"},{"k":"p","t":"معمولاً یک درخواست را مستقیم با صدازدن یک متد انجام می‌دهی. ولی اگر بخواهی درخواست را در صف بگذاری، لاگ کنی، یا مهم‌تر از همه لغوش (undo) کنی، نیاز داری خودِ درخواست یک «شیء» باشد. Command دقیقاً این کار را می‌کند: یک درخواست را داخل یک شیء کپسوله می‌کند که می‌داند چه کاری انجام بدهد و روی چه چیزی. آن‌وقت می‌توانی این شیءها را مثل هر داده دیگری نگه داری، جابه‌جا کنی و اجرا کنی — و چون هر Command می‌داند چطور اثرش را برعکس کند، undo ممکن می‌شود."},{"k":"h","t":"کاربردها؛ از undo تا صف کارها"},{"k":"p","t":"معروف‌ترین کاربرد Command در ویرایشگرها برای undo/redo است: هر عمل (تایپ، حذف) یک Command است که execute و undo دارد و در یک تاریخچه نگه داشته می‌شود. کاربرد دیگر، جداکردن «کسی که درخواست می‌دهد» از «کسی که اجرا می‌کند» است؛ مثلاً دکمه‌های UI فقط Command می‌سازند و یک اجراکننده جدا آن‌ها را انجام می‌دهد — پس می‌توانی درخواست‌ها را در صف بگذاری، زمان‌بندی کنی یا حتی به سرور بفرستی. این جداسازی، انعطاف زیادی می‌دهد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["کاربرد","چطور از Command استفاده می‌شود"],"rows":[["undo/redo","هر عمل یک Command با execute و undo، در تاریخچه"],["صف کارها","Commandها در صف می‌مانند و اجراکننده جدا انجام می‌دهد"],["جداسازی","درخواست‌دهنده (UI) از اجراکننده جدا می‌شود"],["لاگ عملیات","هر Command قبل و بعد از اجرا ثبت می‌شود"]]},{"k":"warn","title":"دام رایج","t":"برای هر متد ساده‌ای Command نساز؛ این الگو سربار دارد (یک کلاس به‌جای یک صدا). فقط وقتی واقعاً نیاز به صف، undo یا جداسازی داری Command به کار ببر، وگرنه یک صدازدن مستقیم ساده‌تر و خواناتر است."},{"k":"tip","title":"نکته منتور","t":"در طراحی undo، به‌جای ذخیره «عمل برعکس»، گاهی ذخیره «وضعیت قبل از عمل» ساده‌تر و مطمئن‌تر است؛ ولی اگر حالت خیلی بزرگ است، ذخیره عملِ معکوس (که Command اجازه می‌دهد) بهینه‌تر است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر عمل یک شیء با متد execute و undo","تاریخچه فرمان‌ها یعنی قابلیت بازگشت","گیرنده واقعی عمل از صادرکننده جدا می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"command.py","code":"class TypeText:\n    def __init__(self, doc, text):\n        self.doc, self.text = doc, text\n    def execute(self): self.doc.add(self.text)\n    def undo(self): self.doc.remove(self.text)\n\nhistory = [TypeText(doc, ''سلام'')]\nhistory[0].execute()\nhistory[0].undo()   # بازگشت"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر عمل یک شیء با متد execute و undo بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Command پیاده‌سازی undo را ساده می‌کند؟","opts":["سرعت","چون هر عمل شیء‌ای است که هم execute دارد هم undo؛ تاریخچه فرمان‌ها یعنی پشته بازگشت","کمتر حافظه","اجباری"],"ans":1,"why":"وقتی عمل یک شیء است، می‌توان آن را نگه داشت و بعداً undo‌اش را صدا زد؛ بدون آن باید هر عمل جدا منطق بازگشت داشت."},{"q":"Command چه چیزی را ممکن می‌کند که صدازدن مستقیم متد نمی‌کند؟","opts":["سرعت بیشتر","نگه‌داشتن درخواست به‌عنوان شیء؛ پس می‌توان آن را در صف گذاشت، لاگ کرد و لغو (undo) کرد","کد کوتاه‌تر","امنیت"],"ans":1,"why":"وقتی درخواست یک شیء است، می‌توانی مثل هر داده‌ای با آن رفتار کنی: ذخیره‌اش کنی، جابه‌جا کنی و بعداً اجرا یا برعکسش کنی — چیزی که با یک صدازدنِ لحظه‌ای ممکن نیست."},{"q":"چطور Command باعث جداسازی درخواست‌دهنده از اجراکننده می‌شود؟","opts":["با حذف اجراکننده","درخواست‌دهنده فقط یک شیء Command می‌سازد و اجراکننده جدا آن را انجام می‌دهد؛ پس این دو همدیگر را لازم ندارند","با کپی کد","ممکن نیست"],"ans":1,"why":"چون درخواست داخل یک شیء کپسوله شده، کسی که می‌سازدش لازم نیست بداند چه‌کسی و کی اجرا می‌کند؛ می‌توان اجرا را به صف، زمان‌بندی یا جای دیگر سپرد."}]'::jsonb),
('dp-b11', 'dp', 'Template Method', 56, 17, '[{"k":"p","t":"Template Method اسکلت یک الگوریتم را در متد پایه ثابت می‌کند و مراحل متغیر را به زیرکلاس‌ها می‌سپارد؛ ساختار یکی، جزئیات متفاوت."},{"k":"h","t":"Template Method؛ اسکلت ثابت، جزئیات متغیر"},{"k":"p","t":"گاهی چند عملیات داری که «ساختار کلی» یکسان ولی «جزئیات» متفاوت دارند؛ مثلاً تولید گزارش: همه گزارش‌ها داده را می‌خوانند، پردازش می‌کنند و خروجی می‌گیرند، ولی نوع داده و شکل خروجی فرق می‌کند. Template Method می‌گوید: اسکلت الگوریتم را در یک متد پایه ثابت کن (ترتیب مراحل) و مراحل متغیر را به صورت متدهای انتزاعی تعریف کن که زیرکلاس‌ها پیاده‌شان می‌کنند. آن‌وقت ساختار یکی است و فقط جزئیات در زیرکلاس‌ها عوض می‌شود."},{"k":"h","t":"جلوگیری از تکرار و حفظ ترتیب"},{"k":"p","t":"فایده Template Method این است که منطق مشترک (ترتیب مراحل، کارهای قبل و بعد) یک‌بار در پایه نوشته می‌شود و تکرار نمی‌شود؛ ضمن اینکه ترتیب اجرا هم تضمین می‌شود چون زیرکلاس نمی‌تواند آن را عوض کند — فقط می‌تواند جاهای خالی را پر کند. این الگو در فریم‌ورک‌ها زیاد است: فریم‌ورک اسکلت را می‌دهد و تو جاهای مشخص را پیاده می‌کنی (مثل متدهای چرخه حیات). به این «معکوس‌شدن کنترل» هم می‌گویند: این پایه است که تعیین می‌کند چه‌کسی و کی صدا زده شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کپی کد در هر عملیات","Template Method"],"rows":[["منطق مشترک","تکرار در همه‌جا","یک‌بار در پایه"],["ترتیب مراحل","ممکن است متفاوت شود","تضمین‌شده توسط پایه"],["تغییر جزئیات","دست‌زدن به هر کپی","فقط پیاده‌سازی متدهای انتزاعی"]]},{"k":"warn","title":"دام رایج","t":"Template Method را با Strategy اشتباه نگیر؛ در Template Method رابطه وراثت است و جزئیات در زیرکلاس‌ها ثابت می‌شود (زمان کامپایل)، ولی در Strategy ترکیب است و الگوریتم در اجرا عوض می‌شود. اگر نیاز به تعویض پویا داری، Strategy منعطف‌تر است."},{"k":"tip","title":"نکته منتور","t":"متدهای پایه در Template Method را معمولاً final (یا معادلش) کن تا زیرکلاس‌ها نتوانند اسکلت را عوض کنند؛ چون کل ارزش این الگو در این است که ساختار و ترتیب، ثابت و قابل‌اعتماد بماند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["مراحل مشترک در پایه، نقاط متغیر abstract","زیرکلاس فقط جاهای خالی را پر می‌کند","جلوگیری از کپی مراحل مشترک"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"template.py","code":"class Report:\n    def run(self):\n        self.collect()\n        self.format()\n        self.send()\n    def format(self): ...      # مشترک\n    def collect(self): raise NotImplementedError\n    def send(self): raise NotImplementedError\n# زیرکلاس فقط collect و send را پر می‌کند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: مراحل مشترک در پایه، نقاط متغیر abstract بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Template Method چه چیزی را ثابت و چه چیزی را متغیر نگه می‌دارد؟","opts":["همه","اسکلت و ترتیب مراحل را ثابت، مراحل متغیر را به زیرکلاس‌ها می‌سپارد","هیچ","فقط نام‌ها"],"ans":1,"why":"ترتیب collect→format→send برای همه گزارش‌ها یکی است؛ فقط چگونگی collect و send فرق می‌کند که زیرکلاس پر می‌کند."},{"q":"Template Method چه چیزی را ثابت و چه چیزی را متغیر نگه می‌دارد؟","opts":["همه را ثابت","اسکلت و ترتیب مراحل را ثابت در پایه؛ جزئیات هر مرحله را متغیر در زیرکلاس‌ها","همه را متغیر","جزئیات را ثابت"],"ans":1,"why":"پایه ترتیب کلی الگوریتم را تعیین و تضمین می‌کند و فقط جاهای مشخص (متدهای انتزاعی) را برای پیاده‌سازی زیرکلاس‌ها باز می‌گذارد؛ پس ساختار یکی است و جزئیات متفاوت."},{"q":"تفاوت Template Method و Strategy چیست؟","opts":["هیچ","Template Method با وراثت و جزئیات ثابت در زمان کامپایل؛ Strategy با ترکیب و تعویض الگوریتم در زمان اجرا","سرعت‌شان","یکی جدیدتر است"],"ans":1,"why":"اگر الگوریتم باید در اجرا عوض شود، Strategy منعطف‌تر است چون رابطه ترکیبی است؛ Template Method برای وقتی است که ساختار مشترک ثابت است و فقط جزئیات در زیرکلاس‌ها فرق می‌کند."}]'::jsonb),
('dp-b12', 'dp', 'انتخاب الگو و ضدالگوها', 56, 18, '[{"k":"p","t":"الگو ابزار است نه هدف؛ استفاده نابجا پیچیدگی می‌آورد. اول ساده‌ترین راه، و فقط وقتی مسئله واقعاً تکرار شد، الگو."},{"k":"h","t":"الگو ابزار است، نه هدف"},{"k":"p","t":"الگوهای طراحی راه‌حل‌های آزموده‌شده برای مسائل تکراری‌اند، ولی خودشان هدف نیستند. بزرگ‌ترین اشتباه تازه‌کارها این است که دنبال فرصتی بگردند تا الگو به کار ببرند؛ نتیجه، کدی است که برای یک مسئله ساده، چند لایه اینترفیس و کلاس اضافه دارد. قانون درست برعکس است: اول ساده‌ترین راه‌حل را بنویس، و فقط وقتی مسئله واقعاً تکرار شد و دردش را حس کردی، الگوی مناسب را بیاور. الگو باید بوی بد کد را درمان کند، نه از اول تجویز شود."},{"k":"h","t":"ضدالگوها؛ وقتی الگو زیاد می‌شود"},{"k":"p","t":"استفاده نابجا یا بیش‌ازحد الگو، خودش ضدالگو می‌شود. چند نمونه رایج: «God Class» یعنی یک کلاس که همه‌چیز را انجام می‌دهد (نتیجه ندادن مسئولیت‌ها)؛ «انتزاع زودهنگام» یعنی ساختن اینترفیس و لایه برای چیزی که فقط یک پیاده‌سازی دارد و شاید هیچ‌وقت دومی نیاید؛ و «الگوزدگی» یعنی پیچیدن یک کار ساده در چند الگوی پشت‌سرهم که فهمیدنش از نوشتنش سخت‌تر است. نشانه اینکه داری زیاده‌روی می‌کنی این است که برای توضیح یک بخش ساده کد، مجبوری سه الگو را نام ببری."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ضدالگو","نشانه","درمان"],"rows":[["God Class","یک کلاس همه‌کاره و پرمسئولیت","تقسیم بر اساس مسئولیت"],["انتزاع زودهنگام","اینترفیس برای یک پیاده‌سازی","صبر تا نیاز واقعی"],["الگوزدگی","کار ساده در چند لایه الگو","ساده‌ترین راه اول"]]},{"k":"warn","title":"دام رایج","t":"اگر برای اضافه‌کردن یک قابلیت ساده باید چهار فایل و دو اینترفیس جدید بسازی، یک لحظه بایست و بپرس «آیا واقعاً این انعطاف لازم است؟» خیلی‌وقت‌ها یک تغییر کوچک مستقیم، خواناتر و قابل‌نگه‌داری‌تر از یک معماری ازپیش‌ساخته برای نیازی است که شاید هیچ‌وقت نیاید."},{"k":"tip","title":"نکته منتور","t":"قانون YAGNI (به آن نیاز نداری) را جدی بگیر: برای نیازهای فرضیِ آینده کد نزن. الگوها را خوب یاد بگیر تا وقتی مسئله واقعی‌اش آمد بشناسیش، ولی زودتر از موعد اجراشان نکن."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["قاعده سه: سومین تکرار که شد، انتزاع کن","Singleton زیاد و Factory بی‌مورد بوی بدند","الگو برای خوانایی تیم است؛ اگر گنگ‌تر کرد، اشتباه است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"قاعده سه","code":"اول:  کد ساده مستقیم\nدوم:  کپی قابل‌قبول است\nسوم:  حالا انتزاع کن (الگو)\n— انتزاع زودتر از وقت، حدسِ اشتباه را میخکوب می‌کند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: قاعده سه: سومین تکرار که شد، انتزاع کن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا نباید الگو را از قبل و «برای روز مبادا» اضافه کرد؟","opts":["کند","چون تا مسئله واقعی تکرار نشده، احتمالاً ساختار اشتباه را حدس می‌زنی و پیچیدگی بی‌فایده می‌سازی","اجباری","ممکن نیست"],"ans":1,"why":"انتزاع زودهنگام بر اساس حدس است؛ وقتی مسئله واقعی سومین بار تکرار شد، تازه می‌فهمی انتزاع درست چیست."},{"q":"کی باید از یک الگوی طراحی استفاده کرد؟","opts":["همیشه","وقتی مسئله واقعاً تکرار شده و دردش حس شده؛ نه از اول و برای نیاز فرضی","وقتی کد کوتاه می‌شود","هیچ‌وقت"],"ans":1,"why":"الگو برای درمان بوی بدِ واقعی است؛ استفاده زودهنگام برای مسئله‌ای که نیامده، فقط پیچیدگی اضافه می‌کند. اول ساده‌ترین راه، و الگو فقط وقتی مسئله تکرار شد."},{"q":"«انتزاع زودهنگام» چه ضدالگویی است؟","opts":["ساختن کلاس بزرگ","ساختن اینترفیس و لایه‌های اضافی برای چیزی که فقط یک پیاده‌سازی دارد و شاید دومی نیاید","کپی کد","حذف تست"],"ans":1,"why":"اگر فقط یک پیاده‌سازی داری و مشخص نیست اصلاً دومی بیاید، اینترفیس جدا فقط یک لایه اضافه است که هیچ انعطافی نمی‌دهد ولی فهم و تغییر کد را سخت می‌کند."}]'::jsonb),
('net-r1', 'net', 'HTTP؛ قراردادی که وب را ساخت', 55, 1, '[{"k":"p","t":"هر بار که صفحه‌ای باز می‌کنی، ده‌ها گفتگوی کوتاه و بی‌حافظه بین مرورگرت و سرورها رد و بدل می‌شود. HTTP قواعد این گفتگوست؛ و با وجود سادگی‌اش، فهمیدنش یعنی فهمیدن نیمی از مشکلات وب — از «چرا لاگینم پرید» تا «چرا کش درست کار نمی‌کند»."},{"k":"h","t":"بی‌حالت بودن؛ طراحی، نه کمبود"},{"k":"p","t":"هر درخواست HTTP مستقل است؛ سرور به‌خودی‌خود نمی‌داند این درخواست از همان کسی است که یک ثانیه پیش آمد. این «بی‌حالتی» شاید ضعف به‌نظر برسد، ولی دلیل مقیاس‌پذیری وب است: سرور لازم نیست بین درخواست‌ها چیزی نگه دارد و می‌تواند میلیون‌ها را پاسخ دهد. همه مفاهیمی مثل Session، کوکی و JWT، راه‌حل‌هایی‌اند که «حالت» را روی این پروتکل بی‌حالت سوار می‌کنند."},{"k":"h","t":"متدها؛ فعل‌های درخواست"},{"k":"p","t":"متد HTTP، «نیت» درخواست را می‌گوید: GET برای گرفتن بدون اثر جانبی، POST برای ساختن، PUT برای جایگزینی کامل، PATCH برای تغییر جزئی و DELETE برای حذف. رعایت این معناها فقط زیبایی نیست؛ مثلاً GET باید امن و قابل‌تکرار باشد تا کش‌ها و مرورگرها بتوانند آزادانه آن را ذخیره و بازپخش کنند. متدی که با معنایش جور نباشد، کش و retry را خراب می‌کند."},{"k":"h","t":"کدهای وضعیت؛ پاسخِ خلاصه"},{"k":"p","t":"هر پاسخ با یک عدد سه‌رقمی شروع می‌شود که سرنوشت کل درخواست را لو می‌دهد: 2xx یعنی موفق، 3xx یعنی جابه‌جا شو، 4xx یعنی اشکال از توست (کلاینت) و 5xx یعنی اشکال از ماست (سرور). دانستن تفاوت 401 (کی هستی؟ نمی‌دانم) و 403 (می‌دانم کی هستی ولی اجازه نداری) یا 404 (چنین چیزی نیست) و 500 (خودم خرابم)، در طراحی API و دیباگ، تفاوت روز و شب است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"http.txt","code":"GET /courses/42 HTTP/1.1\nHost: bitcode.academy\nAccept: application/json\nAuthorization: Bearer <token>\n\nHTTP/1.1 200 OK\nContent-Type: application/json\nCache-Control: max-age=300\n\n{ \"id\": 42, \"title\": \"ساختمان داده\", \"hours\": 30 }"},{"k":"list","items":["خط اول یعنی «با متد GET، این منبع را از این میزبان بده»؛ بقیه خط‌های بالا سربرگ‌اند که متادیتا می‌فرستند.","Authorization حامل توکن است؛ چون HTTP بی‌حالت است، هویت باید با هر درخواست دوباره فرستاده شود.","پاسخ با 200 یعنی موفقیت؛ Cache-Control می‌گوید تا ۵ دقیقه می‌توان این پاسخ را کش کرد و دوباره نپرسید."]},{"k":"def","term":"منبع (Resource) و URL","t":"در HTTP همه‌چیز «منبع» است که با URL نشانی می‌شود؛ متد تعیین می‌کند با آن منبع چه می‌کنیم. این مدل (منبع + فعل) پایه REST است: به‌جای RPCهای پراکنده، API مجموعه‌ای از منابع می‌شود که با متدهای استاندارد دستکاری می‌شوند."},{"k":"table","head":["متد","معنا","ایمن/تکرارپذیر"],"rows":[["GET","گرفتن منبع","هر دو — کش‌پذیر"],["POST","ساختن","هیچ‌کدام"],["PUT","جایگزینی کامل","تکرارپذیر"],["DELETE","حذف","تکرارپذیر"]]},{"k":"warn","title":"دام رایج","t":"انجام عملِ تغییردهنده با GET (مثل حذف با لینک)؛ چون مرورگرها، خزنده‌ها و کش‌ها آزادند GET را پیش‌واکنش و تکرار کنند، ممکن است داده‌ات ناخواسته چندبار تغییر کند. عملِ تغییردهنده همیشه باید با POST/PUT/DELETE و از طریق فرم یا API باشد."},{"k":"tip","title":"نکته حرفه‌ای","t":"هنگام طراحی API، برای هر خطا کد وضعیت درست برگردان نه 200 با یک فیلد error؛ کلاینت‌ها و ابزارها (و خودت هنگام دیباگ) به این کدها متکی‌اند و یک API که همه‌چیز را 200 می‌گوید، عملاً غیرقابل‌دیباگ است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["HTTP بی‌حالت است؛ حالت با کوکی/توکن سوار می‌شود","متد، نیت درخواست است؛ GET باید امن و تکرارپذیر باشد","کدهای 4xx خطای کلاینت و 5xx خطای سرورند","عمل تغییردهنده را هرگز با GET انجام نده"]}]'::jsonb, '[{"q":"چرا HTTP «بی‌حالت» طراحی شده و این چه مزیتی دارد؟","opts":["کمبود بود","مقیاس‌پذیری: سرور بین درخواست‌ها چیزی نگه نمی‌دارد و می‌تواند میلیون‌ها را پاسخ دهد","برای امنیت","برای سرعت شبکه"],"ans":1,"why":"بی‌حالتی یعنی هر سرور می‌تواند هر درخواست را مستقل پاسخ دهد؛ Session و توکن، حالت را روی آن سوار می‌کنند."},{"q":"تفاوت 401 و 403 چیست؟","opts":["هیچ","۴۰۱ یعنی هویت نامشخص است؛ ۴۰۳ یعنی هویت معلوم است ولی اجازه ندارد","۴۰۳ سخت‌تر است","۴۰۱ برای سرور است"],"ans":1,"why":"۴۰۱ پرسش «کی هستی؟» است (ورود لازم)؛ ۴۰۳ پاسخ «می‌دانم ولی اجازه نداری» (نقش/مجوز کم است)."},{"q":"چرا GET باید تکرارپذیر و بدون اثر جانبی باشد؟","opts":["سلیقه‌ای","تا کش‌ها، مرورگرها و خزنده‌ها بتوانند آزادانه آن را ذخیره و بازپخش کنند بدون اینکه چیزی تغییر کند","برای سرعت","اجباری نیست"],"ans":1,"why":"اگر GET اثر جانبی داشت، یک prefetch یا بازپخش کش می‌توانست ناخواسته داده را تغییر دهد."}]'::jsonb),
('net-r2', 'net', 'TCP؛ چگونه از یک لوله غیرقابل‌اعتماد، تحویل مطمئن می‌سازیم', 60, 2, '[{"k":"p","t":"IP فقط بسته‌ها را پرتاب می‌کند؛ ممکن است گم شوند، تکراری برسند یا به‌هم‌ریخته. TCP روی همین پایه سست، یک کانال قابل‌اتکا می‌سازد — و مکانیزم‌هایش (دست‌دادن، شماره ترتیب، ACK، کنترل ازدحام) دقیقاً همان الگوهایی‌اند که در طراحی سیستم توزیع‌شده دوباره با آن‌ها روبه‌رو می‌شوی."},{"k":"h","t":"سه‌راهی دست‌دادن؛ توافق قبل از حرف‌زدن"},{"k":"p","t":"قبل از هر داده، دو طرف با سه پیام اتصال را می‌سازند: کلاینت SYN می‌فرستد (می‌خواهم وصل شوم، شماره ترتیب من X)، سرور با SYN-ACK جواب می‌دهد (قبول، شماره من Y و تأیید X+1) و کلاینت با ACK می‌بندد (X+1 و Y+1 را گرفتم). این سه پیام فقط تشریفات نیست؛ دو طرف با آن شماره‌های ترتیب اولیه را هماهنگ می‌کنند تا بتوانند بعداً بفهمند کدام بایت رسیده و کدام نه. بدون این توافق، در دنیایی که بسته‌ها می‌پرند، هیچ تضمینی ممکن نیست."},{"k":"h","t":"شماره ترتیب و ACK؛ ستون فقرات اعتماد"},{"k":"p","t":"هر بایت داده یک شماره ترتیب دارد و گیرنده با ACK می‌گوید «تا بایت شماره N را گرفتم، بعدی را بفرست». اگر بسته‌ای نرسد، ACK همان عدد قبلی تکرار می‌شود و فرستنده می‌فهمد باید از همان‌جا دوباره بفرستد (بازفرستادن). چون گیرنده بر اساس شماره مرتب می‌کند، بسته‌های به‌هم‌ریخته هم درست سرِ جای خود می‌نشینند. همین دو عدد ساده، تحویلِ به‌ترتیب و بدون‌تکرار را از دل یک شبکه آشفته بیرون می‌کشند."},{"k":"h","t":"کنترل ازدحام؛ عقب‌نشینی هوشمند"},{"k":"p","t":"TCP فقط به گم‌شدن بسته توجه نمی‌کند؛ سرعت فرستادن را هم با وضعیت شبکه تنظیم می‌کند. با Slow Start از سرعت کم شروع و تا وقتی بسته‌ای گم نشده exponentially زیاد می‌کند؛ به‌محض گم‌شدن بسته (نشانه ازدحام)، سرعت را نصف یا کم می‌کند و دوباره آرام بالا می‌رود. این «AIMD» یعنی افزایش جمعی، کاهش ضربی، همان چیزی است که اینترنت را از فروپاشی زیر بار نجات می‌دهد — و الگوی rate limiting و backpressure در نرم‌افزار هم از همین‌جا آمده."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"tcp-handshake.txt","code":"Client                            Server\n  | ---- SYN  (seq=1000) ---------> |\n  | <--- SYN-ACK (seq=5000, ack=1001) |\n  | ---- ACK (ack=5001) ----------> |\n  |        [اتصال برقرار]\n  | ---- DATA (seq=1001,len=200) --> |\n  | <--- ACK (ack=1201) ------------ |\n  | ---- FIN -----------------------> |\n  | <--- ACK / FIN ------------------ |"},{"k":"list","items":["سه پیام اول (SYN، SYN-ACK، ACK) اتصال را می‌سازند و شماره‌های ترتیب دو طرف را همگام می‌کنند.","DATA با seq=1001 و طول 200 یعنی بایت‌های 1001 تا 1200؛ پاسخ ACK=1201 یعنی «بعدی را از 1201 بفرست».","FIN برای بستن مهربانانه اتصال است؛ هر دو طرف باید آن را تأیید کنند تا اتصال کاملاً بسته شود."]},{"k":"def","term":"کنترل ازدحام (Congestion Control)","t":"مکانیزمی که سرعت ارسال را بر اساس نشانه‌های ازدحام شبکه (گم‌شدن بسته یا تأخیر) کم‌وزیاد می‌کند تا کل شبکه زیر بار خفه نشود. تفاوتش با کنترل جریان (Flow Control) این است که دومی فقط ظرفیت «گیرنده» را در نظر می‌گیرد، نه شبکه را."},{"k":"table","head":["مکانیزم","چه چیزی را حل می‌کند"],"rows":[["SYN / SYN-ACK / ACK","هماهنگ‌سازی شماره‌ها و ساخت اتصال"],["Sequence + ACK","تحویل به‌ترتیب، بدون تکرار، با بازفرستادن"],["Flow Control (Window)","فرستنده سریع‌تر از ظرفیت گیرنده نفرستد"],["Congestion Control","شبکه زیر بار خفه نشود"]]},{"k":"warn","title":"دام رایج","t":"فرض‌کردن اینکه «چون TCP قابل‌اتکاست، نیازی به timeout و retry در لایه اپلیکیشن نیست». TCP تحویل را تضمین می‌کند، اما نه «به‌موقع رسیدن» را؛ یک اتصال مرده ممکن است تا دقایق باز بماند. پس همیشه برای عملیات شبکه timeout و برای عملیات مهم Idempotency + retry طراحی کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"مفهوم Idempotency که در TCP (شماره ترتیب، بازفرستادن امن) می‌بینی، همان است که در APIهای واقعی لازم داری: عملیاتی که تکرارش اثر اضافه ندارد. وقتی retry می‌کنی، باید مطمئن باشی تکرار درخواست، پول را دوبار کم نمی‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["TCP روی IP غیرقابل‌اعتماد، با SYN/SYN-ACK/ACK اتصال و با seq/ACK اعتماد می‌سازد.","بازفرستادن بر اساس ACK تکراری و مرتب‌سازی بر اساس شماره ترتیب انجام می‌شود.","کنترل ازدحام (Slow Start + AIMD) سرعت را با وضعیت شبکه تنظیم می‌کند.","قابلیت‌اعتماد TCP جای timeout و idempotency در لایه اپلیکیشن را نمی‌گیرد."]}]'::jsonb, '[{"q":"اگر بسته DATA در TCP گم شود، چه اتفاقی می‌افتد؟","opts":["اتصال قطع می‌شود","گیرنده ACK قبلی را تکرار می‌کند و فرستنده از همان نقطه دوباره می‌فرستد","بسته برای همیشه از دست می‌رود","سرور ارور می‌دهد"],"ans":1,"why":"گیرنده چون بایت بعدی را نگرفته، همان ACK قبلی را می‌فرستد؛ فرستنده با دیدن ACK تکراری متوجه گم‌شدن می‌شود و بازفرستادن می‌کند."},{"q":"تفاوت Flow Control و Congestion Control چیست؟","opts":["فرقی ندارند","اولی ظرفیت گیرنده را رعایت می‌کند، دومی وضعیت کل شبکه را","دومی فقط برای UDP است","اولی در لایه فیزیکی است"],"ans":1,"why":"Flow Control (پنجره دریافت) می‌گوید گیرنده چقدر جا دارد؛ Congestion Control می‌گوید شبکه چقدر شلوغ است. دو مسئله جدا که TCP هر دو را حل می‌کند."},{"q":"چرا Slow Start سرعت را از کم شروع می‌کند؟","opts":["برای صرفه‌جویی باتری","چون نمی‌داند شبکه چقدر ظرفیت دارد؛ تا وقتی نشانه ازدحام نبیند زیاد می‌کند","محدودیت سخت‌افزاری","برای امنیت"],"ans":1,"why":"فرستنده اطلاعاتی از مسیر ندارد؛ با کم شروع و exponential زیاد می‌کند تا به‌محض اولین گم‌شدن (نشانه ازدحام) عقب‌نشینی کند."}]'::jsonb),
('net-r3', 'net', 'IP، زیرشبکه و CIDR؛ ریاضیاتی که شبکه را تقسیم می‌کند', 55, 3, '[{"k":"p","t":"هر دستگاه برای حرف‌زدن باید بداند «مقصد همسایه‌ام است یا باید به روتر بسپارمش؟» جواب این سوال را Subnet Mask می‌دهد. فهمیدن subnetting یعنی فهمیدن اینکه IPها چطور گروه‌بندی می‌شوند — و این مهارتی است که در تنظیم سرور، داکر، کوبرنتیز و ابر همیشه لازم می‌شود."},{"k":"h","t":"آدرس IP و دو بخشش"},{"k":"p","t":"هر آدرس IPv4 سی‌ودو بیت است و به دو بخش تقسیم می‌شود: پیشوند شبکه (که همه اعضای یک زیرشبکه در آن مشترک‌اند) و بخش میزبان (که هر دستگاه را متمایز می‌کند). مرز این دو را Subnet Mask یا در نوشتار مدرن، CIDR (مثل /24) مشخص می‌کند. /24 یعنی ۲۴ بیت اول شبکه و ۸ بیت میزبان — پس ۲ به توان ۸ منهای ۲ یعنی ۲۵۴ میزبان قابل‌استفاده (دو تا کم می‌شود: آدرس شبکه و broadcast)."},{"k":"h","t":"محاسبه عملی با AND"},{"k":"p","t":"برای پیدا کردن آدرس شبکه، IP را با mask بیت‌به‌بیت AND می‌کنیم. مثلاً 192.168.1.50 با mask /24 (یعنی 255.255.255.0) می‌شود 192.168.1.0 — آدرس شبکه. آدرس broadcast آخرین آدرس (192.168.1.255) و بازه قابل‌استفاده بین این دو است. اگر دو دستگاه mask یکسان داشته باشند و آدرس شبکه‌شان یکی باشد، مستقیم با هم حرف می‌زنند؛ وگرنه بسته به gateway می‌رود."},{"k":"h","t":"چرا زیرشبکه‌بندی؟"},{"k":"p","t":"تقسیم شبکه به زیرشبکه‌های کوچک‌تر سه فایده دارد: امنیت (جداسازی سرورها از کلاینت‌ها)، کاهش ترافیک broadcast (پیام‌های همگانی محدود به زیرشبکه می‌مانند) و مدیریت ساده‌تر. در ابر و کوبرنتیز هم مدام با این مفهوم سروکار داری: هر Pod یک IP از یک بلاک CIDR می‌گیرد و سرویس‌ها با rangeهای مشخص از هم جدا می‌شوند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"subnet.txt","code":"آدرس:   192.168.1.50/24\nMask:   255.255.255.0   (۲۴ بیت شبکه)\n\nآدرس شبکه:    192.168.1.0\nBroadcast:    192.168.1.255\nاولین میزبان: 192.168.1.1\nآخرین میزبان: 192.168.1.254\nتعداد میزبان: 2^8 - 2 = 254"},{"k":"list","items":["/24 یعنی ۸ بیت میزبان؛ پس 256 آدرس داریم که 2 تای آن (شبکه و broadcast) مصرف می‌شود.","آدرس شبکه با AND کردن IP و mask به‌دست می‌آید؛ همه میزبان‌های این زیرشبکه در سه اُکتت اول مشترک‌اند.","میزبان‌های 1 تا 254 قابل‌استفاده‌اند؛ معمولی .1 به gateway و .254 به سرورها داده می‌شود."]},{"k":"def","term":"CIDR (Classless Inter-Domain Routing)","t":"نوشتار فشرده‌ای که طول پیشوند شبکه را با اسلش نشان می‌دهد (مثل /16 یا /28) و جایگزین کلاس‌های قدیمی A/B/C شده. انعطافش اجازه می‌دهد شبکه را به هر اندازه‌ای که لازم است تقسیم یا تجمیع کنی — پایه مسیریابی مقیاس‌پذیر اینترنت."},{"k":"table","head":["CIDR","بیت میزبان","میزبان قابل‌استفاده"],"rows":[["/24","8","254"],["/25","7","126"],["/26","6","62"],["/28","4","14"]]},{"k":"warn","title":"دام رایج","t":"انتخاب شبکه‌های خیلی بزرگ (مثل /8) برای یک LAN کوچک. علاوه بر هدررفتن آدرس، broadcast domain بزرگ یعنی ترافیک همگانیِ زیاد و امنیت کمتر. همیشه کوچک‌ترین بلاکی که با کمی حاشیه رشد کافی است را انتخاب کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای محاسبه سریع سرانگشتی: هر بار که عدد CIDR یکی زیاد می‌شود، تعداد میزبان‌ها نصف می‌شود. پس /25 نصف /24 است (126) و /26 نصف آن (62). این رابطه نصف‌شوندگی را که حفظ کنی، بیشتر محاسبات را بدون ماشین‌حساب انجام می‌دهی."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["IP به پیشوند شبکه + بخش میزبان تقسیم می‌شود؛ مرز را mask/CIDR تعیین می‌کند.","آدرس شبکه با AND به‌دست می‌آید؛ اولین و آخرین آدرس (شبکه و broadcast) مصرف می‌شوند.","زیرشبکه‌بندی برای امنیت، کاهش broadcast و مدیریت است.","هر +1 در CIDR، تعداد میزبان را نصف می‌کند."]}]'::jsonb, '[{"q":"در شبکه 192.168.1.50/24، آدرس broadcast چیست؟","opts":["192.168.1.0","192.168.1.255","192.168.1.254","192.168.1.1"],"ans":1,"why":"با /24 سه اُکتت اول شبکه است؛ broadcast آخرین آدرس یعنی همه بیت‌های میزبان یک → 192.168.1.255."},{"q":"چرا در یک /24 فقط 254 میزبان قابل‌استفاده است نه 256؟","opts":["محدودیت سخت‌افزاری","چون آدرس شبکه و broadcast رزرو می‌شوند","دو تا برای gateway است","خطای محاسباتی"],"ans":1,"why":"آدرس شبکه (همه میزبان صفر) و broadcast (همه میزبان یک) به خودِ شبکه اختصاص دارند و به هیچ میزبانی داده نمی‌شوند."},{"q":"اگر دو میزبان mask یکسان ولی آدرس شبکه متفاوت داشته باشند، چه می‌شود؟","opts":["مستقیم با هم حرف می‌زنند","بسته‌ها باید از gateway/روتر عبور کنند","اتصال برقرار نمی‌شود","IPها تداخل می‌کنند"],"ans":1,"why":"وقتی آدرس شبکه متفاوت است یعنی در زیرشبکه‌های جدا هستند؛ پس بسته نمی‌تواند مستقیم برود و باید به روتر (gateway) سپرده شود تا مسیریابی کند."}]'::jsonb),
('net-r4', 'net', 'DNS عمیق؛ رکوردها، بازگشت و امنیت', 55, 4, '[{"k":"p","t":"وقتی آدرسی را تایپ می‌کنی، قبل از هر چیز یک پرس‌وجوی DNS راه می‌افتد تا نام را به IP تبدیل کند. اگر DNS کند باشد یا مسموم شود، کل تجربه وب با آن خراب می‌شود. فهمیدن رکوردها و چرخه resolution برای هر کسی که دامنه، ایمیل یا API مدیریت می‌کند ضروری است."},{"k":"h","t":"انواع رکورد؛ هرکدام یک کار"},{"k":"p","t":"رکورد A نام را به IPv4 و AAAA به IPv6 وصل می‌کند. CNAME یک نام را مستعار نام دیگر می‌کند (www → example.com). رکورد MX مشخص می‌کند ایمیل‌های دامنه به کدام سرور بروند و TXT برای تأیید مالکیت و تنظیمات امنیتی ایمیل (SPF/DKIM) استفاده می‌شود. وقتی «سایت بالا نمی‌آید ولی پینگ IP می‌خورد»، معمولاً مشکل همین رکوردهاست."},{"k":"h","t":"چرخه بازگشتی و نقش TTL"},{"k":"p","t":"کلاینت از resolver محلی می‌پرسد؛ اگر نداند، resolver از ریشه (.) شروع و پله‌پله (TLD بعد دامنه) می‌پرسد تا جواب را بگیرد و کش کند. TTL می‌گوید این جواب چند ثانیه معتبر است؛ TTL کوتاه یعنی تغییرات سریع پخش می‌شود ولی پرس‌وجو بیشتر، TTL بلند یعنی بار کمتر ولی تغییرات دیر می‌رسند. قبل از مهاجرت سرور، TTL را پایین بیاور تا سوئیچ سریع‌تر اتفاق بیفتد."},{"k":"h","t":"امنیت DNS؛ از مسموم‌سازی تا DNSSEC"},{"k":"p","t":"DNS اولیه هیچ احراز هویتی نداشت؛ مهاجم می‌توانست جواب جعلی بفرستد و کاربر را به سایت خودش ببرد (مسموم‌سازی یا cache poisoning). DNSSEC با امضای رمزنگاری، صحت جواب را تأیید می‌کند. و برای محرمانگی پرس‌وجوها (که کسی نبیند کجا می‌روی) از DoH (DNS over HTTPS) و DoT استفاده می‌شود. دانستن این‌ها هنگام انتخاب resolver و تنظیم دامنه حیاتی است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"dig.sh","code":"# دیدن رکورد A و TTL\ndig example.com A\n\n# رکورد MX (سرور ایمیل)\ndig example.com MX +short\n\n# پرس‌وجو از یک resolver خاص\ndig @8.8.8.8 example.com\n\n# دنبال‌کردن کل زنجیره resolution\ndig example.com +trace"},{"k":"list","items":["dig پیش‌فرض رکورد A را می‌پرسد و در بخش answer، TTL را نشان می‌دهد.","+short فقط مقدار را چاپ می‌کند؛ برای اسکریپت‌نویسی راحت‌تر است.","+trace کل مسیر از ریشه تا جواب را قدم‌به‌قدم نشان می‌دهد — بهترین ابزار برای فهمیدن اینکه resolution کجا گیر کرده."]},{"k":"def","term":"Resolver بازگشتی (Recursive Resolver)","t":"سروری که به‌جای کلاینت، کل زنجیره پرس‌وجو (از ریشه تا دامنه) را طی می‌کند و جواب نهایی را برمی‌گرداند و کش می‌کند. resolverهای عمومی مثل 8.8.8.8 یا 1.1.1.1 از این نوع‌اند و بار resolution را از دوش کلاینت و سرورهای ریشه برمی‌دارند."},{"k":"table","head":["رکورد","کاربرد"],"rows":[["A / AAAA","نام به IPv4 / IPv6"],["CNAME","مستعار کردن یک نام به نام دیگر"],["MX","مشخص‌کردن سرور ایمیل دامنه"],["TXT","تأیید مالکیت و تنظیمات SPF/DKIM"],["NS","سرورهای DNS مسئول دامنه"]]},{"k":"warn","title":"دام رایج","t":"تغییر IP سرور با TTL بلند و انتظار بالاآمدن فوری. تا وقتی TTL قبلی در resolverها زنده است، کاربران به IP قدیم می‌روند. قبل از مهاجرت، TTL را چند ساعت زودتر پایین بیاور و بعد از سوئیچ دوباره بالا ببر."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی «برای من باز می‌شود ولی برای کاربر نه»، اول کش DNS را شک کن: dig با +short از چند resolver مختلف بپرس و با flush-dns محلی مقایسه کن. نیمی از مشکلات «سایت پایین است» در واقع مشکل resolution یا کش است، نه خود سرور."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هر نوع رکورد (A، CNAME، MX، TXT، NS) کار مشخصی دارد.","Resolver به‌صورت بازگشتی از ریشه تا دامنه می‌پرسد و TTL عمر کش را تعیین می‌کند.","DNSSEC صحت و DoH/DoT محرمانگی پرس‌وجوها را تأمین می‌کنند.","قبل از مهاجرت، TTL را پایین بیاور."]}]'::jsonb, '[{"q":"برای وصل‌کردن www.example.com به example.com از کدام رکورد استفاده می‌شود؟","opts":["A","MX","CNAME","TXT"],"ans":2,"why":"CNAME یک نام را مستعار نام دیگر می‌کند؛ پس www به‌عنوان alias به example.com اشاره می‌کند و با تغییر A اصلی، هر دو به‌روز می‌مانند."},{"q":"TTL پایین چه فایده و هزینه‌ای دارد؟","opts":["فقط فایده","تغییرات سریع پخش می‌شود ولی پرس‌وجوی DNS بیشتر می‌شود","فقط هزینه","سرعت سایت را بالا می‌برد"],"ans":1,"why":"TTL کوتاه یعنی کش زود منقضی می‌شود و تغییر IP سریع دیده می‌شود، ولی چون جواب کمتر کش می‌ماند، تعداد پرس‌وجوها و بار روی DNS بیشتر می‌شود."},{"q":"DNSSEC چه چیزی را حل می‌کند؟","opts":["سرعت DNS","تأیید صحت جواب DNS در برابر جعل","رمزکردن محتوای سایت","فشرده‌سازی"],"ans":1,"why":"DNSSEC جواب‌ها را امضای رمزنگاری می‌کند تا resolver مطمئن شود جواب از مرجع واقعی آمده و وسط راه جعل نشده — دفاع در برابر cache poisoning."}]'::jsonb),
('net-r5', 'net', 'TLS؛ رمزنگاری، گواهی و دست‌دادن HTTPS', 60, 5, '[{"k":"p","t":"HTTPS یعنی HTTP داخل یک تونل امن به نام TLS. بدون آن، هر کلمه عبور و توکنی که می‌فرستی برای هر شنودکننده‌ای در مسیر قابل‌خواندن است. فهمیدن اینکه TLS چطور با ترکیب رمزنگاری متقارن و نامتقارن، هم امنیت و هم سرعت را به‌دست می‌آورد، برای هر مهندس بک‌اند واجب است."},{"k":"h","t":"چرا ترکیب متقارن و نامتقارن؟"},{"k":"p","t":"رمزنگاری متقارن (یک کلید مشترک) سریع است ولی مشکلش این است که دو طرف چطور بدون اینکه کسی بفهمد، آن کلید را ردوبدل کنند. رمزنگاری نامتقارن (جفت عمومی/خصوصی) این مشکل را حل می‌کند ولی کند است. TLS هوشمندانه ترکیب می‌کند: با نامتقارن (یا بهتر، با تبادل کلید Diffie-Hellman) یک کلید متقارنِ جلسه را امن ردوبدل می‌کند و بعد همه داده‌ها را با همان کلید متقارنِ سریع رمز می‌کند."},{"k":"h","t":"گواهی و زنجیره اعتماد"},{"k":"p","t":"TLS فقط رمز نمی‌کند؛ هویت سرور را هم تأیید می‌کند. سرور گواهی‌اش را می‌فرستد که شامل دامنه و کلید عمومی‌اش است و توسط یک CA معتبر امضا شده. مرورگر زنجیره امضا را تا یک CA ریشه که از قبل به آن اعتماد دارد چک می‌کند و می‌بیند دامنه گواهی با آدرس درخواستی یکی است. اگر گواهی خودامضا یا منقضی باشد، هشدار می‌دهد — چون بدون این تأیید، هر MITM می‌توانست خودش را جای سرور جا بزند."},{"k":"h","t":"دست‌دادن مدرن و Perfect Forward Secrecy"},{"k":"p","t":"در TLS 1.3 دست‌دادن به یک رفت‌وبرگشت (1-RTT) کاهش یافته و رمزنگاری زودتر شروع می‌شود. ویژگی مهم «پیش‌رو ایمنی» است: کلید جلسه برای هر اتصال جدا تولید می‌شود و از کلید خصوصی سرور مشتق نمی‌شود؛ پس حتی اگر کلید خصوصی سرور بعداً لو برود، ترافیک ضبط‌شده قبلی قابل‌رمزگشایی نیست. این همان چیزی است که TLS 1.3 را از نسخه‌های قدیمی متمایز می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"tls.sh","code":"# دیدن گواهی و جزئیات دست‌دادن\nopenssl s_client -connect example.com:443 -brief\n\n# بررسی نسخه TLS و cipher\ncurl -v https://example.com 2>&1 | grep -E ''TLS|SSL''\n\n# چک‌کردن زنجیره گواهی\nopenssl s_client -connect example.com:443 -showcerts"},{"k":"list","items":["s_client یک اتصال TLS واقعی برقرار می‌کند و گواهی سرور و نسخه توافق‌شده را نشان می‌دهد.","خروجی -v در curl نشان می‌دهد کدام نسخه TLS (مثلاً TLSv1.3) و کدام cipher suite انتخاب شده.","-showcerts کل زنجیره (گواهی سرور + CAهای میانی) را چاپ می‌کند تا ببینی آیا زنجیره کامل است یا نه."]},{"k":"def","term":"Cipher Suite","t":"مجموعه‌ای از الگوریتم‌های توافق‌شده برای یک اتصال: تبادل کلید، احراز هویت، رمزنگاری متقارن و هش. مثلاً TLS_AES_128_GCM_SHA256 یعنی AES-128 در حالت GCM با SHA256. سرور و کلاینت در دست‌دادن، قوی‌ترین suite مشترک را انتخاب می‌کنند."},{"k":"table","head":["نسخه","وضعیت"],"rows":[["SSL 3.0 / TLS 1.0 / 1.1","منسوخ و ناامن — غیرفعال کن"],["TLS 1.2","سالم و رایج"],["TLS 1.3","بهترین: سریع‌تر، امن‌تر، PFS پیش‌فرض"]]},{"k":"warn","title":"دام رایج","t":"اجازه‌دادن نسخه‌های قدیمی TLS (1.0/1.1) برای سازگاری با کلاینت‌های خیلی قدیمی. این نسخه‌ها حمله‌های شناخته‌شده دارند و یک کلاینت قدیمی نباید بهانه‌ای برای به‌خطر‌انداختن همه باشد. TLS 1.2 به بالا را اجباری کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"با Let''s Encrypt و certbot، گرفتن و تمدید خودکار گواهی رایگان چند دقیقه کار است؛ امروز هیچ بهانه‌ای برای HTTP خالی وجود ندارد. بعد از نصب، حتماً redirect خودکار HTTP→HTTPS و هدر HSTS را فعال کن تا مرورگر اصلاً HTTP را امتحان نکند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["TLS با ترکیب نامتقارن (برای کلید) و متقارن (برای داده) هم امن و هم سریع است.","گواهی، هویت سرور را با زنجیره اعتماد CA تأیید می‌کند.","TLS 1.3 با 1-RTT سریع‌تر و با PFS امن‌تر است.","نسخه‌های قدیمی را غیرفعال و HTTPS + HSTS را اجباری کن."]}]'::jsonb, '[{"q":"چرا TLS از رمزنگاری متقارن برای داده‌ها استفاده می‌کند؟","opts":["امن‌تر است","چون سریع‌تر است و فقط برای ردوبدل کلید جلسه از نامتقارن استفاده می‌شود","ارزان‌تر","اجباری استاندارد"],"ans":1,"why":"رمز متقارن برای حجم زیاد داده بسیار سریع‌تر است؛ نامتقارن فقط در شروع برای انتقال امن کلید جلسه به‌کار می‌رود. ترکیب هر دو، بهترینِ هر دو دنیاست."},{"q":"Perfect Forward Secrecy چه چیزی را تضمین می‌کند؟","opts":["سرعت اتصال","اگر کلید خصوصی سرور بعداً لو برود، ترافیک گذشته قابل‌رمزگشایی نیست","جلوگیری از MITM","فشرده‌سازی"],"ans":1,"why":"چون کلید هر جلسه جدا و موقتی است و از کلید خصوصی مشتق نمی‌شود، لو رفتن کلید خصوصی در آینده، ترافیک ضبط‌شده قبلی را افشا نمی‌کند."},{"q":"مرورگر چطور می‌فهمد گواهی سرور معتبر است؟","opts":["از سرعت اتصال","با چک‌کردن زنجیره امضا تا یک CA ریشه مورداعتماد و تطبیق دامنه","از حجم گواهی","از IP سرور"],"ans":1,"why":"مرورگر فهرستی از CAهای ریشه مورداعتماد دارد و زنجیره امضای گواهی را تا یکی از آن‌ها دنبال می‌کند؛ همچنین بررسی می‌کند دامنه گواهی با آدرس درخواستی یکی باشد."}]'::jsonb),
('net-r6', 'net', 'از HTTP/1.1 تا HTTP/3؛ جنگ با تأخیر', 55, 6, '[{"k":"p","t":"صفحه‌های وب مدرن ده‌ها منبع دارند و پروتکل قدیمی HTTP/1.1 زیر این بار کم می‌آورد: اتصال‌های زیاد، سربرگ تکراری و صف‌های مسدودشونده. HTTP/2 و HTTP/3 هرکدام با ایده‌ای متفاوت این گلوگاه‌ها را شکستند — و فهمیدنشان برای بهینه‌سازی واقعی سرعت سایت لازم است."},{"k":"h","t":"مشکلات HTTP/1.1"},{"k":"p","t":"در HTTP/1.1 هر اتصال TCP معمولاً یک درخواست را در لحظه پاسخ می‌دهد؛ مرورگر برای موازی‌سازی مجبور است چند اتصال باز کند که سربار دارد. سربرگ‌ها هر بار کامل و متنی فرستاده می‌شوند (هدر تکراری) و اگر یک پاسخ کند باشد، بقیه پشتش معطل می‌مانند (Head-of-Line Blocking در سطح اپلیکیشن). Keep-Alive و فشرده‌سازی کمک کردند ولی ریشه مشکل پابرجا ماند."},{"k":"h","t":"HTTP/2؛ چندمسیره (Multiplexing) روی یک اتصال"},{"k":"p","t":"HTTP/2 همه درخواست‌ها را روی یک اتصال TCP، در قالب streamهای موازی می‌فرستد؛ پس چندمسیره‌ای واقعی بدون بازکردن اتصال‌های متعدد. سربرگ‌ها با HPACK فشرده و فقط تفاوت‌ها فرستاده می‌شود و پیام‌ها باینری‌اند. Server Push هم اجازه می‌داد سرور منابع را قبل از درخواست بفرستد (که عملاً کمتر استفاده شد). نتیجه: حذف صف اتصال و سربرگ تکراری."},{"k":"h","t":"HTTP/3؛ پروتکل جدید زیر پا (QUIC)"},{"k":"p","t":"HTTP/2 هنوز روی TCP است؛ یعنی اگر یک بسته TCP گم شود، همه streamها معطل بازفرستادن می‌شوند — Head-of-Line Blocking این بار در سطح انتقال. HTTP/3 این مشکل را با QUIC حل کرد: پروتکلی روی UDP که جریان‌های مستقل می‌سازد، پس گم‌شدن یک بسته فقط همان جریان را عقب می‌اندازد. QUIC همچنین دست‌دادن رمزنگاری‌شده سریع‌تری دارد و تغییر شبکه (وای‌فای به 4G) را بدون قطع اتصال تحمل می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"http-versions.sh","code":"# دیدن نسخه HTTP پاسخ‌داده‌شده\ncurl -sI https://example.com | head -1\n\n# اجبار نسخه خاص برای تست\ncurl --http2 -sI https://example.com\ncurl --http3 -sI https://example.com\n\n# بررسی ALPN (توافق نسخه در TLS)\nopenssl s_client -connect example.com:443 -alpn h2,http/1.1"},{"k":"list","items":["خط اول پاسخ (HTTP/2 یا HTTP/1.1) نشان می‌دهد سرور کدام نسخه را سرو می‌کند.","با --http2 و --http3 می‌توانی نسخه خاصی را درخواست کنی و ببینی سرور پشتیبانی می‌کند یا نه.","ALPN در دست‌دادن TLS جایی است که کلاینت و سرور روی نسخه HTTP توافق می‌کنند."]},{"k":"def","term":"Head-of-Line Blocking","t":"وقتی یک کند یا گمشده، بقیه موارد پشت‌سرِ خود را معطل می‌کند. در HTTP/1.1 در سطح درخواست‌ها روی یک اتصال بود؛ در HTTP/2 با وجود چندمسیره‌ای، چون همه روی یک TCP بودند به سطح انتقال منتقل شد؛ و HTTP/3 با QUIC و جریان‌های مستقلِ روی UDP، آن را عملاً حذف کرد."},{"k":"table","head":["","HTTP/1.1","HTTP/2","HTTP/3"],"rows":[["انتقال","TCP","TCP","QUIC روی UDP"],["موازی‌سازی","چند اتصال","یک اتصال، چند stream","streamهای مستقل واقعی"],["سربرگ","متنی، تکراری","فشرده (HPACK)","فشرده (QPACK)"],["گم‌شدن بسته","کل اتصال معطل","کل اتصال معطل","فقط همان stream"]]},{"k":"warn","title":"دام رایج","t":"فعال‌کردن HTTP/2 و انتظار معجزه بدون بهینه‌سازی منابع. اگر سایت ۱۰۰ درخواست کوچک دارد، چندمسیره‌ای کمک می‌کند ولی ترکیب و فشرده‌سازی و کشِ درستِ منابع (تصویر، JS، CSS) اثر بیشتری دارد. پروتکل جای بهینه‌سازی محتوا را نمی‌گیرد."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای APIهای داخلی بین سرویس‌ها، gRPC (که روی HTTP/2 است) را جدی بگیر: باینری، دوطرفه و با schema مشخص — برای ارتباط سرویس‌به‌سرویس خیلی کارآمدتر از REST/JSON است. ولی برای API عمومی که کلاینت‌های متنوع دارد، REST همچنان عملی‌ترین است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["HTTP/1.1 با اتصال‌های متعدد و سربرگ تکراری کم می‌آورد.","HTTP/2 چندمسیره‌ای روی یک اتصال و سربرگ فشرده آورد ولی روی TCP ماند.","HTTP/3 با QUIC روی UDP، Head-of-Line Blocking سطح انتقال را حذف کرد.","پروتکل بهتر، جای بهینه‌سازی منابع را نمی‌گیرد."]}]'::jsonb, '[{"q":"بزرگ‌ترین بهبود HTTP/2 نسبت به 1.1 چیست؟","opts":["رمزنگاری","چندمسیره‌ای واقعی روی یک اتصال و سربرگ فشرده","استفاده از UDP","حذف کوکی"],"ans":1,"why":"HTTP/2 با streamهای موازی روی یک اتصال، نیاز به چند اتصال را حذف کرد و با HPACK سربرگ تکراری را فشرده کرد — ولی همچنان روی TCP ماند."},{"q":"چرا HTTP/3 به‌جای TCP از UDP (با QUIC) استفاده می‌کند؟","opts":["UDP امن‌تر است","چون QUIC روی UDP جریان‌های مستقل می‌سازد و گم‌شدن یک بسته بقیه را معطل نمی‌کند","UDP سریع‌تر رمز می‌کند","TCP منسوخ شده"],"ans":1,"why":"مشکل HTTP/2 این بود که همه streamها روی یک TCP بودند و گم‌شدن یک بسته همه را معطل می‌کرد. QUIC با پیاده‌سازی اعتماد و streamها در لایه خود، این وابستگی را شکست."},{"q":"Head-of-Line Blocking یعنی چه؟","opts":["خطای سرور","معطل‌شدن درخواست‌های پشت‌سرِ یک کند یا گمشده","مسدودشدن توسط فایروال","کندبودن DNS"],"ans":1,"why":"وقتی منابع پشت‌سر هم در صف باشند و جلویی کند یا گم شود، بقیه نمی‌توانند جلو بزنند و معطل می‌مانند — مسئله‌ای که نسخه‌های جدید HTTP پله‌پله حلش کردند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('net-r7', 'net', 'ارتباط زنده؛ WebSocket، SSE و انتخاب درست', 50, 7, '[{"k":"p","t":"HTTP مدل «بپرس تا جواب بگیری» است؛ ولی چت، قیمت لحظه‌ای و نوتیفیکیشن نیاز دارند سرور خودش بدون پرسش پیام بفرستد. برای این کار سه راه هست — WebSocket، SSE و Long Polling — و انتخاب اشتباه بین این‌ها یکی از رایج‌ترین خطاهای طراحی realtime است."},{"k":"h","t":"WebSocket؛ کانال دوطرفه دائمی"},{"k":"p","t":"WebSocket با یک دست‌دادن HTTP شروع می‌شود (Upgrade) و بعد اتصال را به یک کانال دوطرفه دائمی تبدیل می‌کند که هر دو طرف هر زمان می‌توانند پیام بفرستند. برای چت، بازی و همکاری همزمان که واقعاً دوطرفه‌اند مناسب است. ولی دائمی‌بودن هزینه دارد: سرور باید هر اتصال را باز نگه دارد، پس scale کردنش با HTTP معمولی فرق دارد و زیرساخت (load balancer، timeout) باید با اتصال‌های بلند سازگار باشد."},{"k":"h","t":"SSE؛ وقتی فقط سرور می‌فرستد"},{"k":"p","t":"Server-Sent Events یک اتصال HTTP معمولی است که سرور آن را باز نگه می‌دارد و جریانی از رویدادها را به سمت کلاینت می‌فرستد — فقط یک‌طرفه (سرور به کلاینت). برای نوتیفیکیشن، فید زنده و داشبورد که کلاینت فقط دریافت‌کننده است، کافی و بسیار ساده‌تر از WebSocket است: روی HTTP معمولی کار می‌کند، خودکار reconnect دارد و با proxyهای ساده هم سازگار است."},{"k":"h","t":"Long Polling و انتخاب بر اساس نیاز"},{"k":"p","t":"قبل از این‌ها، Long Polling بود: کلاینت مدام می‌پرسد و سرور جواب را نگه می‌دارد تا خبری شود — پرهزینه ولی سازگار با همه‌چیز. قاعده انتخاب: اگر دوطرفه واقعی لازم داری (چت، بازی) WebSocket؛ اگر فقط سرور پیام می‌فرستد (نوتیفیکیشن، قیمت) SSE؛ و اگر گیر کرده‌ای در محیطی که هیچ‌کدام راه نیست، Long Polling. بسیاری از «چت»ها واقعاً یک‌طرفه‌اند و با SSE ساده‌تر و پایدارتر می‌شدند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"realtime.js","code":"// SSE — دریافت رویداد از سرور (مرورگر)\nconst es = new EventSource(''/events'');\nes.onmessage = (e) => console.log(''رویداد:'', e.data);\n// reconnect خودکار دارد\n\n// WebSocket — دوطرفه\nconst ws = new WebSocket(''wss://example.com/chat'');\nws.onopen  = () => ws.send(''سلام'');\nws.onmessage = (e) => show(e.data);\n\n// سمت سرور (Node) — فرستادن به همه\nwss.clients.forEach((c) => c.send(msg));"},{"k":"list","items":["EventSource فقط به یک URL وصل می‌شود و رویدادها را می‌گیرد؛ برای push یک‌طرفه کافی است و خودش وصل مجدد می‌کند.","WebSocket بعد از باز شدن، با send و onmessage در دو جهت پیام ردوبدل می‌کند.","سمت سرور، پخش برای همه کلاینت‌ها با پیمایش اتصال‌های باز انجام می‌شود — یعنی سرور باید این اتصال‌ها را نگه دارد."]},{"k":"def","term":"اتصال Stateful در برابر Stateless","t":"HTTP معمولی stateless است و هر درخواست مستقل؛ ولی WebSocket و SSE اتصال stateful و بلندمدت می‌سازند که سرور باید آن‌ها را در حافظه نگه دارد. این یعنی مقیاس‌پذیری‌شان با HTTP فرق می‌کند و باید بین چند سرور با چیزی مثل Redis Pub/Sub هماهنگ شوند."},{"k":"table","head":["","WebSocket","SSE","Long Polling"],"rows":[["جهت","دوطرفه","سرور→کلاینت","شبیه یک‌طرفه"],["پروتکل","ws روی TCP","HTTP","HTTP"],["reconnect خودکار","دستی","دارد","ذاتاً"],["مناسب برای","چت، بازی","نوتیفیکیشن، فید","سازگاری حداکثری"]]},{"k":"warn","title":"دام رایج","t":"استفاده از WebSocket برای چیزی که یک‌طرفه است (مثل نوتیفیکیشن). علاوه بر پیچیدگی بی‌مورد، مقیاس‌کردن و نگهداری اتصال‌های دوطرفه سخت‌تر است؛ در حالی که SSE همان کار را روی HTTP معمولی، با reconnect خودکار و بدون زیرساخت خاص انجام می‌دهد."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی چند سرور پشت load balancer داری، پیامی که به سرور A می‌رسد باید به کلاینتِ وصل‌شده به سرور B هم برسد. راه‌حل استاندارد Redis Pub/Sub است: همه سرورها به یک کانال گوش می‌دهند و پیام را بین کلاینت‌های خودشان پخش می‌کنند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["WebSocket کانال دوطرفه دائمی است؛ برای چت و بازی.","SSE برای push یک‌طرفه ساده‌تر و پایدارتر است.","اتصال‌های زنده stateful‌اند و مقیاس‌کردنشان با HTTP فرق دارد.","برای پخش بین چند سرور از Redis Pub/Sub استفاده کن."]}]'::jsonb, '[{"q":"برای نوتیفیکیشن لحظه‌ای (فقط سرور به کلاینت) کدام انتخاب بهتر است؟","opts":["WebSocket","SSE","Long Polling","REST"],"ans":1,"why":"چون جهت یک‌طرفه است، SSE کافی و ساده‌تر است: روی HTTP معمولی، با reconnect خودکار و بدون نگهداری اتصال‌های دوطرفه."},{"q":"چرا مقیاس‌کردن WebSocket سخت‌تر از HTTP معمولی است؟","opts":["کندتر است","چون اتصال‌های بلندمدت stateful باید در حافظه سرور بمانند و بین سرورها هماهنگ شوند","امن نیست","پهنای باند بیشتری می‌گیرد"],"ans":1,"why":"هر اتصال WebSocket حالت دارد و سرور باید آن را باز نگه دارد؛ پس نمی‌توان مثل درخواست‌های بی‌حالت به‌راحتی بین سرورها پخش کرد و نیاز به Pub/Sub دارد."},{"q":"WebSocket چطور شروع می‌شود؟","opts":["مستقیم روی UDP","با یک دست‌دادن HTTP و ارتقا (Upgrade) به پروتکل ws","با DNS","با TLS مستقیم"],"ans":1,"why":"کلاینت یک درخواست HTTP با هدر Upgrade می‌فرستد؛ اگر سرور قبول کند، همان اتصال TCP به کانال دوطرفه WebSocket تبدیل می‌شود."}]'::jsonb),
('net-r8', 'net', 'Load Balancing و Reverse Proxy؛ مقیاس‌کردن بدون درد', 55, 8, '[{"k":"p","t":"وقتی یک سرور جوابگوی ترافیک نیست، راه‌حل افزودن سرور است — ولی کسی باید درخواست‌ها را بین آن‌ها پخش کند و اگر یکی مرد، حذفش کند. این کارِ Load Balancer و Reverse Proxy است؛ و فهمیدن تفاوت L4 و L7 و استراتژی‌های پخش، پایه معماری هر سرویس مقیاس‌پذیر است."},{"k":"h","t":"Reverse Proxy؛ دربان سرویس‌ها"},{"k":"p","t":"Reverse Proxy جلوی سرورهای داخلی می‌نشیند و تمام ترافیک ورودی اول به او می‌رسد: خاتمه TLS، مسیریابی بر اساس مسیر یا هدر، کش، فشرده‌سازی و rate limiting را یک‌جا انجام می‌دهد و بعد به سرور واقعی می‌سپارد. کلاینت اصلاً نمی‌داند پشتش چند سرور است. Nginx معروف‌ترین نمونه است و بیشتر نقش‌هایی که فکر می‌کنی «سرور» انجام می‌دهد، در واقع proxy انجام می‌دهد."},{"k":"h","t":"L4 در برابر L7"},{"k":"p","t":"Load balancer لایه 4 فقط بر اساس IP و پورت تصمیم می‌گیرد و بسته‌ها را بدون بازکردن منتقل می‌کند — خیلی سریع ولی کم‌هوش. لایه 7 محتوای HTTP را می‌خواند و می‌تواند بر اساس URL، هدر یا کوکی مسیریابی کند، کش بگذارد و TLS را خاتمه دهد — هوشمندتر ولی با سربار بیشتر. معمولاً ترکیب می‌شوند: یک L4 سریع در لبه و L7های هوشمند برای مسیریابی اپلیکیشن."},{"k":"h","t":"استراتژی‌ها و Health Check"},{"k":"p","t":"پخش می‌تواند Round Robin (نوبتی)، Least Connections (کم‌اتصال‌ترین) یا Weighted (بر اساس قدرت سرور) باشد. ولی مهم‌تر از پخش، حذفِ درست است: balancer با health check دوره‌ای از هر سرور می‌پرسد «زنده‌ای؟» و سرور ناسالم را موقتاً از چرخه بیرون می‌کند تا دوباره سالم شود. بدون health check، یک سرور مرده یعنی درصد ثابتی از کاربران خطا می‌گیرند — و این تفاوت یک معماری «پایدار» و «شکننده» است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"nginx.conf","code":"upstream app {\n    least_conn;\n    server 10.0.0.1:8000 max_fails=3 fail_timeout=10s;\n    server 10.0.0.2:8000 max_fails=3 fail_timeout=10s;\n}\n\nserver {\n    listen 443 ssl http2;\n    location / {\n        proxy_pass http://app;\n        proxy_set_header Host $host;\n    }\n    location /static/ {\n        root /var/www;   # کش/سرو مستقیم، بدون زدن به اپ\n    }\n}"},{"k":"list","items":["upstream گروه سرورهای پشتی را تعریف می‌کند و least_conn می‌گوید درخواست به کم‌اتصال‌ترین برود.","max_fails و fail_timeout یعنی اگر سروری 3 بار پشت‌سرهم شکست خورد، 10 ثانیه از چرخه حذف شود — health check غیرمستقیم.","location /static نشان می‌دهد proxy می‌تواند محتوا را مستقیم سرو کند و بار را از دوش اپ بردارد."]},{"k":"def","term":"خاتمه TLS (TLS Termination)","t":"وقتی reverse proxy بار رمزگشایی TLS را به‌جای سرورهای پشتی بر عهده می‌گیرد: کلاینت با proxy به‌صورت HTTPS حرف می‌زند ولی proxy تا سرورهای داخلی (در شبکه امن) می‌تواند HTTP ساده بفرستد. این کار سربار رمزنگاری را متمرکز و مدیریت گواهی را ساده می‌کند."},{"k":"table","head":["","L4","L7"],"rows":[["تصمیم بر اساس","IP و پورت","URL، هدر، کوکی"],["سرعت","خیلی زیاد","کمتر"],["TLS termination","معمولاً نه","بله"],["مثال","LVS، NLB","Nginx، HAProxy، ALB"]]},{"k":"warn","title":"دام رایج","t":"افزودن سرور بدون health check و session stickiness. اگر کاربر لاگین باشد و Session فقط روی سرور A باشد، پخش نوبتی او را به سرور B می‌برد و لاگینش می‌پرد. راه‌حل: Session را متمرکز کن (Redis) یا stickiness بگذار — که اولی برای مقیاس‌پذیری درست‌تر است."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی سرویس را مقیاس می‌کنی، اول Session را از حافظه سرور بیرون ببر (Redis) تا سرورها واقعاً بی‌حالت شوند؛ بعد health check را جدی بگیر؛ و فقط بعد به فکر استراتژی پخش هوشمند باش. ۹۰٪ مشکلات scale از Session و health check می‌آید، نه از انتخاب الگوریتم پخش."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Reverse Proxy ترافیک را یک‌جا مدیریت می‌کند: TLS، مسیریابی، کش.","L4 سریع و کم‌هوش، L7 کندتر و هوشمند — معمولاً ترکیبی.","Health check سرور ناسالم را حذف می‌کند؛ بدون آن معماری شکننده است.","برای scale واقعی، Session را متمرکز و سرورها را بی‌حالت کن."]}]'::jsonb, '[{"q":"مزیت اصلی health check چیست؟","opts":["سرعت بیشتر","حذف خودکار سرور ناسالم از چرخه تا کاربران خطا نگیرند","کاهش پهنای باند","رمزنگاری"],"ans":1,"why":"با بررسی دوره‌ای، balancer سرور مرده یا کند را موقتاً حذف می‌کند؛ پس ترافیک فقط به سرورهای سالم می‌رود و در دسترس بودن کل بالا می‌رود."},{"q":"تفاوت کلیدی L4 و L7 چیست؟","opts":["L7 فقط برای وب نیست","L4 بر اساس IP/پورت و بدون خواندن محتوا، L7 محتوا و هدرهای HTTP را می‌خواند","L4 امن‌تر است","فرقی ندارند"],"ans":1,"why":"L4 بسته را باز نمی‌کند و فقط آدرس و پورت را می‌بیند (سریع)؛ L7 تا لایه اپلیکیشن می‌رود و می‌تواند بر اساس URL و هدر مسیریابی و TLS را خاتمه دهد (هوشمند)."},{"q":"چرا برای مقیاس‌پذیری، متمرکزکردن Session (در Redis) بهتر از stickiness است؟","opts":["ارزان‌تر","چون سرورها واقعاً بی‌حالت می‌شوند و هر balancer می‌تواند هر درخواست را به هر سرور بفرستد","امن‌تر","سریع‌تر رمز می‌کند"],"ans":1,"why":"با Session متمرکز، هیچ وابستگی‌ای بین کاربر و یک سرور خاص نیست؛ پس می‌توان آزادانه سرور اضافه/کم کرد. stickiness این انعطاف را می‌گیرد و با حذف سرور، Sessionها هم می‌پرند."}]'::jsonb),
('n-net-l1', 'net', 'سفر یک بسته؛ لایه‌ها و پروتکل‌ها', 55, 9, '[{"k":"p","t":"اینترنت شاهکار «تقسیم کار» است: هر لایه فقط کار خودش را می‌کند و بقیه را نمی‌شناسد. وقتی پیامی می‌فرستی، در هر لایه یک سربرگ به آن اضافه می‌شود (Encapsulation) و در مقصد لایه‌به‌لایه باز می‌شود. اگر لایه‌ها را بفهمی، هر خطای شبکه را می‌توانی به یک لایه خاص نسبت بدهی — نیمی از راه دیباگ."},{"k":"code","lang":"bash","title":"terminal","code":"# آیا مقصد زنده است؟ (لایه شبکه)\n$ ping -c 3 bitcode.academy\n64 bytes from 185.143.233.12: icmp_seq=1 ttl=52 time=18.4 ms\n\n# مسیر بسته کجاها می‌رود؟\n$ traceroute bitcode.academy\n 1  192.168.1.1        0.9 ms    # مودم خانه\n 2  10.20.0.1          4.1 ms    # ISP محلی\n 3  185.143.232.1     17.8 ms    # هسته ISP\n 4  185.143.233.12    18.4 ms    # مقصد!\n\n# چه پورت‌هایی گوش می‌دهند؟\n$ ss -tulpn\ntcp  LISTEN  0  128  0.0.0.0:22    # SSH\ntcp  LISTEN  0  511  0.0.0.0:80    # HTTP\ntcp  LISTEN  0  511  0.0.0.0:443   # HTTPS"},{"k":"visual","visual":"layers","title":"شبیه‌ساز: لایه‌های شبکه"},{"k":"table","head":["لایه","پروتکل‌ها","وظیفه","واحد داده"],"rows":[["کاربرد","HTTP, DNS, SMTP","معنی پیام برای برنامه","Message"],["انتقال","TCP, UDP","رسیدن کامل و به‌ترتیب (TCP) یا سریع (UDP)","Segment"],["شبکه","IP, ICMP","مسیریابی بین شبکه‌ها","Packet"],["پیوند","Ethernet, WiFi","انتقال روی سیم/موج","Frame"]]},{"k":"def","term":"TCP در برابر UDP","t":"TCP مثل نامه سفارشی است: اتصال می‌سازد (Handshake سه‌مرحله‌ای)، تحویل و ترتیب را تضمین و گمشده را دوباره می‌فرستد. UDP مثل پخش رادیویی: سریع، بدون تضمین — برای ویدیو زنده و بازی که تأخیر از گمشدگی بدتر است."},{"k":"h","t":"عمیق‌تر: MTU و قطعه‌شدن — چرا بسته‌ها می‌شکنند"},{"k":"p","t":"اینترنت بسته‌ها را در قطعه‌های محدود جابه‌جا می‌کند: هر پیوند شبکه یک «حداکثر واحد انتقال» (MTU) دارد که معمولاً ۱۵۰۰ بایت است. وقتی پیام بزرگ‌تری بفرستی، لایه‌های پایین آن را به قطعه‌هایی می‌شکنند و در مقصد دوباره سرهم می‌کنند. این جزئیات معمولاً پنهان است — تا روزی که یک VPN یا تونل، سربار اضافه می‌کند و بسته‌ها دیگر جا نمی‌شوند؛ آنگاه اتصال‌هایی که «باید کار کنند» بدون هیچ خطای روشنی کند یا قطع می‌شوند. دانستن MTU و فرمان‌هایی مثل ping با پرچم «قطعه نشود»، ابزار دیباگ همین روزهای سخت است."},{"k":"p","t":"UDP و TCP در برابر قطعه‌شدن متفاوت‌اند: TCP خودش اندازه قطعه را با شبکه هماهنگ می‌کند (MSS) تا اصلاً نیازی به شکستن نباشد؛ ولی UDP این کار را نمی‌کند و اگر بسته‌ات از MTU بزرگ‌تر باشد، یا در مسیر قطعه می‌شود یا (در IPv6) اصلاً رد نمی‌شود. قاعده عملی: در UDP پیام‌ها را کوچک نگه دار (مثلاً زیر ۵۱۲ بایت برای سازگاری کامل) وگرنه خودت باید مکانیزم تکه‌تکه‌کردن بسازی — همان کاری که پروتکل‌هایی مثل QUIC در لایه کاربرد انجام می‌دهند تا کنترل دست خودشان باشد، نه شبکه."},{"k":"code","lang":"bash","title":"پیدا کردن MTU مسیر","code":"# ping با پرچم «قطعه نشود» و اندازه‌های مختلف:\nping -M do -s 1472 example.com    # 1472 + 28 سربرگ = 1500\n\n# اگر «Fragmentation needed» گرفتی، یعنی مسیر MTU کوچک‌تری دارد:\nping -M do -s 1400 example.com\n\n# با جست‌وجوی دودویی، بزرگ‌ترین اندازه‌ای که رد می‌شود\n# همان MTU واقعی مسیر توست."}]'::jsonb, '[{"q":"چرا استریم ویدیو معمولاً UDP را ترجیح می‌دهد؟","opts":["امن‌تر است","تأخیر از یک فریم گمشده بدتر است؛ بازفرستادن TCP لحظه را از دست می‌دهد","رایگان است","رمزنگاری دارد"],"ans":1,"why":"در پخش زنده، فریمی که دیر برسد بی‌ارزش است؛ UDP بدون سربار تأیید و بازفرستانی، سریع‌ترین مسیر را می‌رود و گمشدگی را لایه‌های بالاتر جبران می‌کنند."},{"q":"وقتی ping جواب نمی‌دهد ولی سایت باز می‌شود، چه اتفاقی افتاده؟","opts":["اینترنت قطع است","احتمالاً سرور یا فایروال بسته‌های ICMP را مسدود کرده؛ HTTP روی TCP جداگانه کار می‌کند","DNS خراب است","غیرممکن است"],"ans":1,"why":"هر پروتکل مسیر خودش را دارد؛ خیلی از سرورها برای کاهش سطح حمله ICMP را می‌بندند. نتیجه: ping تنها معیار «زنده بودن» نیست."}]'::jsonb),
('n-net-l2', 'net', 'DNS و HTTP؛ زبان وب', 60, 10, '[{"k":"p","t":"مرورگر فقط IP می‌فهمد، انسان فقط نام. DNS دفترچه تلفن توزیع‌شده‌ی اینترنت است: رزولوشن از کش مرورگر شروع و تا روت‌سرورها می‌رود. بعد از پیدا شدن IP، گفت‌وگوی واقعی با HTTP شروع می‌شود — پروتکلی متنی و ساده که با همان سادگی، کل وب را حمل می‌کند."},{"k":"code","lang":"txt","title":"request-response","code":"# درخواست خام مرورگر\nGET /courses/react HTTP/1.1\nHost: bitcode.academy\nAccept: text/html\nCookie: session=abc123\n\n# پاسخ سرور\nHTTP/1.1 200 OK\nContent-Type: text/html; charset=utf-8\nCache-Control: max-age=300\nSet-Cookie: session=abc123; HttpOnly; Secure\n\n<!doctype html>..."},{"k":"visual","visual":"httpCycle","title":"شبیه‌ساز: چرخه یک درخواست"},{"k":"table","head":["کد","معنی","در عمل"],"rows":[["200","موفق","همه‌چیز درست"],["301 / 302","منتقل شده (دائم / موقت)","مرورگر خودکار دنبال می‌کند"],["401","هویت نامشخص","لاگین نکرده‌ای"],["403","هویت معلوم، اجازه نداری","لاگین کرده‌ای ولی دسترسی نه"],["404","منبع وجود ندارد","URL اشتباه یا حذف‌شده"],["500 / 503","خطای سرور / سرویس موقتاً پایین","مشکل از سمت ماست"]]},{"k":"def","term":"HTTPS و TLS","t":"HTTP متن ساده است؛ در کافه‌ی دارای WiFi مشترک هر کسی می‌تواند آن را بخواند. HTTPS همان HTTP داخل یک تونل رمزنگاری TLS است: Handshake با گواهی هویت سرور را ثابت و کلید نشست را می‌سازد؛ از آن پس حتی اگر بسته‌ها شنود شوند، خواندنی نیستند."},{"k":"tip","title":"هدرهایی که مصاحبه‌گر می‌پرسد","t":"Cache-Control (کش‌پذیری)، Set-Cookie با HttpOnly و Secure (دسترسی جاوااسکریپت ممنوع + فقط HTTPS)، Content-Type (جلوگیری از حدس‌زدن مرورگر) و CORS-Headerها — این چهار تا را عمیق بفهم."},{"k":"h","t":"عمیق‌تر: آناتومی یک پاسخ HTTP — هدرهایی که باید بشناسی"},{"k":"p","t":"وقتی curl با پرچم i یک آدرس را می‌زنی، پاسخ کامل را می‌بینی — و خواندن این چند خط، نیمی از دیباگ وب است. کد وضعیت (200، 301، 404، 500) فقط سرِ ماجراست؛ هدرها داستان کامل را می‌گویند: Content-Type که می‌گوید بدنه چیست و مرورگر چطور رفتارش کند، Cache-Control که عمر کش را تعیین می‌کند، Set-Cookie که هویت را می‌سازد، و Location در پاسخ‌های redirect که مقصد بعدی را نشان می‌دهد. بسیاری از باگ‌های «نمایش داده نمی‌شود» یا «کش نمی‌شود» ریشه در همین هدرها دارند، نه در کد صفحه."},{"k":"code","lang":"bash","title":"خواندن پاسخ مثل یک مهندس","code":"curl -sI https://example.com\n\n# HTTP/2 200\n# content-type: text/html; charset=UTF-8     ← بدنه چیست\n# cache-control: max-age=604800              ← یک هفته کش کن\n# etag: \"3147526947\"                          ← نسخه محتوا\n# vary: accept-encoding                       ← کش برای هر فشرده‌سازی جدا\n\n# و بررسی کش شرطی — اگر تغییر نکرده، 304 می‌گیری نه 200:\ncurl -sI -H ''If-None-Match: \"3147526947\"'' https://example.com"},{"k":"p","t":"مکانیزم ETag و If-None-Match را خوب بفهم چون قلب «کشِ هوشمند» است: سرور برای هر نسخه از محتوا یک شناسه می‌فرستد؛ دفعه بعد مرورگر همان شناسه را برمی‌گرداند و اگر محتوا عوض نشده، سرور فقط یک 304 خالی می‌فرستد — بدون هیچ بدنه‌ای. یعنی صفحه «تازه» نمایش داده می‌شود ولی هیچ بایتی از محتوا جابه‌جا نشده. تفاوت 200 و 304 در تب Network مرورگر، سریع‌ترین راه فهمیدن این است که کش‌ات واقعاً کار می‌کند یا نه."}]'::jsonb, '[{"q":"تفاوت 401 و 403 چیست؟","opts":["فرقی ندارند","در 401 معلوم نیست کی هستی؛ در 403 معلومی ولی اجازه نداری","403 بدتر از 500 است","هر دو خطای سرورند"],"ans":1,"why":"401 یعنی Authentication لازم است (لاگین کن)؛ 403 یعنی Authorization ناموفق (نقش/دسترسی نداری). درمان اولی ورود است، دومی تغییر اجازه."},{"q":"DNS چه نقشی در باز شدن سایت دارد؟","opts":["رمزنگاری می‌کند","نام دامنه را به IP سرور ترجمه می‌کند تا مرورگر بداند به کجا وصل شود","صفحه را کش می‌کند","هیچ نقشی ندارد"],"ans":1,"why":"مسیریابی اینترنت فقط با IP ممکن است؛ DNS حلقه‌ی گمشده‌ی بین «نام خوانا» و «آدرس قابل‌مسیریابی» است — با کش‌های لایه‌لایه که رزولوشن را میلی‌ثانیه‌ای می‌کنند."}]'::jsonb),
('n-net-l3', 'net', 'امنیت شبکه؛ به خط اعتماد نکن', 55, 11, '[{"k":"p","t":"قانون صفر شبکه: هر بایتی که از دستگاهت خارج می‌شود، قابل خواندن و تغییر است — مگر ثابت شده باشد که نیست. MITM یعنی کسی وسط راه خود را جا بزند؛ DDoS یعنی سیل درخواست جعلی سرویس را خفه کند. دفاع، لایه‌لایه است: رمزنگاری، احراز هویت، فایروال و مانیتورینگ."},{"k":"code","lang":"bash","title":"terminal","code":"# آیا اتصال واقعاً HTTPS است؟ گواهی را ببین\n$ openssl s_client -connect bitcode.academy:443 -brief\nCONNECTION ESTABLISHED\nProtocol version: TLSv1.3\nCiphersuite: TLS_AES_256_GCM_SHA384\nVerification: OK                # زنجیره گواهی معتبر است\n\n# پورت‌های باز سیستم خودت — سطح حمله را بشناس\n$ ss -tulpn | grep LISTEN\n\n# فایروال ساده: فقط 22 و 443 باز\n$ sudo ufw allow 22/tcp\n$ sudo ufw allow 443/tcp\n$ sudo ufw enable\nStatus: active"},{"k":"list","items":["همیشه HTTPS — حتی برای APIهای داخلی؛ گواهی رایگان Let''s Encrypt بهانه را گرفته","DNS over HTTPS/TLS تا دفترچه تلفن هم شنود نشود","پورت‌های باز را ماهی یک بار بازبینی کن؛ هر پورت باز یک در است","SSH فقط با کلید، بدون رمز عبور و بدون root","لاگ دسترسی‌ها را نگه دار؛ حمله‌ای که دیده نشود، اتفاق نیفتاده"]},{"k":"def","term":"Man-in-the-Middle","t":"مهاجم بین تو و سرور می‌نشیند؛ پیام‌ها را می‌خواند و حتی تغییر می‌دهد — مثلاً در WiFi عمومی جعلی. HTTPS سالم با گواهی معتبر، چون مرورگر هویت سرور را رمزنگارانه تأیید می‌کند، این حمله را بی‌اثر می‌کند."},{"k":"warn","title":"VPN همه‌چیز نیست","t":"VPN فقط ترافیک را تا سرور VPN رمز می‌کند؛ از آن‌جا به بعد همان قوانین برقرار است. VPN به سایتی که HTTP ساده می‌فرستد، جادو نمی‌کند. امنیت در لایه‌هاست: TLS، احراز هویت قوی و حداقل دسترسی — هیچ‌کدام جای دیگری را نمی‌گیرند."}]'::jsonb, '[{"q":"حمله MITM دقیقاً چه می‌کند؟","opts":["رمز عبور را حدس می‌زند","بین دو طرف ارتباط قرار می‌گیرد و ترافیک را شنود یا دستکاری می‌کند","سرور را خاموش می‌کند","فایل‌ها را پاک می‌کند"],"ans":1,"why":"در WiFi عمومی یا ARP جعلی، مهاجم خودش را به‌جای دروازه جا می‌زند؛ قربانی فکر می‌کند مستقیم با سرور حرف می‌زند. TLS با تأیید هویت سرور، این توهم را می‌شکند."},{"q":"فایروال چه کاری انجام می‌دهد؟","opts":["ویروس‌ها را پاک می‌کند","ترافیک ورودی/خروجی را بر اساس قوانین (پورت، IP، پروتکل) اجازه یا مسدود می‌کند","رمزنگاری می‌کند","سرعت را بالا می‌برد"],"ans":1,"why":"فایروال درِبان لایه شبکه است: هر سرویسی که لازم نیست از بیرون برسد، پورتش بسته می‌شود — کوچک‌کردن سطح حمله، مؤثرترین دفاع اولیه."}]'::jsonb),
('net-x1', 'net', 'سفر یک بسته — لایه‌ها و Encapsulation', 50, 12, '[{"k":"p","t":"وقتی ایمیلی می‌فرستی، پیام تو در پنج لایه بسته‌بندی می‌شود — مثل نامه‌ای که در پاکت، پاکت در جعبه، جعبه در کانتینر گذاشته می‌شود. هر لایه فقط کار خودش را بلد است و به بقیه کار ندارد؛ این جداسازی شاهکار مهندسی است که اینترنت مقیاس‌پذیر را ممکن کرده."},{"k":"visual","visual":"layers","title":"شبیه‌ساز: بسته‌بندی لایه به لایه"},{"k":"visual","visual":"httpCycle","title":"شبیه‌ساز: مسیر کامل یک درخواست"},{"k":"h","t":"وظیفه هر لایه در یک جمله"},{"k":"list","items":["کاربرد: زبان مشترک برنامه‌ها — HTTP، DNS، SMTP","انتقال: گفتگوی قابل‌اتکا بین دو برنامه — TCP (با تضمین) یا UDP (بدون تضمین، سریع)","شبکه: مسیریابی بین شبکه‌ها — IP؛ آدرس‌دهی منطقی","پیوند داده: انتقال بین دو گره مجاور — Ethernet/WiFi؛ آدرس فیزیکی MAC","فیزیکی: سیگنال واقعی — نور، برق، موج رادیویی"]},{"k":"def","term":"Encapsulation","t":"هر لایه، بسته لایه بالایی را «داده» فرض می‌کند و سربرگ خودش را به آن می‌چسباند. روتر فقط تا لایه شبکه باز می‌کند؛ سوئیچ تا لایه پیوند؛ و فقط مقصد نهایی همه لایه‌ها را باز می‌کند. به همین دلیل زیرساخت وسط نیازی از محتوای تو ندارد."},{"k":"code","lang":"bash","title":"ابزارهای هر لایه","code":"# لایه کاربرد — چه چیزی خواسته می‌شود؟\ncurl -I https://example.com\n\n# لایه انتقال — کدام پورت باز است؟\nnc -zv example.com 443\n\n# لایه شبکه — مسیر بسته‌ها کجاست؟\ntraceroute example.com\n\n# لایه پیوند — همسایه‌های شبکه کیستند؟\narp -a\n\n# DNS — نام به چه IP نگاشت می‌شود؟\ndig example.com +short"},{"k":"tip","title":"نکته منتور","t":"مدل OSI هفت لایه دارد ولی دنیای واقعی با TCP/IP چهارلایه‌ای کار می‌کند. برای مصاحبه، OSI را به‌عنوان واژگان مشترک و TCP/IP را به‌عنوان واقعیت اجرا بدان — و بتوانی هر پروتکل را در جای درستش بگذاری."}]'::jsonb, '[{"q":"روتر در کدام لایه تصمیم می‌گیرد؟","opts":["کاربرد","شبکه — بر اساس آدرس IP مقصد","فیزیکی","انتقال"],"ans":1,"why":"روتر سربرگ IP را می‌خواند و با جدول مسیریابی، بهترین گام بعدی را انتخاب می‌کند؛ محتوای TCP و HTTP برایش مهم نیست."},{"q":"چرا TCP «قابل‌اتکا» و UDP «سریع» خوانده می‌شود؟","opts":["TCP جدیدتر است","TCP تأیید دریافت، ترتیب و بازفرستادن دارد؛ UDP هیچ‌کدام — فقط می‌فرستد","UDP فشرده‌تر است","TCP فقط برای وب است"],"ans":1,"why":"TCP با شماره ترتیب و ACK از نرسیدن و بی‌نظمی جلوگیری می‌کند؛ UDP این سربار را ندارد و برای پخش زنده و بازی که تأخیر مهم‌تر از کامل‌بودن است، مناسب‌تر است."}]'::jsonb),
('net-b1', 'net', 'مدل OSI و TCP/IP', 63, 13, '[{"k":"p","t":"مدل OSI شبکه را هفت لایه می‌بیند و TCP/IP چهار لایه واقعی؛ هر لایه فقط با لایه هم‌تراز طرف مقابل حرف می‌زند و خدمات لایه پایین‌تر را مصرف می‌کند."},{"k":"h","t":"چرا لایه‌ها؛ هنرِ نفهمیدنِ همسایه"},{"k":"p","t":"معماری لایه‌ای اینترنت بزرگ‌ترین درس «جداسازی مسئولیت» در تاریخ مهندسی است: هر لایه فقط کار خودش را بلد است و بقیه را «جعبه سیاه» فرض می‌کند. لایه فیزیکی سیگنال می‌فرستد و نمی‌داند بسته چیست؛ IP فقط آدرس‌دهی و مسیریابی بلد است و نمی‌داند TCP قابل‌اعتماد است یا نه؛ HTTP نمی‌داند بسته‌ها از فیبر می‌روند یا ماهواره. نتیجه این نادانیِ عمدی، مقیاس‌پذیری است: می‌توانی فیبر را با 5G عوض کنی بدون لمس HTTP، و HTTP/2 را جای HTTP/1 بگذاری بدون لمس IP. هر تغییری در یک لایه، محصور می‌ماند. وقتی داری سیستم خودت را لایه‌بندی می‌کنی (UI/منطق/داده)، دقیقاً همین اصل را کپی می‌کنی: هر لایه باید بتواند همسایه‌اش را نفهمد."},{"k":"h","t":"سفر یک بسته؛ Encapsulation در عمل"},{"k":"p","t":"وقتی ایمیلی می‌فرستی، داده‌ات پنج بار بسته‌بندی می‌شود — مثل نامه‌ای که در پاکت، پاکت در جعبه، جعبه در کانتینر می‌رود. هر لایه، بسته لایه بالایی را «محموله» فرض و سربرگ خودش را می‌چسباند: TCP پورت و شماره ترتیب اضافه می‌کند، IP آدرس مبدا/مقصد، Ethernet آدرس MAC همسایه بعدی. در مسیر، روترها فقط تا لایه IP باز می‌کنند (مسیر بعدی را می‌یابند و می‌فرستند) — محتوای TCP/HTTP را اصلاً نمی‌بینند؛ و فقط مقصد نهایی لایه‌ها را یکی‌یکی باز می‌کند (Decapsulation). این طراحی یعنی: زیرساخت وسط نیازی به فهم محتوای تو ندارد — و به همین دلیل اینترنت می‌تواند هر پروتکل جدیدی را بدون تغییر روترها حمل کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"آناتومی یک فریم — لایه‌ها در دل هم","code":"┌─ Ethernet Frame ──────────────────────────────┐\n│ MAC dst │ MAC src │ Type                      │\n│ ┌─ IP Packet ──────────────────────────────┐  │\n│ │ src IP │ dst IP │ TTL │ Protocol         │  │\n│ │ ┌─ TCP Segment ────────────────────────┐ │  │\n│ │ │ src port │ dst port │ seq │ ack      │ │  │\n│ │ │ ┌─ HTTP ──────────────────────────┐  │ │  │\n│ │ │ │ GET /index.html HTTP/1.1        │  │ │  │\n│ │ │ └─────────────────────────────────┘  │ │  │\n│ │ └──────────────────────────────────────┘ │  │\n│ └──────────────────────────────────────────┘  │\n└───────────────────────────────────────────────┘\nهر لایه، قبلی را «داده» فرض و سربرگ خودش را چسباند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["لایه TCP/IP","پروتکل نمونه","واحد داده","سوال اصلی"],"rows":[["کاربرد","HTTP، DNS، SMTP","پیام","چه چیزی بگوییم؟"],["انتقال","TCP، UDP","Segment","گفتگوی قابل‌اتکا یا سریع؟"],["شبکه (اینترنت)","IP، ICMP","Packet","از کدام مسیر؟"],["پیوند + فیزیکی","Ethernet، WiFi","Frame / بیت","به کدام همسایه؟"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["لایه‌ها: فیزیکی، پیوند، شبکه، انتقال، نشست، نمایش، کاربرد","TCP/IP: پیوند، اینترنت، انتقال، کاربرد","Encapsulation: هر لایه سربرگ خودش را اضافه می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"لایه‌ها و پروتکل‌ها","code":"کاربرد:  HTTP, DNS, SMTP\nانتقال:   TCP, UDP\nشبکه:      IP, ICMP\nپیوند:     Ethernet, WiFi\nفیزیکی:    کابل, موج"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: لایه‌ها: فیزیکی، پیوند، شبکه، انتقال، نشست، نمایش، کاربرد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کدام لایه مسئول آدرس‌دهی منطقی و مسیریابی است؟","opts":["پیوند","شبکه (IP)","انتقال","کاربرد"],"ans":1,"why":"لایه شبکه با آدرس IP بسته‌ها را بین شبکه‌ها مسیریابی می‌کند؛ لایه پیوند فقط بین دو گره مجاور است."},{"q":"روتر در کدام لایه تصمیم می‌گیرد و تا کجا را می‌فهمد؟","opts":["کاربرد — تا HTTP","لایه شبکه — فقط سربرگ IP را می‌خواند و مقصد بعدی را می‌یابد؛ محتوای TCP و HTTP برایش نامرئی است","فیزیکی","انتقال"],"ans":1,"why":"روتر بسته را تا IP باز می‌کند، با جدول مسیریابی گام بعدی را می‌یابد و می‌فرستد. ندانستنِ لایه‌های بالاتر، دقیقاً چیزی است که روترها را ساده و سریع نگه داشته."},{"q":"TCP و UDP هر دو در یک لایه‌اند؛ تفاوت اساسی‌شان چیست؟","opts":["سرعت","TCP با شماره ترتیب و تأیید دریافت، تحویل مطمئن و مرتب تضمین می‌کند؛ UDP فقط می‌فرستد — سبک و بدون تضمین","پورت‌ها","رمزنگاری"],"ans":1,"why":"TCP برای وب و فایل است که نرسیدن یعنی خرابی؛ UDP برای پخش زنده و بازی که تأخیر مهم‌تر از کامل‌بودن است — یک بسته گمشده بهتر از یک ثانیه تأخیر است."}]'::jsonb),
('net-b2', 'net', 'TCP و کنترل جریان', 63, 14, '[{"k":"p","t":"TCP اتصال قابل‌اتکا می‌سازد؛ با سه‌راهی دست‌دادن اتصال برقرار، با شماره ترتیب داده مرتب و با ACK و بازفرستادن، تحویل تضمین می‌شود."},{"k":"h","t":"TCP چطور «قابل‌اعتماد» می‌شود؛ سه مکانیزم"},{"k":"p","t":"TCP روی IPِ غیرقابل‌اعتماد، سه مکانیزم سوار می‌کند. اول، شماره ترتیب (Sequence Number): هر بایت شماره دارد، پس گیرنده می‌فهمد کدام تکه گم شده و کجاها تکراری است — بسته‌ها می‌توانند بی‌ترتیب برسند و TCP مرتبشان می‌کند. دوم، تأیید دریافت (ACK): گیرنده می‌گوید «تا شماره X را گرفتم» و فرستنده اگر ACK نرسد، بعد از مهلت (RTO) دوباره می‌فرستد. سوم، کنترل جریان: گیرنده در هر ACK اعلام می‌کند «چقدر بافر خالی دارم» (Window) و فرستنده بیشتر از آن نمی‌فرستد — تا گیرنده کند زیر بار دفن نشود. این سه، به‌اضافه دست‌دادن اولیه برای هماهنگی شماره‌ها، «جریان بایت قابل‌اعتماد» را می‌سازند — و دلیلش که HTTP/3 (QUIC) دوباره این‌ها را روی UDP بازسازی کرد، نه بیهودگی‌شان که سربار و تأخیرشان بود."},{"k":"h","t":"کنترل ازدحام؛ اینترنت خودش را از خودش نجات می‌دهد"},{"k":"p","t":"کنترل جریان مراقب گیرنده است؛ کنترل ازدحام مراقبِ «شبکه بین راه». وقتی فرستنده تشخیص می‌دهد بسته‌ها گم می‌شوند (ACK نمی‌رسد یا تکراری می‌آید)، حدس می‌زند شبکه شلوغ شده — و سرعت را کم می‌کند، حتی اگر گیرنده کشش داشته باشد. الگوریتم کلاسیک AIMD دو فاز دارد: در Slow Start از پنجره ۱ شروع و هر ACK موفق پنجره را «نمایی» بزرگ می‌کند تا اولین گم‌شدگی؛ بعد وارد حالت «افزایش خطی، کاهش ضربی» می‌شود: هر دور کمی زیاد کن، ولی با اولین نشانه ازدحام، نصف کن. این رفتار — احتیاط بعد از هر شکست — چیزی است که اینترنت را از فروپاشیِ خودساخته نجات می‌دهد: میلیون‌ها فرستنده، بدون هیچ هماهنگ‌کننده مرکزی، با هم به تعادل می‌رسند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"دیدن TCP زنده با tcpdump","code":"# دست‌دادن سه‌راهی یک اتصال را ببین:\nsudo tcpdump -i any ''tcp port 443'' -n | head -6\n\n# 12:00:00.001 IP A.51234 > B.443: Flags [S]  seq 100\n# 12:00:00.020 IP B.443 > A.51234: Flags [S.] seq 300 ack 101\n# 12:00:00.021 IP A.51234 > B.443: Flags [.]  ack 301\n#   [S]=SYN  [S.]=SYN+ACK  [.]=ACK — فاصله ۲۰ms یعنی RTT\n\n# بعدش:\n# [P.] = داده (Push)   [F.] = پایان (FIN)\n# اگر [S] بی‌جواب بماند، TCP با فاصله‌های\n# ۱s، ۲s، ۴s دوباره می‌زند (Backoff نمایی) تا تسلیم شود"},{"k":"def","term":"RTT (زمان رفت‌وبرگشت)","t":"زمان رسیدن یک بسته به مقصد و برگشتن تأییدش — مهم‌ترین عدد هر اتصال. TCP از RTT برای تنظیم مهلت بازفرستادن (RTO) استفاده می‌کند و هر پروتکل جدید (مثل QUIC) اول سعی می‌کند تعداد RTTهای لازم برای شروع را کم کند — چون با هر ۱۰۰ms فاصله، کاربر واقعاً صبر می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سه‌راهی: SYN → SYN-ACK → ACK","هر بسته شماره ترتیب دارد تا مرتب و بدون تکرار باشد","گیرنده با ACK می‌گوید چه چیزی رسید؛ گمشده دوباره فرستاده می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"سه‌راهی TCP","code":"Client: ---- SYN(seq=x) ----> Server\nClient: <--- SYN-ACK(y) ------ Server\nClient: ---- ACK -----------> Server\n        [اتصال برقرار شد]"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سه‌راهی: SYN → SYN-ACK → ACK بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا TCP قابل‌اتکاست ولی UDP نه؟","opts":["TCP جدیدتر است","چون TCP تأیید دریافت، ترتیب و بازفرستادن دارد؛ UDP فقط می‌فرستد","UDP فشرده‌تر است","TCP رمز می‌کند"],"ans":1,"why":"TCP با ACK و شماره ترتیب می‌فهمد چه چیزی نرسیده و دوباره می‌فرستد؛ UDP هیچ بازخوردی نمی‌گیرد."},{"q":"چرا TCP بسته‌ها را با شماره ترتیب می‌فرستد؟","opts":["برای رمزنگاری","تا گیرنده بتواند بسته‌های بی‌ترتیب‌رسیده را مرتب و تکراری‌ها را حذف کند و بفهمد دقیقاً چه تکه‌ای گم شده","برای فشرده‌سازی","اجباری نیست"],"ans":1,"why":"در اینترنت بسته‌ها مسیرهای متفاوت می‌روند و ممکن است جابه‌جا یا تکراری برسند. شماره ترتیب است که از این آشوب، «جریان بایت مرتب و بدون تکرار» می‌سازد."},{"q":"در AIMD چرا کاهش «ضربی» است ولی افزایش «خطی»؟","opts":["تصادفی","چون با نشانه ازدحام باید سریع عقب کشید (نصف کردن) تا شبکه نفس بکشد، ولی افزایش محتاطانه و خطی از ساختن دوباره همان ازدحام جلوگیری می‌کند","ریاضی‌اش ساده‌تر","استاندارد است"],"ans":1,"why":"افزایش نمایی سریع دوباره شبکه را پر می‌کند؛ کاهش خطی دیر واکنش می‌دهد. AIMD تعادلی است که میلیون‌ها فرستنده مستقل را به‌طور خودکار به انصاف نزدیک می‌کند."}]'::jsonb),
('net-b3', 'net', 'IP و مسیریابی', 63, 15, '[{"k":"p","t":"IP آدرس منطقی هر دستگاه و زیرشبکه را مشخص می‌کند؛ روترها با جدول مسیریابی هر بسته را یک گام به مقصد نزدیک می‌کنند."},{"k":"h","t":"آدرس منطقی در برابر فیزیکی؛ چرا IP کافی نیست"},{"k":"p","t":"هر کارت شبکه یک آدرس فیزیکی (MAC) دارد — مثل شماره شاسی ماشین — که با خودش جابه‌جا می‌شود و فقط بین همسایه‌های یک شبکه معنا دارد. ولی MAC نمی‌تواند مسیریابی کند: از روی آن معلوم نیست دستگاه «کجای دنیا»ست. IP آدرس «منطقی و سلسله‌مراتبی» است — مثل آدرس پستی: بخش اولش (prefix) می‌گوید کدام شبکه، بخش دوم کدام دستگاه داخل آن. این سلسله‌مراتب همان چیزی است که مسیریابی را ممکن می‌کند: روتر لازم نیست آدرس تک‌تک دستگاه‌های دنیا را بداند؛ کافی است بداند «بسته‌های 185.143.x.x را بفرست به سمت روتر فلان». جدول مسیریابی هر دستگاه هم ساده است: اگر مقصد در شبکه خودم است مستقیم بفرست، وگرنه بده به دروازه (Gateway) تا او برساند — و همین تکرار ساده، بسته را قاره‌به‌قاره جلو می‌برد."},{"k":"h","t":"NAT؛ دروغی که اینترنت را نجات داد"},{"k":"p","t":"آدرس‌های IPv4 فقط ۴.۳ میلیاردند — برای دنیایی که هر نفر چند دستگاه دارد، خیلی کم. دو راه‌حل مکمل: NAT در خانه‌ها و شرکت‌ها — روتر یک آدرس عمومی می‌گیرد و همه دستگاه‌های داخلی با آدرس‌های خصوصی (مثل 192.168.1.x) پشت آن پنهان می‌شوند؛ روتر با جدول ترجمه پورت‌ها می‌فهمد پاسخ هر اتصال مال کدام دستگاه است. و IPv6 با ۳۴۰ تریلیون‌تریلیون آدرس، راه‌حل نهایی. NAT یک عارضه جالب داشت: چون اتصال‌ها فقط از داخل شروع می‌شوند، به‌طور تصادفی دیوار آتش طبیعی ساخت — ولی همزمان، اتصال مستقیم P2P را سخت کرد (راه‌حلش Hole Punching و TURN است). امروز درحال گذاریم: ستون‌فقرات اینترنت کاملاً IPv6 می‌شود و NAT آرام‌آرام به تاریخ می‌پیوندد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"مسیریابی از دید خود سیستم","code":"# جدول مسیریابی من:\nip route\n# default via 192.168.1.1 dev wlan0\n#   ← هرچه مال شبکه‌ام نیست، به دروازه بده\n# 192.168.1.0/24 dev wlan0\n#   ← همسایه‌های خودم: مستقیم\n\n# آدرس‌هایم:\nip addr | grep inet\n# 192.168.1.42/24        ← خصوصی، پشت NAT\n\n# بسته‌ها واقعاً از کجا می‌روند؟\ntraceroute 8.8.8.8\n# هر خط یک روتر — مشاهده‌گرهای واقعی مسیر"},{"k":"def","term":"جدول مسیریابی (Routing Table)","t":"نقشه تصمیم هر روتر: برای هر prefix مقصد، «گام بعدی» را می‌گوید. قانون انتخاب: بلندترین پیشوندِ منطبق (Longest Prefix Match) — مشخص‌ترین مسیر برنده است. پروتکل‌هایی مثل BGP این جدول‌ها را بین هزاران روتر دنیا هماهنگ می‌کنند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["IPv4 چهار عدد و IPv3 هگز طولانی؛ NAT آدرس‌ها را ترجمه می‌کند","netmask مرز شبکه و دستگاه را جدا می‌کند","هر روتر فقط گام بعدی را می‌داند نه کل مسیر"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"ip.sh","code":"ip addr              # آدرس‌های من\nip route             # جدول مسیریابی\ntraceroute 8.8.8.8   # گام‌های مسیر تا مقصد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: IPv4 چهار عدد و IPv3 هگز طولانی؛ NAT آدرس‌ها را ترجمه می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا NAT لازم شد؟","opts":["برای سرعت","چون آدرس‌های IPv4 تمام شدند و NAT چند دستگاه را پشت یک آدرس عمومی می‌برد","برای امنیت فقط","اجباری نیست"],"ans":1,"why":"فضای IPv4 محدود است؛ NAT آدرس‌های خصوصی داخل خانه را به یک آدرس عمومی ترجمه می‌کند تا همه به اینترنت برسند."},{"q":"چرا MAC برای مسیریابی جهانی کافی نیست؟","opts":["کوتاه است","چون تخت است و سلسله‌مراتب ندارد — از رویش معلوم نیست دستگاه کجای دنیاست؛ IP با prefix شبکه‌ای، مسیر‌یابی را ممکن می‌کند","قدیمی است","امن نیست"],"ans":1,"why":"با MAC، هر روتر دنیا باید آدرس تک‌تک دستگاه‌ها را بداند — غیرممکن. سلسله‌مراتب IP یعنی «اول برو به سمت شبکه مقصد، آنجا بپرس» — مثل آدرس پستی."},{"q":"NAT دقیقاً چه می‌کند؟","opts":["رمزنگاری","آدرس‌ها و پورت‌های خصوصیِ داخلی را به یک آدرس عمومی ترجمه می‌کند و با جدول ترجمه، پاسخ هر اتصال را به دستگاه درست برمی‌گرداند","فشرده‌سازی","کش DNS"],"ans":1,"why":"چند دستگاه خصوصی پشت یک آدرس عمومی — و جدول ترجمه پورت‌ها مشخص می‌کند پاسخ اتصال ۵۱۲۳۴ مال لپ‌تاپ است یا گوشی. کمبود IPv4 را دهه‌ها کش داد."}]'::jsonb),
('net-b4', 'net', 'DNS و نام‌گذاری', 63, 16, '[{"k":"p","t":"DNS نام خوانا را به IP ترجمه می‌کند؛ مرورگر اول کش محلی، بعد سرور DNS را می‌پرسد و جواب کش می‌شود تا دوباره پرسیده نشود."},{"k":"h","t":"DNS؛ دیتابیس توزیع‌شده‌ای که هر روز می‌بینی"},{"k":"p","t":"مرورگرها با IP حرف می‌زنند ولی انسان‌ها با نام — و DNS دفترچه تلفن بین این دو دنیاست. ولی نه یک دفترچه مرکزی؛ یک درخت توزیع‌شده از سرورهای مستقل: ریشه (.) می‌داند com کجاست، سرورهای com می‌دانند example.com کجاست، و سرور خود example آدرس نهایی را می‌دهد. این recursive resolution با کش در هر سطح، معمولاً چند میلی‌ثانیه طول می‌کشد. رکوردها انواع دارند: A (نام به IPv4)، AAAA (به IPv6)، CNAME (نام به نام — مثل www به root)، MX (سرور ایمیل) و TXT (هر متن — برای اثبات مالکیت و SPF). و TTL روی هر رکورد می‌گوید «چقدر کش کن» — کم بودنش تغییرات را سریع پخش می‌کند ولی بار سرور را زیاد؛ تنظیم TTL قبل از مهاجرت سرور، یک مهارت عملی واقعی است."},{"k":"h","t":"جایی که DNS امنیتی می‌شود؛ از مسمومیت تا DoH"},{"k":"p","t":"DNS در اصل بدون امضا بود — هر کسی می‌توانست پاسخ جعلی بفرستد و کاربر را به سایت قلابی ببرد (مسمومیت کش یا حمله MITM). دو لایه دفاع آمد: DNSSEC که پاسخ‌ها را با امضای رمزنگاری تأیید می‌کند (و اگر امضا نخورد، رکورد بی‌اعتبار است)، و DoH/DoT که کل پرس‌وجو را داخل HTTPS/TLS می‌برد تا شنود و دستکاری در مسیر ناممکن شود. امروز دو نکته عملی برای توسعه‌دهنده: اول، کش DNS را دست‌کم نگیر — بعد از تغییر IP سرور، کاربران تا پایان TTL نسخه قدیمی را می‌بینند (پس TTL را از قبل پایین بیاور). دوم، اگر سایتت «روی بعضی ISPها باز نمی‌شود»، اول dig و nslookup روی سرورهای مختلف (8.8.8.8 و 1.1.1.1) بزن — نصف دیباگ‌های «سایت دان است» در واقع مشکل DNS است، نه سرور."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"جراحی یک نام با dig","code":"# رکورد A (آدرس IP):\ndig +short example.com              # 93.184.215.14\n\n# زنجیره کامل — از ریشه تا جواب:\ndig +trace example.com | tail -4\n\n# سرور ایمیل‌ها:\ndig +short MX gmail.com\n# 5 gmail-smtp-in.l.google.com.\n\n# TTL چقدر است؟ (کش تا کی معتبر است)\ndig example.com | grep -A1 ''ANSWER''\n# example.com.  3600  IN  A  93.184.215.14\n#               ^^^^ ثانیه کش\n\n# پرس‌وجو از سرور خاص (دیباگ DNS):\ndig @1.1.1.1 example.com +short"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["رکورد","نگاشت","کاربرد"],"rows":[["A / AAAA","نام → IP (v4 / v6)","آدرس اصلی سایت"],["CNAME","نام → نام دیگر","www، زیردامنه‌ها به سرویس‌ها"],["MX","دامنه → سرور ایمیل","ایمیل با اولویت"],["TXT","دامنه → متن دلخواه","SPF، اثبات مالکیت، DKIM"],["NS","دامنه → سرور DNS مسئول","تفویض زیردامنه"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["دامنه سلسله‌مراتبی: com → example → www","سرورهای ریشه، TLD و authoritative به ترتیب پرسیده می‌شوند","TTL عمر کش هر رکورد است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"dns.sh","code":"dig example.com +short      # IP\ndig example.com MX +short   # سرور ایمیل\nnslookup google.com"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: دامنه سلسله‌مراتبی: com → example → www بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا DNS جواب را کش می‌کند؟","opts":["برای امنیت","تا پرسش‌های تکراری به سرورهای بالادست نرسد و سرعت بالا برود","اجباری","برای رمزنگاری"],"ans":1,"why":"میلیون‌ها بار example.com پرسیده می‌شود؛ کش با TTL از بار سرورهای ریشه کم و پاسخ را فوری می‌کند."},{"q":"چرا تغییر IP سرور، برای همه کاربران بلافاصله اعمال نمی‌شود؟","opts":["سرور کند است","چون رکورد DNS با TTL در چند سطح کش شده — تا انقضای TTL، کش‌های میانی همان IP قدیمی را برمی‌گردانند","باگ مرورگر","NAT مشکل دارد"],"ans":1,"why":"هر resolver رکورد را تا TTL نگه می‌دارد. قبل از مهاجرت، TTL را از روزها به چند دقیقه کم کن تا بعد از تغییر، پخش سریع شود — بعدش دوباره بالا ببر."},{"q":"تفاوت CNAME با A چیست؟","opts":["هیچ","A نام را مستقیم به IP می‌برد؛ CNAME نام را به نام دیگری ارجاع می‌دهد که بعداً خودش resolve می‌شود","سرعت","امنیت"],"ans":1,"why":"CNAME یعنی «این نام، همان آن نام است» — مثل alias. برای وصل‌کردن زیردامنه به سرویس‌های ابری (shop.mysite → shops.platform.com) عالی است چون IP سرویس عوض شود، تو تغییری نمی‌خواهی."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('net-b5', 'net', 'HTTP و متدها', 56, 17, '[{"k":"p","t":"HTTP پروتکل درخواست/پاسخ وب است؛ متد عمل را و کد وضعیت نتیجه را می‌گوید. HTTP/1.1 متنی و HTTP/2 و ۳ سریع‌تر و با چندمسیره‌ای."},{"k":"h","t":"متدها؛ فعل‌های زبان منابع"},{"k":"p","t":"هر متد HTTP یک «نیت» را اعلام می‌کند و سرور بر اساس آن رفتار می‌کند. GET فقط می‌خواند و باید idempotent باشد (تکرارش وضعیت را عوض نکند)، POST می‌سازد و تکرارش ممکن است چند منبع بسازد، PUT جایگزین کامل می‌کند و PATCH تغییر جزئی است. وقتی تیمی این قرارداد را جدی بگیرد، API خودش توضیح می‌دهد چه می‌کند — بدون خواندن مستندات. معنای دیگر متدها، قابلیت کش‌شدن است: پاسخ GET قابل کش است ولی POST نیست؛ پس انتخاب درست متد مستقیماً روی عملکرد اثر دارد."},{"k":"h","t":"کد وضعیت؛ جواب کوتاه ولی گویا"},{"k":"p","t":"کدهای وضعیت در پنج خانواده‌اند و هرکدام یک پیام روشن دارند: 2xx موفقیت (200 باشه، 201 ساخته شد، 204 موفق ولی بی‌بدنه)، 3xx جابه‌جایی (301 دائم، 302 موقت)، 4xx خطای کلاینت (400 درخواست بد، 401 احراز هویت لازم، 403 ممنوع، 404 نیست، 409 تعارض)، 5xx خطای سرور (500 داخلی، 503 در دسترس نیست). تفاوت 401 و 403 را خیلی‌ها اشتباه می‌گیرند: اولی یعنی «نمی‌دانم کی هستی» و دومی یعنی «می‌دانم کی هستی ولی اجازه نداری». کد درست، دیباگ را برای مصرف‌کننده چند برابر ساده‌تر می‌کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["متد","نیت","Idempotent","کش‌پذیر"],"rows":[["GET","خواندن","بله","بله"],["POST","ساختن","خیر","خیر"],["PUT","جایگزینی کامل","بله","خیر"],["PATCH","تغییر جزئی","خیر","خیر"],["DELETE","حذف","بله","خیر"]]},{"k":"tip","title":"نکته منتور","t":"اگر عملیاتی «خواندنی» است ولی پارامترهایش طولانی از حد URL می‌شود، وسوسه نشو POST کنی — بهتر است ساختار را بازبینی کنی؛ چون با POST، قابلیت کش و idempotency را از دست می‌دهی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["GET خواندن، POST ارسال، PUT جایگزینی، DELETE حذف","کد ۲xx موفق، ۳xx ریدایرکت، ۴xx خطای کاربر، ۵xx خطای سرور","هدرها متادیتا می‌برند: Content-Type، Authorization"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"http.sh","code":"curl -i https://api.example.com/users\n# HTTP/2 200\n# content-type: application/json\n# [...بدنه...]"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: GET خواندن، POST ارسال، PUT جایگزینی، DELETE حذف بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت ۴۰۴ و ۵۰۰ چیست؟","opts":["هیچ","۴۰۴ یعنی منبع پیدا نشد (خطای درخواست)؛ ۵۰۰ یعنی سرور حین پردازش خطا کرد","سرعت","نوع متد"],"ans":1,"why":"404 تقصیر درخواست است (مسیر اشتباه)؛ 500 تقصیر سرور است (باگ یا خرابی داخلی)."},{"q":"تفاوت اصلی PUT و PATCH چیست؟","opts":["هیچ","PUT کل منبع را جایگزین می‌کند ولی PATCH فقط بخش‌های تغییرکرده را می‌فرستد","PUT سریع‌تر است","PATCH فقط برای حذف"],"ans":1,"why":"در PUT باید کل منبع را بفرستی و هر فیلدی که نفرستی پاک می‌شود؛ در PATCH فقط تغییرات را می‌فرستی و بقیه دست‌نخورده می‌مانند."},{"q":"کد 403 چه می‌گوید؟","opts":["کاربر وجود ندارد","هویت مشخص است ولی دسترسی کافی نیست","سرور خراب است","منبع جابه‌جا شده"],"ans":1,"why":"401 یعنی احراز هویت نشده‌ای؛ 403 یعنی احراز هویت شدی ولی این کار را اجازه نداری — تفاوت ظریفی که در طراحی API مهم است."}]'::jsonb),
('net-b6', 'net', 'HTTPS و TLS', 63, 18, '[{"k":"p","t":"HTTPS یعنی HTTP روی TLS؛ TLS با رمزنگاری نامتقارن کلید ردوبدل و بعد با کلید متقارن داده را رمز می‌کند و با گواهی هویت سرور را تأیید می‌کند."},{"k":"h","t":"دست‌دادن TLS؛ اعتماد از کجا می‌آید"},{"k":"p","t":"وقتی به یک سایت HTTPS وصل می‌شوی، قبل از ردوبدل شدن حتی یک بایت داده، یک دست‌دادن رخ می‌دهد که سه کار می‌کند: هویت سرور را با گواهی تأیید می‌کند، یک کلید متقارن سری را به‌صورت امن ردوبدل می‌کند و الگوریتم رمز را توافق می‌کند. نکته ظریف اینجاست که رمزنگاری نامتقارن (RSA/ECDHE) فقط برای همان لحظه توافق استفاده می‌شود چون کند است؛ بعد از آن همه داده با کلید متقارن (AES) رمز می‌شود که سریع است. پس TLS ترکیب هوشمندانه «امنیت نامتقارن» و «سرعت متقارن» است."},{"k":"h","t":"گواهی و زنجیره اعتماد"},{"k":"p","t":"گواهی SSL سندی است که یک مرجع مورد اعتماد (CA) امضایش کرده و می‌گوید «این کلید عمومی واقعاً مال example.com است». مرورگر خودش به چند ده CA ریشه اعتماد دارد و با دنبال‌کردن زنجیره امضاها، گواهی سایت را راستی‌آزمایی می‌کند. اگر کسی بخواهد در وسط راه خودش را جا بزند (MITM)، گواهی جعلی‌اش امضای CA معتبر ندارد و مرورگر هشدار قرمز می‌دهد. امروز با Let''s Encrypt صدور گواهی رایگان و خودکار شده، پس بهانه‌ای برای HTTP ساده باقی نمانده است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"مشاهده گواهی یک سایت","code":"# اطلاعات گواهی و زنجیره اعتماد را ببین\necho | openssl s_client -connect bitcode.ir:443 2>/dev/null \\\n  | openssl x509 -noout -subject -issuer -dates\n\n# خروجی چیزی شبیه این است:\n# subject=CN = bitcode.ir\n# issuer=CN = R3, O = Let''s Encrypt   ← صادرکننده\n# notAfter=Sep 10 12:00:00 2026 GMT   ← انقضا"},{"k":"tip","title":"نکته منتور","t":"اگر در توسعه محلی با گواهی خودامضا کار می‌کنی و مرورگر هشدار می‌دهد، این طبیعی است — ولی هیچ‌وقت در کد کلاینت، بررسی گواهی را disable نکن؛ این یکی از شایع‌ترین حفره‌های امنیتی اپ‌های موبایل است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["گواهی توسط CA امضا شده و مرورگر آن را اعتبارسنجی می‌کند","TLS ابتدا نامتقارن (سنگین) برای تبادل کلید، بعد متقارن (سریع)","بدون HTTPS داده‌ها در مسیر خوانا‌اند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"tls.sh","code":"openssl s_client -connect example.com:443 \\\n  -brief   # خلاصه دست‌دادن TLS\ncurl -v https://example.com 2>&1 | grep ''SSL''"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: گواهی توسط CA امضا شده و مرورگر آن را اعتبارسنجی می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"TLS چرا از رمزنگاری ترکیبی استفاده می‌کند؟","opts":["تصادفی","چون نامتقارن امن ولی کند است؛ فقط برای تبادل کلید متقارنِ سریع استفاده می‌شود","برای فشرده‌سازی","اجباری"],"ans":1,"why":"رمز متقارن برای حجم داده سریع است ولی تبادل کلیدش مشکل دارد؛ نامتقارن کلید را امن منتقل می‌کند و بعد متقارن ادامه می‌دهد."},{"q":"چرا TLS بعد از دست‌دادن به رمز متقارن می‌رود؟","opts":["چون امن‌تر است","چون رمز متقارن برای حجم بالای داده بسیار سریع‌تر است","چون نامتقارن منسوخ شده","تصادفی"],"ans":1,"why":"رمز نامتقارن صدها برابر کندتر است؛ پس فقط برای توافق امنِ یک کلید متقارن استفاده می‌شود و بعد، تبادل واقعی داده با سرعت AES انجام می‌شود."},{"q":"هشدار قرمز مرورگر برای گواهی یعنی چه؟","opts":["سایت کند است","گواهی امضای یک CA مورد اعتماد را ندارد یا با دامنه یکی نیست","اینترنت قطع است","سرور HTTPS ندارد"],"ans":1,"why":"مرورگر زنجیره امضاها را تا یک CA ریشه که می‌شناسد دنبال می‌کند؛ اگر به آن نرسد یا دامنه گواهی با آدرس یکی نباشد، یعنی هویت سرور تأیید نشده و ممکن است MITM باشد."}]'::jsonb),
('net-b7', 'net', 'Socket و برنامه‌نویسی شبکه', 63, 19, '[{"k":"p","t":"Socket انتهای یک ارتباط شبکه است؛ سرور با listen و accept منتظر می‌ماند و client با connect وصل می‌شود — پایه همه ارتباطات شبکه‌ای."},{"k":"h","t":"Socket؛ پایین‌ترین سطح گفت‌وگو"},{"k":"p","t":"همه چیز در شبکه — از HTTP تا بازی آنلاین — در نهایت به Socket می‌رسد: یک انتهای ارتباط که با آدرس IP و پورت مشخص می‌شود. سرور با listen روی یک پورت منتظر می‌ماند، با accept یک اتصال جدید را می‌پذیرد و بعد می‌تواند بخواند و بنویسد؛ کلاینت هم با connect وصل می‌شود. این مدل «اتصال‌گرا» (TCP) تضمین می‌کند داده به ترتیب و کامل برسد. درک این لایه پایین کمک می‌کند بفهمی چرا هر وب‌سرور محدودیت تعداد اتصال دارد و چرا پورت‌ها مهم‌اند."},{"k":"h","t":"TCP یا UDP؛ انتخاب بر اساس تحمل از دست دادن"},{"k":"p","t":"TCP با دست‌دادن و تأیید دریافت، تحویل مطمئن می‌دهد ولی سربار و تأخیر دارد. UDP هیچ تضمینی نمی‌دهد — بسته را می‌فرستد و تمام — ولی سبک و سریع است. پس انتخاب این است: اگر از دست رفتن یک بسته یعنی خرابی (انتقال فایل، وب)، TCP؛ اگر تأخیر مهم‌تر از کامل‌بودن است (پخش زنده، بازی، DNS)، UDP. جالب اینکه QUIC — پروتکل پایه HTTP/3 — روی UDP سوار شده ولی قابلیت‌های قابل‌اعتمادی شبیه TCP را خودش در لایه بالاتر بازسازی کرده تا از مشکل head-of-line blocking خلاص شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"یک اکوی ساده با Socket","code":"import socket\n\n# --- سرور ---\ns = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\ns.bind((''localhost'', 9000))\ns.listen(1)                    # منتظر یک اتصال\nconn, addr = s.accept()        # اتصال پذیرفته شد\ndata = conn.recv(1024)         # خواندن\nconn.sendall(data)             # پژواک\nconn.close()\n\n# --- کلاینت (در ترمینالی دیگر) ---\nc = socket.socket()\nc.connect((''localhost'', 9000))\nc.sendall(b''salam'')\nprint(c.recv(1024))            # b''salam''"},{"k":"tip","title":"نکته منتور","t":"همیشه برای عملیات‌های socket مهلت (timeout) بگذار؛ وگرنه یک recv روی اتصال مرده می‌تواند thread را برای همیشه بلوکه کند و سرورت ظاهراً سالم ولی عملاً فلج شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سرور: socket → bind → listen → accept","client: socket → connect → send/recv","آدرس = IP + پورت؛ پورت برنامه را مشخص می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"socket.py","code":"import socket\ns = socket.socket()\ns.bind((''0.0.0.0'', 8080))\ns.listen()\nconn, addr = s.accept()\ndata = conn.recv(1024)\nconn.send(b''salam'')"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سرور: socket → bind → listen → accept بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"نقش پورت چیست؟","opts":["سرعت","مشخص‌کردن برنامه مقصد روی یک دستگاه؛ IP دستگاه و پورت برنامه را می‌دهد","رمزنگاری","فشرده‌سازی"],"ans":1,"why":"یک سرور چند سرویس دارد (وب ۸۰، ssh ۲۲)؛ پورت می‌گوید بسته به کدام برنامه برسد."},{"q":"نقش accept در سرور socket چیست؟","opts":["پورت را باز می‌کند","یک اتصال ورودی در صف را می‌پذیرد و یک socket اختصاصی برای آن برمی‌گرداند","داده را می‌خواند","اتصال را می‌بندد"],"ans":1,"why":"listen فقط صف اتصال می‌سازد؛ این accept است که یک اتصال را از صف برمی‌دارد و socket جدیدی برای گفت‌وگوی واقعی با همان کلاینت برمی‌گرداند."},{"q":"چرا بازی‌های آنلاین معمولاً UDP را ترجیح می‌دهند؟","opts":["چون امن‌تر است","چون تأخیر کم مهم‌تر از رسیدن همه بسته‌هاست","چون TCP قدیمی است","چون رایگان است"],"ans":1,"why":"در بازی، یک موقعیت دیررسیده بی‌فایده است؛ بهتر است بسته‌ای گم شود تا اینکه منتظر بازفرستادنش بمانی. UDP تأخیر را حداقل نگه می‌دارد."}]'::jsonb),
('net-b8', 'net', 'CDN و کش', 56, 20, '[{"k":"p","t":"CDN محتوا را در سرورهای نزدیک کاربر کپی می‌کند تا تأخیر کم شود؛ کش در مرورگر، CDN و سرور هرکدام جلوی درخواست تکراری را می‌گیرند."},{"k":"h","t":"CDN؛ جابه‌جایی محتوا به سمت کاربر"},{"k":"p","t":"فاصله فیزیکی یعنی تأخیر: نور هم در فیبر با سرعت محدود حرکت می‌کند و هر هزار کیلومتر چند میلی‌ثانیه اضافه می‌کند. CDN این فاصله را حذف می‌کند با کپی‌کردن محتوای تو در ده‌ها نقطه جهان؛ وقتی کاربری از شیراز عکسی را می‌خواهد، از سرور شیراز یا نزدیک‌ترین نقطه می‌گیرد نه از دیتاسنتر اصلی. برای محتوای ایستا (عکس، CSS، JS، ویدیو) این یعنی کاهش چشمگیر زمان بارگذاری. DNS هوشمند، کاربر را به نزدیک‌ترین edge هدایت می‌کند."},{"k":"h","t":"لایه‌های کش؛ هرکدام جلوی درخواست تکراری"},{"k":"p","t":"کش فقط در CDN نیست؛ یک زنجیره است: کش مرورگر (با هدرهای Cache-Control)، کش CDN، کش سرور (مثل Redis برای نتیجه query) و کش دیتابیس. هر لایه که پاسخ را داشته باشد، درخواست اصلاً به لایه بعدی نمی‌رسد. هنر، تنظیم درست TTL هر لایه است: محتوای تغییرناپذیر (فایل‌های hash‌دار باندل) را می‌شود یک سال کش کرد، ولی داده‌ای که لحظه‌ای عوض می‌شود نباید کش شود یا باید با مکانیزم invalidation همراه باشد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["لایه کش","کجا","مناسب برای"],"rows":[["مرورگر","دستگاه کاربر","فایل‌های ایستا و hash‌دار"],["CDN","نقاط edge جهان","عکس، ویدیو، JS/CSS"],["سرور (Redis)","کنار اپلیکیشن","نتیجه query و محاسبات"],["دیتابیس","داخل DB","buffer pool"]]},{"k":"warn","title":"دام رایج","t":"کش‌کردن محتوای پویا بدون invalidation، منبع کلاسیک باگ «داده را عوض کردم ولی نشان نمی‌دهد» است. یا به داده‌های پویا کش نده، یا کلید کش را به نسخه داده گره بزن تا با تغییر، خودکار منقضی شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["CDN فایل‌های استاتیک را از نزدیک‌ترین لبه می‌دهد","Cache-Control و ETag به مرورگر می‌گویند تا کی کش معتبر است","کش نامعتبر (stale) باید با نسخه‌بندی فایل حل شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"مسیر درخواست با CDN","code":"کاربر → لبه CDN (نزدیک) → [کش داشت؟ بده]\n                          → [نداشت؟ از سرور اصلی بگیر]\nسرور اصلی فقط برای missها"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: CDN فایل‌های استاتیک را از نزدیک‌ترین لبه می‌دهد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"CDN چطور تأخیر را کم می‌کند؟","opts":["فشرده می‌کند","با نگه‌داشتن محتوا در سرورهای نزدیک کاربر، فاصله فیزیکی و تعداد پرش‌ها کم می‌شود","سرور را زیاد می‌کند","رمز نمی‌کند"],"ans":1,"why":"به‌جای رفتن تا سرور اصلی آن‌ور دنیا، کاربر از لبه نزدیک شهرش محتوا می‌گیرد؛ مسافت کمتر یعنی تأخیر کمتر."},{"q":"چرا CDN زمان بارگذاری را کم می‌کند؟","opts":["چون فایل‌ها را فشرده می‌کند","چون محتوا را در نقطه‌ای نزدیک کاربر سرو می‌کند و تأخیر شبکه کم می‌شود","چون سرور را قوی‌تر می‌کند","چون تبلیغ ندارد"],"ans":1,"why":"با حذف فاصله فیزیکی بین کاربر و محتوا، زمان رفت‌وبرگرد (RTT) کم می‌شود؛ فشرده‌سازی اثر جدا و مکملی است."},{"q":"محتوای hash‌دار (app.3f2a.js) را چرا می‌شود یک سال کش کرد؟","opts":["چون کوچک است","چون با هر تغییر، نام فایل عوض می‌شود پس نسخه قدیمی هرگز با محتوای جدید اشتباه گرفته نمی‌شود","چون CDN سریع است","چون مرورگر مجبور است"],"ans":1,"why":"hash بخشی از نام فایل است؛ پس محتوای جدید hash جدید و URL جدید می‌گیرد و کش‌های قدیمی بی‌ضرر می‌شوند — این یعنی کش‌کردن نامحدود بدون نگرانی از invalidation."}]'::jsonb),
('net-b9', 'net', 'REST و طراحی API', 56, 21, '[{"k":"p","t":"REST سبکی برای طراحی API است که منابع را با URL و عملیات را با متد HTTP مدل می‌کند؛ API خوب قابل‌پیش‌بینی و خودتوصیف است."},{"k":"h","t":"منبع‌محوری؛ قلب REST"},{"k":"p","t":"REST یعنی API را به‌صورت مجموعه‌ای از «منابع» مدل کنی که هرکدام URL خودشان را دارند و عملیات با متد HTTP انجام می‌شود — نه با فعل‌های دلخواه در URL. به‌جای /getUser?id=5 و /deleteUser?id=5، می‌نویسی GET /users/5 و DELETE /users/5. این سبک چند برد دارد: URLها قابل‌حدس‌اند، از متدها و کش HTTP رایگان بهره می‌بری و ساختار API با مدل داده‌ات هم‌راستا می‌شود. یک نشانه REST خوب این است که توسعه‌دهنده بتواند URL منبع بعدی را حدس بزند."},{"k":"h","t":"قراردادهایی که API را حرفه‌ای می‌کنند"},{"k":"p","t":"چند قرارداد کوچک، API را از «کار می‌کند» به «لذت‌بخش» می‌برند: اسم منابع جمع باشد (users نه user)، فیلتر و صفحه‌بندی با query string (؟status=active&page=2)، نسخه‌بندی در URL یا هدر (v1/) برای تغییرات شکننده، و پاسخ‌های خطا با بدنه ساختاریافته (کد + پیام + جزئیات) نه فقط کد وضعیت. مهم‌تر از همه، ثبات است: وقتی نام فیلدی را منتشر کردی، دیگر عوضش نکن — مصرف‌کننده‌ها به آن تکیه کرده‌اند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["عملیات","روش REST"],"rows":[["فهرست کاربران","GET /users"],["ساخت کاربر","POST /users → 201"],["جزئیات یک کاربر","GET /users/5"],["به‌روزرسانی کامل","PUT /users/5"],["تغییر جزئی","PATCH /users/5"],["حذف","DELETE /users/5 → 204"]]},{"k":"tip","title":"نکته منتور","t":"وقتی عملیاتی به‌راحتی در قالب CRUD نمی‌گنجد (مثل «انتقال پول»)، مجبور نیستی URL عجیب بسازی؛ یک منبعِ عمل تعریف کن: POST /transfers. REST انعطاف دارد، فقط باید منابع را هوشمندانه نام‌گذاری کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["منبع با اسم: /users/42 نه /getUser?id=42","متد عمل را می‌گوید: GET /users/42، DELETE /users/42","کد وضعیت و بدنه معنادار؛ نسخه‌بندی با /v1/"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"REST نمونه","code":"GET    /v1/articles        → لیست\nPOST   /v1/articles        → ساخت\nGET    /v1/articles/7      → یکی\nPATCH  /v1/articles/7      → ویرایش\nDELETE /v1/articles/7      → حذف"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: منبع با اسم: /users/42 نه /getUser?id=42 بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"در REST حذف یک مقاله کدام است؟","opts":["GET /delete/7","DELETE /v1/articles/7","POST /articles/7/delete","PUT /articles/7"],"ans":1,"why":"REST عمل را با متد می‌گوید نه در مسیر؛ DELETE روی مسیر منبع، آن را حذف می‌کند."},{"q":"چرا REST از متد HTTP به‌جای فعل در URL استفاده می‌کند؟","opts":["سلیقه‌ای است","چون URLها قابل‌حدس می‌مانند و از قابلیت‌های ذاتی HTTP مثل کش و idempotency بهره می‌بری","چون کوتاه‌تر است","اجباری است"],"ans":1,"why":"با جداسازی «منبع» (URL) از «عمل» (متد)، ساختار ساده و یکنواخت می‌ماند و لایه‌های زیرین (کش، proxy) می‌توانند بر اساس متد تصمیم درست بگیرند."},{"q":"چرا نام فیلدهای منتشرشده را نباید عوض کرد؟","opts":["چون سخت است","چون کلاینت‌های قدیمی به آن نام تکیه کرده‌اند و تغییرش همه‌شان را می‌شکند","چون کند می‌شود","ممکن است"],"ans":1,"why":"API یک قرارداد عمومی است؛ هزاران کلاینت ممکن است از فیلدی استفاده کنند که تو فراموش کرده‌ای. تغییر نام یعنی شکستن همه‌شان — مگر با نسخه‌بندی جدید."}]'::jsonb),
('net-b10', 'net', 'WebSocket و ارتباط دوطرفه', 56, 22, '[{"k":"p","t":"WebSocket بعد از یک دست‌دادن HTTP، اتصال دائمی دوطرفه باز نگه می‌دارد؛ برای چت و نوتیفیکیشن زنده که سرور باید خودش پیام بفرستد."},{"k":"h","t":"چرا HTTP برای چیزهای زنده کافی نیست"},{"k":"p","t":"HTTP مدل درخواست/پاسخ دارد: همیشه کلاینت باید اول حرف بزند. ولی در چت، نوتیفیکیشن و داشبورد زنده، این سرور است که باید بدون درخواست، پیام بفرستد. راه‌حل قدیمی polling بود (کلاینت هر چند ثانیه بپرسد «چیز جدیدی هست؟») که هم تأخیر دارد هم پهنای باند هدر می‌دهد. WebSocket این مشکل را حل می‌کند: با یک دست‌دادن اولیه HTTP، اتصال به حالت دائمی و دوطرفه ارتقا می‌یابد و بعد هر طرف هر لحظه می‌تواند پیام بفرستد — بدون سربار درخواست‌های تکراری."},{"k":"h","t":"SSE؛ وقتی فقط یک‌طرفه کافی است"},{"k":"p","t":"همیشه به دوطرفه کامل نیاز نیست. اگر فقط سرور باید به کلاینت بفرستد (نوتیفیکیشن، قیمت لحظه‌ای، خروجی build)، Server-Sent Events ساده‌تر است: یک GET که پاسخش باز می‌ماند و سرور مدام داده می‌فرستد. مزیت بزرگش این است که روی همان HTTP معمولی کار می‌کند، خودکار reconnect دارد و با CDN و proxy مشکل کمتری دارد. پس قبل از WebSocket بپرس: آیا واقعاً به ارسال از سمت کلاینت نیاز دارم؟ اگر نه، SSE انتخاب سبک‌تر است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Polling","SSE","WebSocket"],"rows":[["جهت","کلاینت→سرور","سرور→کلاینت","دوطرفه"],["پروتکل","HTTP","HTTP","ارتقایافته از HTTP"],["اتصال مجدد","دستی","خودکار","دستی"],["مناسب","تقریباً هیچ","نوتیفیکیشن، فید","چت، بازی"]]},{"k":"tip","title":"نکته منتور","t":"WebSocket چون اتصال دائمی است، با Load Balancer و مقیاس‌افقی کمی چالش دارد (اتصال کاربر به یک سرور خاص می‌چسبد). برای شروع و اکثر موارد، SSE یا حتی polling هوشمند ساده‌تر و قابل‌اتکاتر است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["با HTTP شروع و بعد به پروتکل ws ارتقا می‌یابد","هر دو طرف هر لحظه می‌توانند پیام بفرستند","برای داده زنده؛ برای درخواست‌های معمولی همان HTTP کافی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"ws.js","code":"const ws = new WebSocket(''wss://example.com/chat'');\nws.onmessage = e => console.log(''گرفتم:'', e.data);\nws.onopen = () => ws.send(''سلام'');"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: با HTTP شروع و بعد به پروتکل ws ارتقا می‌یابد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا برای چت WebSocket بهتر از HTTP است؟","opts":["جدیدتر","چون اتصال دائمی است و سرور بدون درخواستِ مکرر می‌تواند پیام بفرستد","امن‌تر","ساده‌تر"],"ans":1,"why":"با HTTP کلاینت باید مدام نظرسنجی کند؛ WebSocket اجازه می‌دهد سرور به‌محض آمدن پیام آن را بفرستد."},{"q":"مشکل اصلی polling چیست؟","opts":["امن نیست","هم تأخیر دارد (بین دو پرسش) و هم درخواست‌های تکراری پهنای باند و سرور را هدر می‌دهند","پیچیده است","قدیمی است"],"ans":1,"why":"با polling یا دیر متوجه می‌شوی (فاصله بین پرسش‌ها) یا با پرسش‌های پرتکرار منبع هدر می‌دهی — یک مصالحه همیشگی که WebSocket/SSE حذفش می‌کنند."},{"q":"کی SSE بر WebSocket ارجحیت دارد؟","opts":["هیچ‌وقت","وقتی فقط سرور باید پیام بفرستد؛ چون ساده‌تر است و روی HTTP معمولی کار می‌کند","وقتی بازی می‌سازی","وقتی چت دوطرفه داری"],"ans":1,"why":"اگر کلاینت نیازی به ارسال روی همان اتصال ندارد، SSE با reconnect خودکار و سازگاری بهتر با زیرساخت HTTP، راه‌حل سبک‌تر و قابل‌اتکاتری است."}]'::jsonb),
('net-b11', 'net', 'Latency و پهنای باند', 63, 23, '[{"k":"p","t":"پهنای باند حجم داده در ثانیه و تأخیر زمان رسیدن اولین بیت است؛ برای تجربه کاربری، تأخیر مهم‌تر از پهنای باند است و با فاصله فیزیکی رابطه مستقیم دارد."},{"k":"h","t":"پهنای باند در برابر تأخیر؛ دو معیار متفاوت"},{"k":"p","t":"این دو اغلب اشتباه گرفته می‌شوند: پهنای باند یعنی چه حجم داده‌ای در ثانیه می‌تواند رد شود (لوله چقدر پهن است) و تأخیر یعنی چقدر طول می‌کشد تا اولین بیت برسد (لوله چقدر طولانی است). برای دانلود یک فایل بزرگ، پهنای باند مهم است؛ ولی برای تجربه وب — که صدها درخواست کوچکِ رفت‌وبرگردی دارد — تأخیر حاکم است. به همین دلیل است که حتی با اینترنت پرسرعت، سایتی که سرورش آن‌طرف دنیاست، کند حس می‌شود: هر درخواست باید فاصله فیزیکی را طی کند."},{"k":"h","t":"قانون BDP؛ چرا یک درخواست کند، کل صفحه را می‌گیرد"},{"k":"p","t":"حاصل‌ضرب پهنای‌باند×تأخیر (BDP) می‌گوید در هر لحظه چه مقدار داده «در راه» است. در اتصالات پرسرعت با تأخیر بالا، این مقدار زیاد است و اگر پنجره TCP کوچک باشد، لوله پر نمی‌شود و سرعت واقعی خیلی کمتر از پهنای باند اسمی می‌شود. در وب هم اثر مشابهی هست: در HTTP/1.1 روی یک اتصال، درخواست‌ها پشت‌سرهم می‌روند و یکی کند همه را معطل می‌کند (head-of-line blocking). راه‌حل‌ها — چند اتصال، HTTP/2 multiplexing، QUIC — همه دارند همین گلوگاه تأخیر را دور می‌زنند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"اندازه‌گیری تأخیر واقعی","code":"# زمان هر مرحله از اتصال به یک سایت\ncurl -o /dev/null -s -w \\\n ''dns: %{time_namelookup}s\\nconnect: %{time_connect}s\\ntls: %{time_appconnect}s\\nttfb: %{time_starttransfer}s\\ntotal: %{time_total}s\\n'' \\\n https://example.com\n\n# ttfb (زمان تا اولین بایت) معیار خوبی برای تأخیر سرور است"},{"k":"tip","title":"نکته منتور","t":"وقتی می‌خواهی بدانی «چرا کند است»، اول TTFB را اندازه بگیر: اگر بالا بود مشکل از سرور/فاصله است (راه‌حل: CDN، بهینه‌سازی، سرور نزدیک‌تر)؛ اگر پایین بود و باز هم کند است، مشکل از حجم محتواست (راه‌حل: فشرده‌سازی، کش)."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نور در فیبر حدود ۲۰۰هزار کیلومتر بر ثانیه؛ فاصله یعنی تأخیر","بافرینگ ویدیو پهنای باند می‌خواهد؛ بازی تأخیر کم","RTT رفت‌وبرگشت کامل یک بسته است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"latency.sh","code":"ping -c 5 google.com    # RTT تا گوگل\nping -c 5 8.8.8.8\n# time=12.3 ms → فاصله و تعداد پرش‌ها"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نور در فیبر حدود ۲۰۰هزار کیلومتر بر ثانیه؛ فاصله یعنی تأخیر بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا بازی آنلاین به تأخیر حساس‌تر از دانلود است؟","opts":["گرافیک دارد","چون تعامل لحظه‌ای است؛ ۱۰۰ms تأخیر در بازی محسوس است ولی در دانلود فقط کمی دیرتر تمام می‌شود","حجم کمتر","رمزنگاری"],"ans":1,"why":"در دانلود، تأخیر فقط شروع را عقب می‌اندازد و پهنای باند مهم است؛ در بازی هر عمل باید فوراً نتیجه بدهد."},{"q":"برای وب‌گردی روزمره کدام مهم‌تر است؟","opts":["پهنای باند","تأخیر — چون وب یعنی صدها درخواست کوچکِ رفت‌وبرگردی","هر دو برابر","هیچ‌کدام"],"ans":1,"why":"هر درخواست HTTP باید یک رفت‌وبرگرد کامل شبکه را طی کند؛ پس تعداد این رفت‌وبرگردها و تأخیر هرکدام، تجربه را تعیین می‌کنند نه حجم لوله."},{"q":"head-of-line blocking در HTTP/1.1 یعنی چه؟","opts":["سرور شلوغ است","روی یک اتصال، درخواست‌ها پشت‌سرهم‌اند و یک درخواست کند، بقیه را معطل می‌کند","اینترنت قطع شده","کش پر است"],"ans":1,"why":"در HTTP/1.1 پاسخ‌ها روی یک اتصال به ترتیب می‌آیند؛ پس یک پاسخ دیررس، همه پاسخ‌های پشت سرش را بلوکه می‌کند — مشکل اصلی‌ای که HTTP/2 با multiplexing حل کرد."}]'::jsonb),
('net-b12', 'net', 'فایروال و امنیت پایه شبکه', 63, 24, '[{"k":"p","t":"فایروال ترافیک را بر اساس قوانین فیلتر می‌کند؛ اصل کمترین دسترسی یعنی فقط پورت‌های لازم باز باشند و بقیه بسته."},{"k":"h","t":"فایروال؛ دربان ترافیک"},{"k":"p","t":"فایروال با مجموعه‌ای از قوانین تصمیم می‌گیرد هر بسته ورودی یا خروجی رد شود یا نه — بر اساس IP، پورت و پروتکل. روی سرور اوبونتو، ufw ساده‌ترین ابزار است: به‌طور پیش‌فرض همه‌چیز را می‌بندی و فقط پورت‌های لازم (مثل 22 برای SSH و 443 برای HTTPS) را باز می‌کنی. این «پیش‌فرض بسته» همان اصل کمترین دسترسی است: اگر سرویسی ناخواسته روی پورتی بالا بیاید، از بیرون دیده نمی‌شود چون فایروال راهش را بسته است."},{"k":"h","t":"لایه‌های دفاع؛ فقط فایروال کافی نیست"},{"k":"p","t":"فایروال فقط اولین لایه است. دفاع عمیق یعنی چند سد مستقل: فایروال شبکه (چه پورت‌هایی بازند)، فایروال سیستم (ufw)، سخت‌سازی سرویس‌ها (SSH فقط با کلید و نه رمز، و ترجیحاً روی پورت غیراستاندارد)، به‌روزرسانی امنیتی منظم، و TLS برای رمزکردن ترافیک. نکته مهم این است که هر لایه فرض می‌کند لایه قبلی ممکن است شکسته شود؛ پس حتی اگر کسی از فایروال رد شد، باز هم موانع بعدی سر راهش هست. امنیت یک دیوار بلند نیست، چند دیوار کوتاه پشت‌سرهم است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"پیکربندی پایه ufw","code":"# پیش‌فرض: همه ورودی‌ها بسته، همه خروجی‌ها باز\nsudo ufw default deny incoming\nsudo ufw default allow outgoing\n\n# فقط پورت‌های لازم را باز کن\nsudo ufw allow 22/tcp     # SSH\nsudo ufw allow 443/tcp    # HTTPS\nsudo ufw allow 80/tcp     # HTTP (برای ریدایرکت)\n\nsudo ufw enable\nsudo ufw status verbose   # بررسی قوانین فعال"},{"k":"warn","title":"دام رایج","t":"قبل از فعال‌کردن ufw روی یک سرور راه‌دور، حتماً پورت SSH را باز کن؛ وگرنه به‌محض enable شدن، خودت را بیرون قفل می‌کنی و فقط با دسترسی کنسول (از پنل هاستینگ) برمی‌گردی — تجربه‌ای که هر ادمینی یک بار دارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["فقط پورت‌های لازم را باز کن (۸۰، ۴۴۳، ۲۲)","ssh را با کلید بگذار نه رمز و پورتش را عوض نکن، محدودش کن","هر سرویس غیرضروری یک سطح حمله است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"firewall.sh","code":"ufw default deny incoming\nufw allow 22/tcp    # ssh\nufw allow 443/tcp   # https\nufw enable\nufw status"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: فقط پورت‌های لازم را باز کن (۸۰، ۴۴۳، ۲۲) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اصل کمترین دسترسی در شبکه یعنی چه؟","opts":["همه بسته","فقط پورت‌ها و سرویس‌های واقعاً لازم باز باشند تا سطح حمله کوچک شود","رمز قوی","فایروال خاموش"],"ans":1,"why":"هر پورت باز یک درِ احتمالی برای مهاجم است؛ با بستن همه و بازکردن فقط لازم‌ها، درها حداقل می‌شود."},{"q":"اصل کمترین دسترسی در فایروال یعنی چه؟","opts":["همه پورت‌ها باز باشند","پیش‌فرض همه‌چیز بسته است و فقط پورت‌های واقعاً لازم باز می‌شوند","فقط پورت ۸۰ باز باشد","هیچ پورتی باز نباشد"],"ans":1,"why":"با پیش‌فرض بسته، هر سرویس جدیدی که ناخواسته بالا بیاید از بیرون قابل‌دسترس نیست؛ فقط چیزهایی که آگاهانه باز کرده‌ای دیده می‌شوند."},{"q":"چرا امنیت را «دفاع عمیق» می‌گویند؟","opts":["چون گران است","چون چند لایه مستقل پشت‌سرهم است و شکستن یکی، نفوذ کامل نمی‌دهد","چون پیچیده است","چون عمیق است"],"ans":1,"why":"هیچ لایه‌ای بی‌نقص نیست؛ اگر مهاجم از فایروال رد شد، هنوز SSH سخت‌شده، TLS و به‌روزرسانی‌ها سر راهش‌اند. هر لایه، زمان و هزینه نفوذ را بالا می‌برد."}]'::jsonb),
('v-l1', 'vibe', 'وایب کدینگ چیست؟ تولد یک پارادایم', 65, 1, '[{"k":"p","t":"فوریه ۲۰۲۵، آندری کارپاتی — کسی که سال‌ها تیم هوش مصنوعی تسلا را رهبری کرد و از بنیان‌گذاران OpenAI بود — واژه‌ای ساخت که در چند هفته کل صنعت را گرفت: Vibe Coding. تعریفش این بود: «کاملاً به وایب (حس و حال) تن بده، وجودِ کد را فراموش کن؛ به هوش مصنوعی بگو چه می‌خواهی، خروجی را اجرا کن، اگر خطا داد متن خطا را برگردان به او، و آن‌قدر تکرار کن تا کار کند.» جنجال از همان جمله دوم شروع شد — چون کارپاتی این را برای «پروژه‌های یک‌آخرهفته‌ای» توصیف کرد، نه سیستم‌های بانکی. و تمام بحث امروز وایب کدینگ، دقیقاً همین مرز است: کجا رهایش کنی، کجا فرمان را پس بگیری."},{"k":"p","t":"برای فهمیدن عمق ماجرا، تاریخچه را در چهار پله ببین. پله اول (۲۰۱۸): تکمیل خودکار — Copilotِ اولیه که بقیه خط را حدس می‌زد؛ تایپ کمی کمتر، فکر همان. پله دوم (۲۰۲۲): چت — سوال بپرس و کد بگیر؛ ولی کپی‌پیست با دست، و Context محدود به سوال تو. پله سوم (۲۰۲۴): جفت‌برنامه‌نویس — ابزارهایی مثل Cursor که کل ریپازیتوری را می‌خوانند، چند فایل را همزمان ویرایش می‌کنند و Terminal را هم اجرا می‌کنند؛ اینجا دیگر «همکار» داری نه «ماشین تحریر». پله چهارم (۲۰۲۵): عامل (Agent) — هدف را بگو، خودش برنامه می‌ریزد، کد می‌زند، تست می‌کند، خطا را برمی‌گرداند و اصلاح می‌کند؛ تو فقط دمو را تماشا و جهت را اصلاح می‌کنی. وایب کدینگ، زندگی‌کردن در پله چهارم است."},{"k":"visual","visual":"vibeLoop","title":"شبیه‌ساز: حلقه وایب کدینگ — قدم‌به‌قدم جلو برو"},{"k":"p","t":"حلقه وایب کدینگ پنج مرحله دارد و سرعت واقعی در درست انجام‌دادن مرحله اول است — نه آخر. اول «مشخصات»: آنچه می‌خواهی را در یک فایل spec.md بنویس — هدف، کاربران، صفحات، قوانین و آنچه صریحاً نمی‌خواهی. دوم «پرامپت»: مشخصات را با Context فنی (زبان، فریم‌ورک، سبک) به Agent بده. سوم «تولید»: Agent کد را می‌سازد — و این‌جا جایی است که تازه‌کارها هیجان‌زده می‌شوند و حرفه‌ای‌ها شکاک. چهارم «اجرا و مشاهده»: برنامه را بالا بیاور، با چشم خودت کلیک کن، خطاها را جمع کن. پنجم «بازخورد»: به‌جای بازنویسی کل درخواست، دقیق بگو چه چیزی درست نیست — «دکمه ذخیره بعد از کلیک غیرفعال نمی‌شود» — و حلقه تکرار می‌شود. هر دور، محصول نزدیک‌تر می‌شود؛ هنر این است که هر دور را کوچک نگه داری تا وقتی Agent کج می‌رود، گم نشوی."},{"k":"def","term":"Context Window","t":"حداکثر متنی که مدل در یک گفتگو می‌تواند «به خاطر بیاورد» — شامل کدهایت، پرامپت‌ها و پاسخ‌های قبلی. وقتی پر شود، مدل چیزهای اول را فراموش می‌کند (Context Rot) و ناگهان قراردادهایی که صفحه ۱ گذاشتی را نقض می‌کند. وایب‌کدرِ حرفه‌ای این را می‌داند و گفتگوهای بلند را می‌شکند؛ تازه‌کار فقط می‌گوید «چرا خراب شد؟!»."},{"k":"h","t":"کجا وایب، کجا مهندسی؟"},{"k":"table","head":["سناریو","حکم","چرا"],"rows":[["پروتوتایپ و اعتبارسنجی ایده","وایب کامل","هدف یادگیری است؛ دور انداختنش ارزان است"],["اسکریپت و ابزار شخصی","وایب با بازبینی سریع","اگر خراب شود فقط خودت می‌فهمی"],["یادگیری مفاهیم جدید","وایب + خواندن کد","بهترین معلم خصوصی تاریخ — به‌شرط اینکه خروجی را بخوانی"],["MVP محصول واقعی","وایبِ هدایت‌شده","سرعت عالی است ولی تست و Git از روز اول لازم‌اند"],["سیستم مالی/پزشکی/امنیتی","مهندسی با کمک AI","هزینه باگ از سرعت ساخت بیشتر است — انسان مسئول می‌ماند"]]},{"k":"warn","title":"تله «چون کار می‌کند، درست است»","t":"خطرناک‌ترین لحظه وایب کدینگ وقتی است که دمو بالا می‌آید و همه‌چیز به‌نظر می‌رسد. کدی که بدون فهم ساخته شده، بدون فهم هم دیباگ می‌شود — یعنی نمی‌شود. قانون نجات: قبل از Merge هر تکه، حداقل مسیر اصلی‌اش را خودت بخوان و دو سوال بپرس: «اگر ورودی بد بگیرد چه؟» و «اگر سرور/شبکه قطع شود چه؟» همین دو سوال، ۸۰٪ فاجعه‌های آینده را قبل از تولد می‌گیرند."},{"k":"tip","title":"نکته منتور","t":"پروژه اولت را کوچک نگه دار — یک ابزار واقعاً کوچک که خودت استفاده می‌کنی (مثلاً تبدیل‌گر واحد با نرخ زنده، یا یک بازی مار). هدف محصول نیست؛ هدف ساختن «حس» است: کی Agent را باور کنی، کی متوقفش کنی، و کی فرمان را بگیری. این حس را فقط تکرار می‌سازد — پس این هفته ده حلقه کوچک بزن، نه یک حلقه بزرگ."}]'::jsonb, '[{"q":"طبق تعریف اصلی کارپاتی، وایب کدینگ برای چه پروژه‌هایی توصیف شد؟","opts":["سیستم‌های بانکی","پروژه‌های یک‌آخرهفته‌ای و اکتشافی — جایی که هزینه باگ پایین و سرعت مهم است","هر پروژه‌ای","فقط پروژه‌های OpenAI"],"ans":1,"why":"خودِ کارپاتی تاکید کرد که برای چیزهای جدی، کد را می‌خواند و فرمان را پس می‌گیرد — مرز بین «وایب» و «مهندسی» کل فلسفه این سبک است."},{"q":"کدام مرحله از حلقه وایب، بیشترین تاثیر را روی کیفیت نهایی دارد؟","opts":["تولید کد","نوشتن مشخصات (Spec) قبل از شروع — چون جهت کل حلقه‌ها را تعیین می‌کند","اجرا","انتخاب مدل"],"ans":1,"why":"هر حلقه بعدی، اصلاحِ چیزی است که حلقه اول ساخت. اگر spec مبهم باشد، Agent یک چیز «قابل دفاع» می‌سازد ولی نه آن چیزی که می‌خواستی — و هر دور اصلاح، گران‌تر می‌شود."},{"q":"Context Rot یعنی چه و چه واکنشی لازم دارد؟","opts":["خرابی دیسک","فراموشی تدریجی مدل وقتی پنجره Context پر می‌شود — درمان: شکستن گفتگو به جلسه‌های تازه با خلاصه وضعیت","باگ فریم‌ورک","کندی اینترنت"],"ans":1,"why":"وقتی گفتگو طولانی می‌شود، مدل توافق‌های اول را فراموش و سبک را عوض می‌کند؛ حرفه‌ای‌ها در نقاط طبیعی «چک‌پوینت + گفتگوی تازه» می‌زنند."}]'::jsonb),
('v-l2', 'vibe', 'مهندسی پرامپت برای کد — هنر خواستنِ دقیق', 70, 2, '[{"k":"p","t":"پرامپت، کدِ دنیای وایب است — و مثل هر کدی، نسخه بدش «کار می‌کند» ولی با هزینه پنهان. تفاوت دو پرامپت می‌تواند تفاوت بین یک بعدازظهر و یک هفته باشد. پرامپت ضعیف می‌گوید: «یک سایت فروشگاه بساز.» نتیجه: Agent صدها تصمیم را خودش می‌گیرد — فریم‌ورک، ساختار، رنگ، شکل داده — و هیچ‌کدام لزوماً آن چیزی نیست که می‌خواستی، ولی همه «منطقی»‌اند. پرامپت قوی تصمیم‌ها را از قبل می‌گیرد: هدف، کاربر، تکنولوژی، قراردادها، و مرزها. قاعده طلایی: هر تصمیمی که تو نگیری، Agent می‌گیرد — و Agent سلیقه تو را ندارد."},{"k":"p","t":"ساختار یک پرامپت مهندسی‌شده شش بخش دارد که مخففش را می‌توانی «مشخصاتِ فنیِ کار» بخوانی: ۱) نقش: «تو یک توسعه‌دهنده ارشد React هستی» — لحن و سطح خروجی را تنظیم می‌کند. ۲) زمینه: وضعیت فعلی پروژه، فایل‌های مهم، قراردادها. ۳) وظیفه: دقیقاً چه چیزی باید ساخته یا تغییر کند — یک وظیفه، نه پنج تا. ۴) قیدها: چه چیزهایی ممنوع است (کتابخانه جدید ممنوع، دیتابیس دست نخورد، سبک فعلی حفظ شود). ۵) نمونه: یک مثال ورودی-خروجی یا یک فایل مشابه که سبکش را دوست داری — مثال، قوی‌ترین سیگنال برای مدل است. ۶) قرارداد خروجی: کد کامل یا فقط diff؟ فایل به فایل؟ با تست؟ وقتی خروجی ساختار داشته باشد، بازبینی‌اش ممکن می‌شود."},{"k":"code","lang":"txt","title":"template.md — قالب پرامپت مهندسی","code":"## نقش\nتو توسعه‌دهنده ارشد TypeScript هستی که کد تمیز و\nتست‌پذیر می‌نویسی.\n\n## زمینه\nپروژه: اپ یادداشت با React + Vite + Tailwind.\nوضعیت: لیست یادداشت‌ها کار می‌کند؛ ذخیره فقط در state\nاست و با رفرش می‌پرد.\n\n## وظیفه\nذخیره‌سازی در localStorage را پیاده کن:\n۱. Hook به نام useLocalNotes بساز (فایل hooks/)\n۲. بارگذاری هنگام mount، ذخیره در هر تغییر (با debounce)\n۳. اگر localStorage خراب بود، با state خالی ادامه بده\n\n## قیدها\n- کتابخانه جدید نصب نشود\n- کامپوننت‌های موجود تغییر نکنند — فقط Hook جدید + اتصال\n- سبک موجود: توابع arrow، بدون class\n\n## نمونه\nشیوه مدیریت state در src/hooks/useSearch.ts را ببین\nو همان الگو را دنبال کن.\n\n## خروجی\nفایل‌های جدید/تغییریافته را کامل بده + یک تست ساده\nبرای مسیر بارگذاری/ذخیره."},{"k":"p","t":"بعد از پرامپت اول، هنر واقعی شروع می‌شود: تکرار هدایت‌شده. سه الگوی تکرار را بشناس چون هر روز استفاده می‌شوند. «زوم»: «حالا فقط تابع validateEmail را با Regex قوی‌تر بازنویسی کن و حالات لبه ایرانی/بین‌المللی را پوشش بده.» «واگردانی»: «تغییر قبلی را برگردان؛ باعث شد فرم دوبار submit شود — احتمالاً چون handler روی فرم و دکمه هر دو بود.» «تجزیه»: وقتی خروجی بزرگ و پرخطاست، نگو «درستش کن»؛ بگو «فقط ارور اول را ریشه‌یابی کن و بگو چرا؛ بعد راه‌حل پیشنهاد بده، بعد اعمال کن.» و همیشه — همیشه — بعد از هر تغییر بزرگ، یک Commit بزن قبل از ادامه؛ Git تو در وایب کدینگ، دکمه Undo نامحدود توست."},{"k":"table","head":["ضدالگو","چرا شکست می‌خورد","الگوی درست"],"rows":[["«این را درست کن» بدون متن خطا","مدل حدس می‌زند؛ حدس‌ها هم معمولاً نزدیک‌اند ولی اشتباه","متن کامل خطا + فایل مرتبط + آنچه امتحان کرده‌ای"],["پنج کار در یک پرامپت","خروجی مخلوط می‌شود و بازبینی‌اش ناممکن","یک کار در هر دور؛ زنجیره دورهای کوچک"],["قبول بدون اجرا","کد «منطقی» که اجرا نشده، باگ‌هایش پنهان‌اند","هر دور: اجرا کن، یک مسیر را کلیک کن، بعد ادامه"],["Context آلوده","گفتگوی ۲۰۰ پیامی که مدل اولش را فراموش کرده","چک‌پوینت: خلاصه وضعیت + گفتگوی تازه"]]},{"k":"code","lang":"txt","title":"zoom-pattern.md — الگوی زوم در عمل","code":"درست کار می‌کند ولی دو مشکل دارد. فقط همین دو تا،\nبه همین ترتیب:\n\n۱. مشکل: با کلیک سریع، دو سفارش ثبت می‌شود.\n   ریشه‌یابی کن (به نظرم race condition در handler است)\n   و فقط همان را رفع کن.\n\n۲. بعدش: مبلغ کل، تخفیف را دوبار اعمال می‌کند وقتی\n   کاربر کد را عوض می‌کند. تابع recalcTotal را ببین.\n\nبرای هر کدام: اول توضیح ریشه در دو خط، بعد diff،\nبعد یک تست که همان سناریو را پوشش بدهد."},{"k":"def","term":"Few-shot Prompting","t":"دادن چند مثالِ «ورودی → خروجی» قبل از درخواست اصلی. برای کد یعنی: یک نمونه از سبکی که می‌خواهی (نام‌گذاری، مدیریت خطا، ساختار) را بده و بگو «همین الگو». مدل‌ها تقلیدِ مثال را بهتر از دنبال‌کردن توصیف انجام می‌دهند — پس به‌جای سه خط توضیح سبک، سه خط مثال بده."},{"k":"tip","title":"نکته منتور","t":"یک فایل PROMPTS.md در پروژه‌ات بساز و پرامپت‌هایی که خوب جواب دادند را ذخیره کن — مثل کتابخانه توابع. بعد از چند ماه، پرامپت‌های پروژه‌ات خودشان یک دارایی می‌شوند: «پرامپت افزودن صفحه جدید»، «پرامپت رفع باگ»، «پرامپت نوشتن تست». این یعنی وایب کدینگ از شانس به سیستم تبدیل شده."}]'::jsonb, '[{"q":"چرا «هر تصمیمی که تو نگیری، Agent می‌گیرد» یک اصل مهم است؟","opts":["چون Agent خلاق‌تر است","چون خروجی پر از تصمیم‌های نانوشته می‌شود که بعداً باید یکی‌یکی کشف و اصلاح کنی — گرفتن تصمیم‌ها از اول ارزان‌تر است","چون Agent نمی‌تواند تصمیم بگیرد","فقط برای پروژه‌های بزرگ"],"ans":1,"why":"هر انتخاب خودسر Agent (کتابخانه، ساختار، فرمت داده) یک بدهی کوچک است؛ ده انتخاب خودسر یعنی بازبینی‌ای که از صفرنوشتن سخت‌تر است."},{"q":"الگوی «تجزیه» هنگام خروجی پرخطا چیست؟","opts":["گفتگوی جدید با همان پرامپت","اول ریشه‌یابی بدون تغییر، بعد پیشنهاد راه‌حل، بعد اعمال — قدم‌به‌قدم و قابل‌بررسی","بازنویسی کامل پروژه","تغییر مدل"],"ans":1,"why":"وقتی نمی‌دانی چه چیزی اشتباه است، تغییر دادن یعنی ریختن حدس‌های جدید روی حدس‌های قبلی. جداسازی «فهمیدن» از «تغییردادن»، حلقه را قابل‌کنترل نگه می‌دارد."},{"q":"Few-shot در پرامپت کد یعنی چه؟","opts":["چند بار تکرار درخواست","دادن یک‌دو مثال واقعی از سبک/الگوی موردنظر قبل از درخواست اصلی","استفاده از چند مدل","پرامپت کوتاه‌تر"],"ans":1,"why":"مدل‌ها الگوهای داخل Context را تقلید می‌کنند؛ یک مثال دقیق از مدیریت خطا، قوی‌تر از یک پاراگراف توصیف آن است."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('v-l3', 'vibe', 'جعبه‌ابزار وایب‌کدر — Cursor، Copilot، Claude و بقیه', 60, 3, '[{"k":"p","t":"ابزارهای وایب کدینگ سه دسته‌اند و دانستن جای هرکدام، نیمی از مسیر است. دسته اول «تکمیل‌کننده‌ها» مثل GitHub Copilot: داخل ویرایشگر، خط و تابع بعدی را حدس می‌زنند — عالی برای کارهای روتین، بی‌صدا، و همیشه روشن. دسته دوم «ویرایشگرهای AI-first» مثل Cursor و Windsurf: همان VS Code که مغز اضافه کرده — چت با کل ریپازیتوری به‌عنوان Context، ویرایش چندفایلی همزمان، و Agent که خودش فایل می‌سازد و فرمان اجرا می‌کند. دسته سوم «سازنده‌های محصول» مثل v0 و Bolt و Lovable: توصیف بده و یک اپ کامل با UI تحویل بگیر — برای پروتوتایپ و دمو بی‌رقیب‌اند. و بالای همه، مدل‌های چتی مثل Claude و ChatGPT که برای معماری، دیباگ عمیق و توضیح کد، هنوز قوی‌ترین‌اند."},{"k":"table","head":["ابزار","نقطه قوت","نقطه ضعف","کی استفاده کنیم"],"rows":[["Cursor","چت با کل کدبیس + Agent ویرایشگر","اشتراک پولی؛ وابستگی به اینترنت","پروژه‌های جدی روزمره — انتخاب اصلی اکثر وایب‌کدرها"],["GitHub Copilot","تکمیل بی‌صدا و ارزان، داخل همه ویرایشگرها","چت ضعیف‌تر؛ Context کمتر","همیشه روشن — مثل غلط‌گیر خودکار"],["Claude / ChatGPT","استدلال عمیق، معماری، دیباگ سخت","جدا از ویرایشگر؛ کپی‌پیست لازم","طراحی، بازبینی، سوال‌های مفهومی"],["v0 / Bolt","از توصیف تا UI کارکردی در دقیقه","کدش برای محصول بلندمدت مناسب نیست","پروتوتایپ، دمو، اعتبارسنجی ایده"],["Aider / Codex CLI","Agent داخل ترمینال، Git-aware","رابط کاربری فنی","عاشقان ترمینال و اتوماسیون"]]},{"k":"p","t":"اما مهم‌تر از انتخاب ابزار، «جریان کاری» است — چون حرفه‌ای‌ها با ابزار ساده هم نتیجه می‌گیرند و تازه‌کارها با بهترین ابزار هم گم می‌شوند. جریان پیشنهادی برای شروع هر پروژه: اول، ایده را با یک مدل چتی قوی به spec تبدیل کن — گفتگو کن، سوال بپرس، بگذار چالش‌هایت را پیدا کند. دوم، پروژه را در Cursor بساز: Agent را با spec شروع کن، بعد حلقه‌های کوچک اجرا/بازخورد. سوم، هر نقطه عطف که برنامه «کار می‌کند»، Commit بزن با پیام گویا — این‌ها چک‌پوینت‌های نجات‌ات هستند. چهارم، برای تصمیم‌های معماری و باگ‌های عمیق، به مدل چتی برگرد و کد را paste کن و بپرس «چرا». ابزار را بر اساس مرحله انتخاب کن، نه بر اساس تعصب."},{"k":"code","lang":"txt","title":"vibe-setup.md — تنظیمات یک پروژه وایب","code":"# فایل‌هایی که از روز اول بساز:\n\n## .cursorrules یا CLAUDE.md — «قانون اساسی» پروژه\n- زبان: TypeScript strict، بدون any\n- فریم‌ورک: React 19 + Vite + Tailwind v4\n- همه کامپوننت‌ها در components/ و نام‌گذاری PascalCase\n- مدیریت خطا: try/catch + نمایش toast، هرگز console.log خالی\n- تست: Vitest برای توابع خالص\n- فارسی‌سازی: همه متن‌های UI فارسی، dir=rtl\nاین فایل را Agent هر گفتگو می‌خواند — یعنی سبک،\nخودکار و پایدار می‌ماند حتی بعد از Context Rot.\n\n## spec.md — مشخصات محصول (خروجی گفتگوی اول)\n## TODO.md — کارهای پیش‌رو به ترتیب اولویت\n## git — اولین Commit قبل از هر کد Agent:\n     \"chore: scaffold + rules + spec\""},{"k":"p","t":"یک مهارت پنهان که ابزارهای AI-first را چند برابر می‌کند: «Context Engineering» — مهندسیِ اینکه چه چیزی وارد پنجره Context شود. @file برای ارجاع دقیق فایل‌ها، @docs برای وصل‌کردن مستندات کتابخانه‌ها (تا مدل نسخه پارسال را حدس نزند)، و فایل rules برای قراردادهای ماندگار. و برعکسش هم مهم است: نگذار Agent کل ریپازیتوری بزرگ را هر بار ببلعد — node_modules و فایل‌های تولیدی را exclude کن و فقط بخش مرتبط هر کار را به Context بیاور. Context تمیز یعنی پاسخ‌های دقیق‌تر، سریع‌تر و ارزان‌تر."},{"k":"warn","title":"توهم نسخه‌ها","t":"مدل‌ها دانش‌شان در یک تاریخ قطع شده — و درباره کتابخانه‌ها با اطمینانِ کامل، API نسخه‌های قدیمی را می‌نویسند. اگر دیدی کدی کار نمی‌کند ولی «درست به‌نظر می‌رسد»، اولین شک به نسخه‌ها باشد. درمان: مستندات رسمی را به Context بده (@docs یا کپی صفحه API)، و در rules بنویس «نسخه‌ها: react 19, tailwind 4» — دو دقیقه کار که ساعت‌ها دیباگِ «چرا import ارور می‌دهد» را حذف می‌کند."},{"k":"tip","title":"نکته منتور","t":"این هفته فقط با یک ابزار عمیق شو — پیشنهاد: Cursor — و سه چیز را یاد بگیر: چت با @file، حالت Agent برای ساخت از صفر، و Diff review قبل از قبول هر تغییر. تسلط بر یک ابزار، از آشنایی سطحی با پنج‌تا ارزشمندتر است؛ چون جریان‌های کاری (نه دکمه‌ها) مهارت واقعی‌اند."}]'::jsonb, '[{"q":"v0 و Bolt برای کدام مرحله از پروژه بهترین انتخاب‌اند؟","opts":["نگهداری محصول پنج‌ساله","پروتوتایپ و اعتبارسنجی سریع ایده — جایی که دمو مهم‌تر از معماری است","سیستم‌های بانکی","فقط طراحی لوگو"],"ans":1,"why":"این ابزارها از توصیف تا UI کارکردی در چند دقیقه می‌روند — برای «آیا این ایده ارزش ساختن دارد؟» بی‌رقیب‌اند؛ ولی کدشان برای تکامل بلندمدت طراحی نشده."},{"q":"Context Engineering یعنی چه؟","opts":["خرید Context بیشتر","انتخاب آگاهانه اینکه چه فایل‌ها و اسنادی وارد پنجره Context شوند — و چه چیزهایی بیرون بمانند","حذف فایل‌ها","تغییر مدل"],"ans":1,"why":"پنجره Context منبع کمیاب است؛ پر کردنش با چیزهای بی‌ربط، پاسخ‌ها را گمراه و گران می‌کند. آوردن دقیقِ فایل‌های مرتبط + rules + docs، مهارت هسته‌ای ابزارهای AI-first است."},{"q":"چرا فایل rules (مثل CLAUDE.md) اهمیت حیاتی دارد؟","opts":["برای زیبایی ریپازیتوری","چون قراردادهای سبک و نسخه‌ها را در هر گفتگوی تازه زنده نگه می‌دارد — حتی بعد از شروع گفتگوی جدید","Agent آن را نمی‌خواند","فقط در پروژه‌های تیمی"],"ans":1,"why":"گفتگوها تمام می‌شوند ولی rules می‌ماند؛ این فایل یعنی سبک پروژه وابسته به حافظه تو یا یک گفتگوی خاص نیست — قابل‌اتکاست."}]'::jsonb),
('v-l4', 'vibe', 'ساخت یک MVP در یک روز — کارگاه عملی', 80, 4, '[{"k":"p","t":"این درس، جلسه عملی دوره است: یک MVP واقعی را از صفر تا «قابل نشان‌دادن» می‌سازیم — «کتابچه»: یک اپ شخصی برای ذخیره لینک‌ها با تگ، جست‌وجوی فوری و حالت مطالعه. هدف محصول نیست؛ هدف تمرینِ ریتم است. ریتم حرفه‌ای‌ها این است: ۲۰٪ زمان روی مشخصات و نقشه، ۶۰٪ روی حلقه‌های کوچکِ ساخت/اجرا/بازخورد، و ۲۰٪ روی سخت‌کردن و تمیزکردن. تازه‌کارها این نسبت را برعکس دارند — ۵ دقیقه فکر، بقیه‌اش تلاش برای کنترل کدی که خودشان نفهمیده‌اند."},{"k":"code","lang":"txt","title":"مرحله ۱ — spec.md (قبل از هر کد)","code":"# کتابچه — MVP v0.1\n\n## چیست\nاپ وب شخصی برای ذخیره لینک‌ها با تگ و جست‌وجو.\nکاربر: فقط خودم. ورود/ثبت‌نام: ندارد (داده محلی).\n\n## صفحات (دقیقاً دو تا، نه بیشتر)\n۱. خانه: لیست لینک‌ها + جست‌وجو + فیلتر تگ + دکمه افزودن\n۲. افزودن: فرم (عنوان، آدرس، تگ‌ها با کاما جدا شوند)\n\n## رفتارها\n- ذخیره در localStorage (بدون بک‌اند)\n- جست‌وجو روی عنوان و تگ‌ها، همزمان با تایپ\n- حذف با تایید (دکمه سطل + «مطمئنی؟»)\n- راست‌چین، فارسی، تم تیره\n\n## صریحاً نمی‌خواهم (مهم!)\n- بک‌اند و دیتابیس\n- ورود کاربر و همگام‌سازی\n- ویرایش لینک (فقط حذف و افزودن)  ← برای v0.2\n\n## معیار «تمام»\nمی‌توانم ۵ لینک اضافه کنم، با تگ فیلتر کنم، یکی را\nحذف کنم و بعد از رفرش همه‌چیز سر جایش باشد."},{"k":"code","lang":"txt","title":"مرحله ۲ — پرامپت شروع به Agent","code":"## زمینه\nیک پروژه React+Vite+Tailwind تازه و خالی است.\nrules پروژه را بخوان (زبان، سبک، RTL).\n\n## وظیفه\nMVP «کتابچه» را طبق spec.md بساز. ترتیب:\n۱. ساختار داده Link و Hook به نام useLinks\n   (localStorage + CRUD) — ابتدا همین، با یک صفحه تست ساده\n۲. بعد صفحه افزودن\n۳. بعد لیست + جست‌وجو + فیلتر تگ\n۴. آخر: تم تیره و پرداخت ظاهری\n\n## قراردادها\n- بعد از هر مرحله توقف کن تا اجرا کنم — همه‌چیز یکجا نه\n- هر مرحله که کار کرد، بگو چه Commit message‌ای بزنم\n- اگر جایی در spec ابهام دیدی، حدس نزن — سوال کن\n\n## الان فقط قدم ۱ را انجام بده."},{"k":"p","t":"چرا «توقف بین مرحله‌ها» در پرامپت آمده؟ چون بزرگ‌ترین قاتل MVPهای وایبی، خروجیِ ۸۰۰ خطیِ یکجاست که اگر یک جایش کج باشد، نمی‌دانی از کجا شروع کنی. حلقه‌های کوچک یعنی هر لحظه حداکثر یک چیز خراب است و می‌دانی کدام است. قدم یک (Hook) را اجرا و تست کن: در console لینک اضافه کن، رفرش کن، ببین ماند. بعد قدم دو — و اگر صفحه افزودن دو بار ذخیره کرد (باگی که واقعاً در همین سناریو رایج است)، دقیق بگو: «ذخیره با هر کلیک دوبار صدا می‌شود؛ احتمالاً handler روی فرم است و دکمه هم submit می‌کند — بررسی و رفع کن، فقط همین.» ببین؟ نه «درستش کن»، نه بازنویسی — یک تشخیص جهت‌دار. این سطح از بازخورد، همان چیزی است که Agent را از ۶۰٪ دقت به ۹۵٪ می‌برد."},{"k":"code","lang":"js","title":"مرحله ۳ — کدی که Agent می‌سازد (و تو بازبینی می‌کنی)","code":"// hooks/useLinks.js — قلب MVP؛ این ۲۰ خط را حتماً بخوان\nexport function useLinks() {\n  const [links, setLinks] = useState(() => {\n    try {\n      return JSON.parse(localStorage.getItem(''links'')) ?? [];\n    } catch {\n      return [];              // داده خراب؟ شروع تمیز، نه کرش\n    }\n  });\n\n  useEffect(() => {\n    localStorage.setItem(''links'', JSON.stringify(links));\n  }, [links]);               // هر تغییر → ذخیره خودکار\n\n  const add = (link) =>\n    setLinks((prev) => [{ ...link, id: crypto.randomUUID(),\n                          createdAt: Date.now() }, ...prev]);\n  const remove = (id) =>\n    setLinks((prev) => prev.filter((l) => l.id !== id));\n\n  return { links, add, remove };\n}\n// سوالات بازبینی شما: JSON.parse خراب چطور؟ ✓ پوشش دارد\n// رفرش وسط نوشتن؟ ✓ useEffect ذخیره می‌کند\n// id یکتا؟ ✓ UUID — خوب است، نه Math.random"},{"k":"list","items":["چک‌پوینت‌های Commit (واقعی، بعد از هر مرحله): «feat: useLinks hook با ذخیره localStorage» → «feat: فرم افزودن لینک» → «feat: جست‌وجو و فیلتر تگ» → «fix: ذخیره دوبار هنگام submit»","وقتی Agent گیر کرد (دور سوم با همان خطا): مکث کن، گفتگوی تازه باز کن، متن خطا + فایل + آنچه امتحان شده را بده — گفتگوی کهنه با Context آلوده، چاله را عمیق‌تر می‌کند","وقتی چیزی خراب شد که «قبلاً کار می‌کرد»: git diff HEAD~1 ببین آخرین تغییر چه کرده — ۹ از ۱۰ بار جواب همان‌جاست و ۳۰ ثانیه‌ای حل می‌شود","آخر روز: git log --oneline — این تاریخچه، داستان یک روز مهندسی است؛ هر خطش یک تصمیم. همین را در رزومه‌ات روایت کن"]},{"k":"warn","title":"دام «یک قدم دیگر»","t":"ساعت ۶ عصر، MVP کار می‌کند و وسوسه می‌گوید «حالا حالت مطالعه را هم اضافه کن». نکن. معیار «تمام» را در spec نوشتی که همین لحظه نجاتت بدهد: ۵ لینک، فیلتر، حذف، ماندگاری — تیک خورد؟ پس Commit بزن، دمو را ضبط کن، و برو. بزرگ‌ترین دستاورد روز اول، «تمام‌کردن» است نه «همه‌چیز داشتن». حالت مطالعه، صبح فردا با ذهن تازه و یک spec بازبینی‌شده — آن‌وقت نه وسوسه است، بلکه برنامه."},{"k":"tip","title":"نکته منتور","t":"این کارگاه را واقعاً انجام بده — نه اینکه بخوانی. چهار ساعت، موبایل سایلنت، و آخرش دمو را برای یک نفر بفرست. اولین «وای، تو این را ساختی؟» را که بشنوی، چیزی در ذهنت جابه‌جا می‌شود که هیچ دوره‌ای بدون ساختن نمی‌تواند جابه‌جا کند. و اگر جایی گیر کردی، دقیقاً همان لحظه، درس ۵ را باز کن."}]'::jsonb, '[{"q":"چرا پرامپت شروع، از Agent خواست بعد از هر مرحله توقف کند؟","opts":["برای صرفه‌جویی در توکن","چون خروجی یکجای بزرگ وقتی خراب شود غیرقابل‌دیباگ است — حلقه کوچک یعنی همیشه حداکثر یک چیز خراب است و می‌دانی کدام","Agent نمی‌تواند همه را یکجا بسازد","برای Commit بیشتر"],"ans":1,"why":"هر چه خروجی یک دور بزرگ‌تر باشد، فاصله بین «کار می‌کرد» و «خراب شد» بیشتر و ریشه‌یابی سخت‌تر است. حلقه کوچک، هزینه خطا را در هر لحظه پایین نگه می‌دارد."},{"q":"بهترین واکنش وقتی Agent سه دور پشت‌سرهم با همان خطا می‌چرخد چیست؟","opts":["تکرار پرامپت با تأکید بیشتر","مکث: گفتگوی تازه با متن خطا، فایل مرتبط و کارهایی که امتحان شده — Context آلوده معمولاً خودش بخشی از مشکل است","تغییر کل پروژه","ادامه تا دور دهم"],"ans":1,"why":"گفتگوی طولانی، فرض‌های غلط اولیه را با خودش می‌کشد. گفتگوی تازه با اطلاعات دقیق، اغلب در یک دور چیزی را حل می‌کند که ده دور قبلی نتوانست."},{"q":"نقش git در وایب کدینگ چیست؟","opts":["فقط برای تیم‌ها","دکمه Undo نامحدود: چک‌پوینت‌های سالم قبل از هر ریسک، و تاریخچه‌ای که می‌گوید کدام تغییر چه چیزی را شکست","ضروری نیست چون Agent کد را نگه می‌دارد","فقط برای پروژه‌های بزرگ"],"ans":1,"why":"وقتی سازنده کد یک مدل غیرقطعی است، «دانستن نقطه سالم قبلی» حیاتی‌تر از هر پروژه کلاسیک است. git diff و log ابزارهای ریشه‌یابی اصلی وایب‌کدرند."}]'::jsonb),
('v-l5', 'vibe', 'کیفیت در دنیای وایب — توهم، تست و ریویو', 70, 5, '[{"k":"p","t":"حالا که می‌توانی سریع بسازی، سوال جدی شروع می‌شود: آیا چیزی که ساختی «درست» است؟ مدل‌ها کدی می‌نویسند که با اعتمادبه‌نفس کامل، گاهی اشتباه است — و اشتباه‌هایشان از جنس اشتباه‌های آدم‌ها نیست. انسان وقتی خسته است غلط می‌کند؛ مدل وقتی «ناآشناست» با اعتمادبه‌نفسِ همانِ وقتی که آشناست پاسخ می‌دهد. معروف‌ترین شکلش توهم API است: فراخوانی کتابخانه‌ای، تابعی یا پارامتری که اصلاً وجود ندارد — چون از نظر آماری «شبیه» چیزی است که وجود دارد. پس اولین اصل کیفیت در وایب: هیچ import و API را بدون چک‌کردن در مستندات نپذیر؛ اجرای موفقِ یک مسیر هم دلیل بر نبودن باگ در مسیرهای دیگر نیست."},{"k":"p","t":"دفاع عمیق در وایب کدینگ سه لایه دارد. لایه اول: تست‌هایی که Agent برای کدِ خودش می‌نویسد — ولی با یک قاعده حیاتی: اول بگو «برای این تابع، تست بنویس که این سناریوها را پوشش بدهد» و سناریوها را خودت بده (مرزها، خالی، خطا)؛ اگر بگذاری خودش هم سناریو را انتخاب کند هم تست را بنویسد، می‌تواند ناخودآگاه همان برداشتش از کد را تست کند و هر دو با هم اشتباه باشند. لایه دوم: ریویوی diff — قبل از قبول هر تغییر چندفایلی، خط‌به‌خط ببین چه چیزی واقعاً عوض شد؛ Agent گاهی «برای حل مشکل» چیزی را حذف می‌کند که تو خبر نداری. لایه سوم: اجرا و مشاهده دستی — حداقل یک بار، مسیر اصلی را مثل کاربر واقعی برو، با ورودی‌های بد: فیلد خالی، متن طولانی، کلیک‌های پشت‌سرهم."},{"k":"code","lang":"txt","title":"review-checklist.md — چک‌لیست ریویوی خروجی Agent","code":"قبل از قبول هر تغییر بزرگ، این شش سوال:\n\n۱. قراردادها: آیا چیزی که خواستم دقیقاً انجام شد —\n   نه بیشتر (فیچرهای ناخوانده) و نه کمتر؟\n۲. حذف‌ها: git diff را ببین — چیزی پاک/ساده شده که\n   لازم بود؟ (Agent عاشق «تمیزکردن» اضافی است)\n۳. وابستگی‌ها: پکیج جدیدی نصب شده؟ مجوزش چیست؟\n   واقعاً لازم بود یا می‌شد با کتابخانه استاندارد؟\n۴. مرزها: ورودی بد/خالی/طولانی چه می‌کند؟\n   مسیر خطا هم مثل مسیر شاد هندل شده؟\n۵. رازها: کلید/توکن/رمزی در کد Commit نمی‌شود؟\n   (grep بزن: password|secret|api_key|token)\n۶. ساده‌ترین راه بود؟ راه‌حل‌های Agent گاهی برای\n   مسئله‌ای است که در کدبیس‌های بزرگ‌تر دیده —\n   نه برای مسئله تو."},{"k":"code","lang":"py","title":"test-first-with-agent.py","code":"# ❌ «برای تابع زیر تست بنویس»\n# → تستِ برداشتِ خودش از تابع؛ اگر هر دو کج باشند، سبزِ دروغین\n\n# ✓ سناریو را تو بده، پیاده‌سازی را او:\n\"\"\"\nبرای تابع normalize_phone این تست‌ها را بنویس:\n- ''۰۹۱۲۳۴۵۶۷۸۹'' → ''09123456789'' (ارقام فارسی → انگلیسی)\n- ''+98 912 345 6789'' → ''09123456789''\n- ''0098-912-345-6789'' → ''09123456789''\n- ورودی کوتاه/بلند → None (نه استثنا)\n- رشته خالی و None → None\nسپس تابع را طوری اصلاح کن که همه پاس شوند.\n\"\"\"\n\n# نکته: ارقام فارسی را تو آورده‌ای — چون می‌دانی کاربر\n# ایرانی تایپ می‌کند «۰۹۱۲»؛ مدل شاید هرگز به ذهنش نرسد.\n# این یعنی «دانش مسئله» مال توست، «دانش پیاده‌سازی» مشترک."},{"k":"p","t":"امنیت در کد AI-ساخته دو چهره دارد. چهره اول، کدِ خودِ خروجی: مدل‌ها چون از میلیون‌ها ریپازیتوری عمومی یاد گرفته‌اند، گاهی الگوهای ناامن را «استاندارد» می‌نویسند — eval روی ورودی کاربر، CORS باز برای همه، هش ضعیف رمز، کوئری ساخته‌شده با رشته. چک‌لیست امنیتی درس‌های امنیت این دوره را روی خروجی Agent هم اجرا کن؛ آن‌ها آن‌جا برای کد انسان نوشته شده‌اند ولی اینجا مهم‌ترند چون نویسنده‌ای وجود ندارد که «حواش باشد». چهره دوم، زنجیره تامین: پکیجی که Agent پیشنهاد نصبش را می‌دهد حتماً چک کن — نام‌های شبیه‌به‌اصل (typosquatting) و پکیج‌های متروکه، از درهای ورودی مهاجم‌ها به پروژه‌های AI-ساخته‌اند."},{"k":"table","head":["خطر","نشانه در خروجی Agent","اقدام"],"rows":[["API خیالی","ارور import یا undefined در اجرا","چک در مستندات رسمی + @docs"],["الگوی ناامن","eval، SQL رشته‌ای، CORS: *","اجرای چک‌لیست امنیت — بدون تعارف"],["وابستگی مخدوش","نام پکیج یک حرف با نسخه اصلی فرق دارد","چک در npm/PyPI: تعداد دانلود، نگهدارنده"],["فیچر ناخوانده","فایل‌هایی در diff که خواسته نشدند","برگردان؛ یک کار در هر دور"],["مجوز آلوده","کپی کد از منبع ناشناس","برای محصول جدی، پاک‌سازی منبع"]]},{"k":"warn","title":"تست سبز، همیشه یعنی درست","t":"خطرناک‌ترین حالت در وایب کدینگ این است: Agent هم کد را نوشت هم تست را، و هر دو سبز. اگر سناریوها را تو نداده باشی، ممکن است هر دو یک سوءتفاهم مشترک را تأیید کنند. قانون: سناریوی تست از توست (چون مسئله را تو می‌فهمی)، پیاده‌سازی و کد تست از Agent. این تقسیم کار کوچک، کل فرهنگ کیفیت وایب را می‌سازد."},{"k":"tip","title":"نکته منتور","t":"یک رسم هفتگی بساز: جمعه‌ها، یکی از Agentهای قوی را باز کن و بگو «این فایل را مثل یک کدریوی‌کننده سخت‌گیر نقد کن؛ امنیتی، کارایی، خوانایی». بعد نقدهایش را خودت داوری کن — کدام درست، کدام سخت‌گیری بی‌مورد. این تمرین، هم کدت را بهتر می‌کند هم حس داوری‌ات را؛ چون در دنیای وایب، آخرین کدریوی‌کننده همیشه تویی."}]'::jsonb, '[{"q":"چرا «سناریوی تست از تو، پیاده‌سازی از Agent» قاعده طلایی است؟","opts":["چون Agent تست نمی‌تواند بنویسد","چون اگر هر دو از یک منبع بیایند، سوءتفاهم مشترک را تأیید می‌کنند — دانش مسئله نزد توست","برای سرعت بیشتر","چون تست سخت‌تر از کد است"],"ans":1,"why":"مدل می‌داند کد چه می‌کند؛ تو می‌دانی چه «باید» بکند — از جمله سناریوهایی که خودش هرگز به ذهنش نمی‌رسد (مثل ارقام فارسی). این شکاف را فقط تو می‌توانی پر کنی."},{"q":"کدوم گزینه در ریویوی diff از همه خطرناک‌تر است؟","opts":["افزودن کامنت","حذف‌هایی که تو خبر نداری — Agent گاهی برای حل مشکل، کد لازم را «تمیز» می‌کند","تغییر نام متغیر","فرمت مجدد"],"ans":1,"why":"افزودن‌ها دیده می‌شوند؛ حذف‌ها نامرئی‌اند. وقتی فیچری «ناگهان» کار نمی‌کند، اول git diff را ببین چه چیزی پاک شده — نه چه چیزی اضافه شده."},{"q":"typosquatting چیست و چرا در پروژه‌های AI-ساخته مهم‌تر است؟","opts":["غلط املایی در کد","پکیج‌هایی با نام شبیه پکیج معروف که Agent ممکن است پیشنهادشان دهد — چون مدل نام‌ها را از حافظه می‌آورد نه از registry","نوعی تست","خطای کامپایلر"],"ans":1,"why":"مدل نام پکیج را «حدس» می‌زند؛ مهاجم‌ها هم دقیقاً همین حدس‌ها را از قبل ثبت کرده‌اند. یک چک در npm قبل از نصب، درِ این حمله را می‌بندد."}]'::jsonb),
('v-l6', 'vibe', 'عصر Agentها — آینده توسعه‌دهنده و مسیر تو', 65, 6, '[{"k":"p","t":"تا اینجا یاد گرفتی با Agentها کد بزنی؛ حالا بگذار ببینیم این قطار به کجا می‌رود — چون مسیری که امروز شروع می‌کنی، باید تا آن‌جا راه داشته باشد. موج فعلی «Agent» است: سیستمی که هدف می‌گیرد و خودش حلقه «برنامه‌ریزی → عمل → مشاهده → اصلاح» را می‌بندد — گاهی برای ساعت‌ها، با دسترسی به ترمینال، مرورگر و APIها. Devin و OpenAI Codex و Claude Code نمونه‌های اولیه‌اند: مسائلی را می‌گیرند، خودشان فایل می‌سازند، تست اجرا می‌کنند، و PR باز می‌کنند. هنوز خطا می‌کنند و نظارت لازم‌اند — مثل کارآموز باهوشی که اعتمادبه‌نفسش از تجربه‌اش جلوتر است. ولی جهتِ منحنی واضح است: بخش «تایپ کردن راه‌حل» که ۷۰٪ زمان توسعه‌دهنده میانگین را می‌گیرد، دارد به ماشین سپرده می‌شود."},{"k":"p","t":"سوالی که همه می‌پرسند: «پس من چه می‌شوم؟» پاسخ صادقانه: کاری که «فقط اجرا» باشد، کوچک می‌شود؛ ولی کاری که «قضاوت» بخواهد، بزرگ‌تر و گران‌تر می‌شود. فهرست چیزهایی که Agentها در آینده نزدیک هم نمی‌توانند: فهمیدن اینکه مسئله اصلی چیست (مشتری می‌گوید «دکمه می‌خواهم»، مشکل واقعی چیز دیگری است)، مذاکره بر سر مصالحه‌ها (سرعت در برابر امنیت در این محصولِ خاص)، پذیرفتن مسئولیت نتیجه، و سلیقه — همان حسِ «این تجربه کاربری درست نیست» که از هزار محصول دیدن می‌آید. توسعه‌دهنده آینده، کمتر «نویسنده کد» و بیشتر «مدیر فنیِ تیمی از Agentها» است: مشخصات دقیق می‌نویسد، خروجی‌ها را داوری می‌کند، معماری نگه‌دارنده را طراحی می‌کند و وقتی Agentها به بن‌بست می‌رسند، خودش وارد عمق می‌شود."},{"k":"code","lang":"txt","title":"مهارت‌های عصر Agent — ترتیب سرمایه‌گذاری","code":"لایه ۱ — هنوز پایه‌ها (بله، هنوز!)\n  خواندن کد سریع و بی‌ترس ← مهم‌ترین مهارت دهه آینده\n  دیباگ از روی خطا و لاگ ← Agentها راهنما می‌خواهند\n  Git و ترمینال ← فرمان‌رانی Agentها با همین‌هاست\n\nلایه ۲ — مهارت‌های جدید\n  نوشتن Spec و قرارداد شفاف ← «مدیریت» Agentها\n  طراحی تست و سناریو ← مرز دانش مسئله/پیاده‌سازی\n  ریویوی معماری ← فهمیدن اینکه Agent چرا کج رفت\n\nلایه ۳ — اهرم‌های چندبرابری\n  اتصال ابزارها به مدل (MCP و Tool Use) ← Agentی که\n     دیتابیس و API تو را می‌فهمد، ده برابر مفیدتر است\n  اتوماسیون جریان‌ها ← CI که خودش باگ را به Agent\n     می‌سپارد و PR را می‌گیرد\n  ساخت محصول ← چون هزینه ساخت نزدیک صفر شده،\n     برنده کسی است که «چه بسازد» را بداند، نه فقط «چطور»"},{"k":"def","term":"MCP (Model Context Protocol)","t":"پروتکلی که به مدل‌ها اجازه می‌دهد به ابزارها و داده‌های واقعی وصل شوند — دیتابیس، فایل‌ها، APIهای داخلی، ترمینال — با یک قرارداد استاندارد. یعنی به‌جای اینکه کد را کپی کنی و به چت paste کنی، Agent مستقیم می‌پرسد و عمل می‌کند. MCP برای Agentها همان کاری را می‌کند که USB برای دستگاه‌ها کرد: یک پورت استاندارد که همه‌چیز به آن وصل می‌شود — و مهارت «وصل‌کردن سیستم‌ها به مدل‌ها» دارد تبدیل به یکی از پرتقاضاترین مهارت‌های مهندسی می‌شود."},{"k":"table","head":["باور رایج","واقعیت مهندسی"],"rows":[["«AI جای برنامه‌نویس‌ها را می‌گیرد»","جای «برنامه‌نویس‌هایی که فقط اجرا می‌کنند» را تنگ می‌کند؛ تقاضا برای قضاوت فنی بالا می‌رود"],["«دیگر لازم نیست کد یاد بگیرم»","برعکس: خواندن و داوری کد مهم‌تر از همیشه است — نمی‌توانی چیزی را داوری کنی که نمی‌فهمی"],["«Agentها کامل می‌شوند و نظارت لازم نیست»","هرچه توانا‌تر، نظارت هوشمندتر لازم است — مثل هواپیمای خودران: خلبان حذف نشده، نقشش عوض شده"],["«وایب کدینگ یعنی بی‌نظمی»","وایبِ خوب، بیشترین نظم پنهان را دارد: spec، Git، تست و ریویو — فقط نویسنده‌اش عوض شده"]]},{"k":"p","t":"و مسیر عملی تو بعد از این دوره: قدم اول (همین ماه) — ده پروژه کوچک وایبی تمام کن و هرکدام را با یک یادداشت تمام کن: چه چیزی Agent خوب انجام داد، کجا گمراه شد، چه پرامپتی نجاتم داد. این یادداشت‌ها، دفترچه قضاوت توست. قدم دوم (ماه دوم) — یک پروژه را «دوطرفه» بساز: یک بار دستی با کد کلاسیک، یک بار وایب — و Diff تجربه‌ها را بنویس؛ این کار، پایه‌های مهندسی‌ات را محکم نگه می‌دارد در حالی که سوار موجی. قدم سوم — یک Agent به سیستم واقعی وصل کن: MCP ساده‌ای بنویس که مدل را به دیتابیس محلی‌ات وصل کند و ببین چه چیزی ممکن می‌شود. کسی که این سه قدم را برداشته باشد، در بازارِ بعد از Agent هم کمیاب است: چون هم می‌سازد، هم می‌فهمد، هم وصل می‌کند."},{"k":"warn","title":"تله وابستگی","t":"اگر بعد از شش ماه دیدی نمی‌توانی یک حلقه ساده را بدون Agent بنویسی، خبر خوبی نیست — چون روزی Agent اشتباه می‌کند و تنها کسی که می‌تواند نجاتش بدهد تویی. قانون تعادل: هفته‌ای چند ساعت «کد دستی» بزن — نه چون بهینه‌تر است، چون عضلات فهم باید قوی بمانند. خلبان خودرانِ خوب، خلبانی است که هنوز دستی فرود آمدن بلد است."},{"k":"tip","title":"نکته منتور","t":"به‌جای ترسیدن از موج یا سوارشدن کورکورانه، کار سوم را بکن: موج را مهندسی کن. هر ماه یک عصر را به خواندن یک گزارش فنی از آزمایشگاه‌های اصلی (OpenAI، Anthropic، مقالات MCP) اختصاص بده و از خودت بپرس: «این قابلیت جدید، کدام بخش از کارِ من را عوض می‌کند — و کدام را گران‌تر؟» این عادت، فاصله بین «کسی که تغییر رویش اتفاق می‌افتد» و «کسی که تغییر را می‌سازد» است."}]'::jsonb, '[{"q":"در عصر Agentها، کدام مهارت گران‌تر می‌شود؟","opts":["سرعت تایپ کد","قضاوت فنی: تعریف مسئله، داوری خروجی، طراحی تست و پذیرفتن مسئولیت — کارهایی که مدل نمی‌تواند","حفظ کردن Syntax","کار بدون ابزار"],"ans":1,"why":"اجرا ارزان و فراوان می‌شود؛ پس ارزش به سمت کمیاب‌ترین بخش جابه‌جا می‌شود — فهمیدن مسئله درست و تشخیصِ درست‌بودنِ جواب."},{"q":"MCP چه نقشی در آینده نزدیک دارد؟","opts":["یک فریم‌ورک فرانت‌اند","پورت استاندارد اتصال مدل‌ها به ابزارها و داده‌های واقعی — USBِ دنیای Agentها","یک دیتابیس","پروتکل شبکه"],"ans":1,"why":"Agent بدون دسترسی به دنیای واقعی فقط متن تولید می‌کند؛ MCP اتصال امن و استاندارد می‌سازد — و مهارت ساخت این اتصال‌ها دارد کمیاب و پرتقاضا می‌شود."},{"q":"چرا «کد دستیِ هفتگی» حتی برای وایب‌کدر حرفه‌ای لازم است؟","opts":["چون Agent پولی است","چون وقتی Agent اشتباه می‌کند، تنها نجات‌دهنده کسی است که هنوز عمق را می‌فهمد — عضلات فهم باید فعال بمانند","چون مصاحبه‌ها هنوز دستی‌اند","برای سرعت بیشتر"],"ans":1,"why":"وابستگی کامل یعنی تک‌نقطه شکست: روزی Agent به بن‌بست می‌رسد و فقط کسی که «دستی فرود آمدن» بلد است می‌تواند سیستم را نجات بدهد."}]'::jsonb),
('vibe-b1', 'vibe', 'وایب کدینگ چیست', 56, 7, '[{"k":"p","t":"وایب کدینگ سبکی از توسعه است که مسیر و قضاوت با توست و نوشتن کد با هوش مصنوعی؛ توصیف می‌کنی چه می‌خواهی، Agent می‌سازد، تو بازبینی و هدایت می‌کنی."},{"k":"h","t":"وایب کدینگ چیست و چه چیزی نیست"},{"k":"p","t":"وایب کدینگ یعنی توسعه نرم‌افزار با هم‌نشینی یک Agent هوشمند: تو هدف، قیدها و جهت را مشخص می‌کنی و Agent پیشنهاد کد می‌دهد، اجرا می‌کند و اصلاح می‌کند — و تو در هر گام داوری می‌کنی. این «کد ننوشتن» نیست؛ «نوشتنِ کمتر و داوریِ بیشتر» است. تفاوتش با استفاده معمولی از Copilot این است که حلقه تنگ‌تر و دوطرفه‌تر می‌شود: Agent نه‌تنها کامل می‌کند، بلکه آزمایش می‌کند، خطا می‌خواند و خودش پیشنهاد اصلاح می‌دهد."},{"k":"h","t":"کجا رها کنی، کجا فرمان بگیری"},{"k":"p","t":"وایب کدینگ در کارهای با بازخورد سریع و قابل‌سنجش می‌درخشد — ساخت UI، نوشتن تست، refactoring، اسکریپت‌های یک‌بارمصرف، دیباگ با پیام خطای روشن. ولی در جاهایی که «درست‌بودن» به‌راحتی قابل‌سنجش نیست — امنیت، همزمانی، طراحی داده بلندمدت — نباید فرمان را رها کنی؛ آنجا Agent دستیار است نه خلبان. مهارت اصلی وایب‌کدرِ خوب، تشخیص همین مرز است: چه زمانی سرعت را بسپاری به Agent و چه زمانی خودت عمیق شوی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کد کلاسیک","وایب کدینگ"],"rows":[["نویسنده اول","انسان","Agent"],["نقش انسان","نوشتن + داوری","جهت‌دهی + داوری"],["سرعت prototyping","کندتر","بسیار سریع"],["نیاز به داوری","همیشه","همیشه و حتی بیشتر"]]},{"k":"warn","title":"دام رایج","t":"بزرگ‌ترین دام وایب کدینگ، اعتماد به خروجی بدون اجرا و سنجش است. Agent با اعتمادبه‌نفس کامل کدی می‌دهد که گاهی API خیالی دارد یا منطقی ظریف را اشتباه گرفته؛ چون «به‌نظر درست» می‌آید، تازه‌کارها آن را می‌پذیرند. قانون: هیچ خروجی‌ای بدون اجرا و دیدن رفتار واقعی قبول نشود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["تو مسئله را می‌فهمی و تعریف می‌کنی، Agent پیاده می‌کند","بازبینی و تأیید هر خروجی وظیفه توست","سرعت ساخت چند برابر می‌شود، مسئولیت همان"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"تقسیم کار","code":"تو:    مسئله → Spec → بازبینی → تأیید\nAgent: کد → تست → refactor → پیشنهاد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: تو مسئله را می‌فهمی و تعریف می‌کنی، Agent پیاده می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"در وایب کدینگ چه چیزی به عهده توسعه‌دهنده می‌ماند؟","opts":["هیچ","فهم مسئله، تعریف دقیق خواسته و بازبینی/تأیید خروجی — نوشتن جزئیات به Agent سپرده می‌شود","نوشتن کد","تست فقط"],"ans":1,"why":"Agent کد می‌نویسد ولی نمی‌داند چه چیزی درست است؛ فهم مسئله و قضاوت درباره خروجی همیشه با انسان است."},{"q":"تفاوت اصلی وایب کدینگ با کپی‌کردن جواب از یک چت‌بات چیست؟","opts":["هیچ","وایب کدینگ یک حلقه تنگ و دوطرفه است: Agent پیشنهاد می‌دهد، اجرا و آزمایش می‌کند و بر اساس بازخورد واقعی اصلاح می‌کند — نه یک جواب یک‌طرفه","فقط سرعتش بیشتر است","مدل بهتری دارد"],"ans":1,"why":"قدرت وایب در حلقه «پیشنهاد → اجرا → مشاهده → اصلاح» است؛ همین بازخورد واقعی است که خطاها را زود می‌گیرد و خروجی را به واقعیت نزدیک می‌کند، نه صرفِ تولید متن."},{"q":"در کدام کار نباید فرمان را کاملاً به Agent سپرد؟","opts":["ساخت یک صفحه UI","طراحی مکانیزم امنیت و همزمانی — چون درست‌بودنش با یک نگاه یا اجرای ساده قابل‌سنجش نیست","نوشتن یک تست","refactoring یک تابع"],"ans":1,"why":"معیار سپردن فرمان، «قابل‌سنجش‌بودنِ درست‌بودن» است؛ UI و تست با اجرا قضاوت می‌شوند، ولی حفره امنیتی یا race condition می‌تواند ماه‌ها پنهان بماند — پس آنجا داوری عمیق انسانی لازم است."}]'::jsonb),
('vibe-b2', 'vibe', 'نوشتن Spec خوب', 63, 8, '[{"k":"p","t":"Spec مشخصات واضح و کامل خواسته است؛ هرچه Spec دقیق‌تر، خروجی Agent نزدیک‌تر — ابهام در Spec یعنی حدس Agent و دوباره‌کاری."},{"k":"h","t":"Spec خوب، نیمی از راه"},{"k":"p","t":"در وایب کدینگ، کیفیت خروجی به‌شدت به کیفیت ورودی وابسته است — و ورودی تو همان Spec است. یک Spec خوب به سه سؤال پاسخ می‌دهد: چه چیزی بساز (رفتار قابل‌مشاهده، نه پیاده‌سازی)، چه چیزی نساز (مرزها و ضددامنه‌ها که جلوی بزرگ‌شدن بی‌رویه را می‌گیرند)، و «تمام شد» یعنی چه (معیار پذیرش قابل‌سنجش). وقتی این سه روشن باشند، Agent راه اشتباه رفتن کمتری دارد و داوریِ تو هم ساده‌تر می‌شود چون با یک قرارداد روشن می‌سنجی."},{"k":"h","t":"رفتار بنویس، نه پیاده‌سازی"},{"k":"p","t":"Specی که می‌گوید «از useState استفاده کن و map بزن» دارد کار Agent را انجام می‌دهد — و اگر اشتباه کند، هر دو اشتباه کرده‌اید. Specی که می‌گوید «کاربر لیست را می‌بیند، با تایپ فیلتر می‌شود و حذف با تأیید انجام می‌شود» دست Agent را برای انتخاب ابزار باز می‌گذارد و تمرکز را روی نتیجه می‌گذارد. قانون: پیاده‌سازی را فقط وقتی قید کن که دلیل واقعی داشته باشی (سازگاری با کد موجود، استاندارد تیم) — وگرنه بگذار Agent انتخاب کند و تو نتیجه را بسنج."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک Spec خوب در برابر یک Spec بد","code":"# ❌ بد: مبهم + پیاده‌سازی‌محور\n«یک صفحه بساز خوب باشه، از react استفاده کن»\n\n# ✓ خوب: رفتار + مرز + معیار\nهدف: صفحه لیست دوره‌ها\nرفتارها:\n  - لیست از /api/courses خوانده و لودینگ/خطا نشان بدهد\n  - با تایپ در جستجو، روی عنوان فیلتر شود (بدون درخواست جدید)\n  - کلیک روی کارت به /courses/:id برود\nنخواهم: صفحه‌بندی، فیلتر دسته‌بندی (بعداً)\nمعیار تمام: ۵ دوره نمایش داده شود، جستجوی «وب» فقط\n  دوره‌های وب را نشان دهد، خطای قطع شبکه پیام فارسی بدهد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["بخش Spec","پاسخ می‌دهد","مثال"],"rows":[["هدف/رفتارها","چه چیزی بساز","با تایپ فیلتر شود"],["ضددامنه","چه چیزی نساز","صفحه‌بندی فعلاً نه"],["معیار پذیرش","«تمام» یعنی چه","جستجوی X نتیجه Y بدهد"]]},{"k":"tip","title":"نکته منتور","t":"Spec را با Agent هم چک کن: قبل از کدنویسی بپرس «بر اساس این Spec چه ابهامی می‌بینی؟». سؤال‌هایش دقیقاً همان جاهایی است که Spec گنگ بوده — و پر کردن همان‌ها، کیفیت خروجی را چند برابر می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["چه چیزی، برای چه کسی، با چه رفتارهایی","موارد مرزی و خطاها را صریح بنویس","صریحاً بگو چه چیزی نمی‌خواهی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"spec.md نمونه","code":"# اپ یادداشت\nکاربر: فقط خودم\nرفتار:\n- افزودن/حذف یادداشت\n- جست‌وجو همزمان با تایپ\nموارد مرزی:\n- یادداشت خالی ذخیره نشود\n- بعد از رفرش داده بماند (localStorage)\nنمی‌خواهم: ورود کاربر، بک‌اند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: چه چیزی، برای چه کسی، با چه رفتارهایی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا نوشتن «چه چیزی نمی‌خواهم» در Spec مهم است؟","opts":["زیبایی","چون Agent ممکن است امکانات اضافه ناخواسته بسازد و صریح‌کردن ممنوع‌ها، خروجی را متمرکز نگه می‌دارد","اجباری","سرعت"],"ans":1,"why":"Agentها تمایل دارند کامل‌سازی کنند و امکانات اضافه بزنند؛ گفتن صریح ممنوع‌ها، جلوی scope creep خودکار را می‌گیرد."},{"q":"چرا نوشتن «ضددامنه» (چه چیزی نساز) در Spec مهم است؟","opts":["برای کوتاه‌شدن کد","چون Agentها تمایل به کامل‌کردن و افزودن دارند؛ مرز روشن جلوی بزرگ‌شدن بی‌رویه و قابلیت‌های ناخواسته را می‌گیرد","اجباری است","سرعت را بالا می‌برد"],"ans":1,"why":"مدل‌ها روی کدهای کامل و پر از قابلیت آموزش دیده‌اند و دوست دارند «همه‌چیز» بسازند؛ ضددامنه یک قرارداد صریح است که می‌گوید ساده‌ماندنِ این نسخه، یک تصمیم است نه یک کمبود."},{"q":"کدام Spec بهتر است؟","opts":["«از map و filter استفاده کن»","«با تایپ کاربر، لیست روی عنوان فیلتر شود» — چون رفتار قابل‌مشاهده را می‌گوید و انتخاب ابزار را باز می‌گذارد","«سریع بنویس»","«مثل دیروز»"],"ans":1,"why":"رفتارِ قابل‌مشاهده هم به Agent آزادی پیاده‌سازی می‌دهد و هم به تو معیاری برای سنجش؛ قیدِ ابزارِ خاص فقط وقتی توجیه دارد که دلیل واقعی (مثل سازگاری) پشتش باشد."}]'::jsonb),
('vibe-b3', 'vibe', 'پرامپت‌های مهندسی‌شده', 63, 9, '[{"k":"p","t":"پرامپت خوب نقش، زمینه، وظیفه، قیدها و فرمت خروجی دارد؛ پرامپت‌های ساختاریافته قابل‌تکرار و قابل‌بهبودند و خطا را کم می‌کنند."},{"k":"h","t":"پرامپت مهندسی‌شده چیست"},{"k":"p","t":"پرامپت مهندسی‌شده یعنی درخواستی که ساختار دارد: نقش و زمینه (Agent بداند در چه پروژه‌ای و با چه قراردادهایی است)، یک وظیفه مشخص (نه ده کار همزمان)، قیدها (زبان، کتابخانه‌های مجاز، سبک کد) و قرارداد خروجی (فقط کد؟ توضیح هم؟ تست هم؟). تفاوتش با «یه دکمه اضافه کن» این است که فضای تصمیم‌های Agent را کوچک می‌کنی؛ هر تصمیمی که تو نگیری، Agent با سلیقه خودش می‌گیرد — و سلیقه او متوسطِ میلیون‌ها ریپازیتوری است، نه استاندارد تیم تو."},{"k":"h","t":"زمینه بده، نه فقط دستور"},{"k":"p","t":"قدرتمندترین بخش پرامپت، زمینه است: ساختار فایل‌ها، قراردادهای نام‌گذاری، الگویی که قبلاً استفاده کرده‌ای. جمله «همان الگوی useFetch در hooks/useFetch.ts را برای useCourses هم بساز» از یک پاراگراف توضیح مؤثرتر است چون Agent را به یک نمونه واقعی و درست ارجاع می‌دهد. در ابزارهایی مثل Cursor، اشاره مستقیم به فایل‌ها (@file) این کار را دقیق می‌کند — پس به‌جای توصیف کد موجود، نشانش بده."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"ساختار یک پرامپت مهندسی‌شده","code":"## زمینه\nپروژه React+TS است؛ داده‌ها با hook سفارشی\nhooks/useFetch.ts خوانده می‌شوند و استایل Tailwind.\n\n## وظیفه\nhook جدید useCourses بنویس که GET /api/courses را\nبخواند و { data, loading, error } برگرداند.\n\n## قیدها\n- دقیقاً همان الگوی useFetch (ارجاع به فایل)\n- تایپ Course در types.ts تعریف شود\n- بدون کتابخانه جدید\n\n## خروجی\nفقط کد + یک مثال مصرف کوتاه؛ توضیح اضافه نده."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["بخش پرامپت","کارش","اگر نباشد"],"rows":[["زمینه/نقش","چارچوب پروژه","کد بی‌ربط به قراردادها"],["وظیفه واحد","تمرکز","خروجی پراکنده و ناتمام"],["قیدها","کوچک‌کردن فضا","انتخاب‌های سلیقه‌ای Agent"],["قرارداد خروجی","شکل پاسخ","توضیح اضافی یا کد ناقص"]]},{"k":"warn","title":"دام رایج","t":"پرامپتِ چندوظیفه‌ای («هم UI بساز، هم API بنویس، هم تست بزن، هم مستندات») تقریباً همیشه خروجی نیمه‌تمام می‌دهد. Agent وقتی چند هدف همزمان دارد، هیچ را کامل نمی‌کند؛ وظیفه را بشکن و هر بار یک کار بخواه — جمعِ چند دورِ کامل، بهتر از یک دورِ نیمه است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نقش و زمینه، چارچوب پاسخ را می‌سازد","یک وظیفه در هر پرامپت، نه چندتایش","از Agent بخواه قبل از کد، رویکردش را بگوید"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"پرامپت ساختاریافته","code":"## زمینه\nپروژه React+TS با Tailwind. زبان فارسی و RTL.\n\n## وظیفه\nکامپوننت جست‌وجو با debounce بساز.\n\n## قیدها\n- فقط Tailwind، بدون کتابخانه جدید\n- debounce با useEffect\n\n## خروجی\nکد کامپوننت + یک جمله توضیح رویکرد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نقش و زمینه، چارچوب پاسخ را می‌سازد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا بهتر است Agent قبل از کد، رویکردش را توضیح بدهد؟","opts":["طولانی‌تر","تا اگر رویکرد اشتباه است، قبل از تولید صدها خط کد اصلاحش کنی — ارزان‌ترین نقطه اصلاح","اجباری","سرعت"],"ans":1,"why":"اگر رویکرد غلط باشد، بعد از تولید کد، اصلاح گران است؛ گرفتن رویکرد اول، مثل ریویوی طراحی قبل از پیاده‌سازی است."},{"q":"چرا ارجاع به یک فایل موجود («مثل useFetch.ts») از توضیح متنی مؤثرتر است؟","opts":["کوتاه‌تر است","چون Agent را به یک نمونه واقعی و درست ارجاع می‌دهد و ابهامِ توصیف را حذف می‌کند — نشان دادن بهتر از گفتن است","سریع‌تر اجرا می‌شود","مدل جدیدتری می‌خواهد"],"ans":1,"why":"توصیفِ الگو همیشه ناقص است؛ فایل واقعی همه جزئیات (نام‌گذاری، مدیریت خطا، تایپ‌ها) را یکجا منتقل می‌کند و خروجی را با کد موجود هم‌سبک می‌سازد."},{"q":"اگر Agent مدام کتابخانه‌های جدید پیشنهاد می‌کند، بهترین پاسخ چیست؟","opts":["قبول کن تا سریع‌تر شود","در قیدهای پرامپت صریح بنویس «بدون وابستگی جدید» و بخواه با ابزار موجود حل کند","مدل را عوض کن","پروژه را از اول بساز"],"ans":1,"why":"Agent برای ساده‌کردن کارش تمایل به افزودن وابستگی دارد؛ ولی هر کتابخانه جدید هزینه نگهداری و امنیت می‌آورد. قیدِ صریح، این تصمیم را از سلیقه Agent به قرارداد پروژه برمی‌گرداند."}]'::jsonb),
('vibe-b4', 'vibe', 'حلقه بازخورد سریع', 63, 10, '[{"k":"p","t":"قدرت وایب در حلقه‌های کوتاه است: درخواست کوچک → اجرا → بازخورد دقیق → اصلاح. حلقه‌های بزرگ دیباگ را غیرممکن و اصلاح را گران می‌کنند."},{"k":"h","t":"حلقه بازخورد؛ ضربان وایب کدینگ"},{"k":"p","t":"تمام ارزش وایب کدینگ در سرعتِ حلقه «پیشنهاد → اجرا → مشاهده → اصلاح» است؛ هرچه این حلقه کوتاه‌تر و پر‌بازخوردتر باشد، خروجی زودتر به واقعیت می‌رسد. پس وظیفه اصلی تو ساختن زیرساختِ بازخورد سریع است: اجرای محلی داغ (hot reload)، تست‌هایی که در ثانیه جواب بدهند، و یک راه دیدنِ فوریِ نتیجه. وقتی فاصله هر دور به چند ثانیه برسد، حتی ده‌ها اصلاح کوچک ارزان‌تر از یک طراحی بزرگِ از اول درست می‌شود."},{"k":"h","t":"بازخورد جهت‌دار بده، نه کلی"},{"k":"p","t":"وقتی خروجی اشتباه است، «درستش کن» بدترین بازخورد است؛ Agent حدس می‌زند و اغلب همان اشتباه را با شکل جدید تکرار می‌کند. بازخورد خوب سه جزء دارد: چه چیزی دیده‌ای (پیام خطا یا رفتار غلط)، چه انتظاری داشتی، و در صورت امکان حدست از ریشه («احتمالاً چون state همزمان آپدیت می‌شود»). این اطلاعات، فضای جستجوی Agent را واقعاً کوچک می‌کند و معمولاً یک دور کافی است. اگر دو دور با همان خطا چرخید، مکث کن و گفتگو را با اطلاعات کامل از نو شروع کن — نه با فشار بیشتر."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"بازخورد بد در برابر بازخورد جهت‌دار","code":"# ❌ بد — Agent حدس می‌زند:\n«کار نمی‌کنه، درستش کن»\n\n# ✓ جهت‌دار — یک دور کافی است:\n«با کلیک روی ذخیره، خطای ''items is not defined''\nمی‌گیرم. انتظار دارم لیست جدید در localStorage\nذخیره شود. حدس: داخل handleSave از متغیر state\nقبل از تعریف استفاده شده؛ لطفاً همان‌جا را چک کن\nو فقط همان تابع را اصلاح کن.»"},{"k":"tip","title":"نکته منتور","t":"بعد از هر اصلاح موفق، یک Commit بزن — حتی کوچک. این کار دو فایده دارد: نقطه بازگشت امن قبل از دور بعدی داری، و تاریخچه‌ات می‌گوید کدام پرامپت/بازخورد واقعاً جواب داد تا الگوهای خوب را تکرار کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر دور یک تغییر کوچک و قابل‌بررسی","خطا را دقیق کپی کن، نه «کار نمی‌کند»","وقتی گیر کرد، گفتگوی تازه با context تمیز"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"حلقه وایب","code":"۱. درخواست کوچک و مشخص\n۲. اجرا و مشاهده نتیجه\n۳. بازخورد دقیق (خطا/رفتار اشتباه)\n۴. اصلاح ← تکرار\n— هر دور حداکثر چند دقیقه"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر دور یک تغییر کوچک و قابل‌بررسی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا بازخورد «کار نمی‌کند» بی‌فایده است؟","opts":["کوتاه","چون Agent نمی‌داند کجا و چطور خراب شده و حدس می‌زند؛ متن خطا و رفتار مشاهده‌شده، اصلاح را ممکن می‌کند","بی‌ادبانه","اجباری"],"ans":1,"why":"بدون اطلاعات دقیق، Agent حدس می‌زند و ممکن است چیز درست را خراب کند؛ متن خطا و رفتار واقعی، مسیر اصلاح را روشن می‌کند."},{"q":"چرا «درستش کن» بازخورد ضعیفی است؟","opts":["بی‌ادبانه است","چون هیچ اطلاعاتی درباره خطا نمی‌دهد و Agent را به حدس وا می‌دارد؛ معمولاً همان اشتباه با شکل جدید تکرار می‌شود","کوتاه است","مدل نمی‌فهمد"],"ans":1,"why":"کیفیت دورِ بعدی به کیفیت بازخورد قبلی وابسته است؛ بدون پیام خطا و انتظار روشن، Agent فضای بزرگی برای حدس‌زدن دارد و احتمالاً دورِ بعد هم به هدف نمی‌خورد."},{"q":"اگر Agent دو دور پشت‌سرهم با همان خطا چرخید، چه باید کرد؟","opts":["دور سوم را با تأکید بیشتر بخواه","مکث کن؛ با متن خطا، فایل مرتبط و کارهایی که امتحان شده، گفتگوی تازه شروع کن — ادامه گفتگوی آلوده معمولاً چاله را عمیق‌تر می‌کند","مدل را عوض کن","دستی بنویس و تسلیم شو"],"ans":1,"why":"گفتگوی طولانی فرض‌های غلط اولیه را با خود می‌کشد؛ یک شروع تازه با اطلاعات دقیق و فشرده، اغلب در همان دور اول چیزی را حل می‌کند که ده دور قبلی نتوانست."}]'::jsonb),
('vibe-b5', 'vibe', 'Agent و تفاوت با تکمیل کد', 56, 11, '[{"k":"p","t":"تکمیل‌کننده‌ها چند خط بعدی را حدس می‌زنند ولی Agent هدف می‌گیرد و حلقه برنامه‌ریزی، اجرا و اصلاح را می‌بندد — چند فایل می‌سازد و تست اجرا می‌کند."},{"k":"h","t":"تکمیل‌کننده کد در برابر Agent"},{"k":"p","t":"ابزارهای کمک‌کدنویسی دو سطح دارند. سطح اول، تکمیل‌کننده‌ها (مثل Copilot هنگام تایپ): فقط چند خط بعدی را بر اساس زمینه حدس می‌زنند و تو هنوز فرمان همه‌چیز را در دست داری. سطح دوم، Agentها: یک «هدف» می‌گیرند و خودشان حلقه برنامه‌ریزی، اجرا و اصلاح را می‌بندند — چند فایل می‌سازند، فرمان اجرا می‌کنند، خطا را می‌خوانند و دوباره تلاش می‌کنند تا کار تمام شود. تفاوت اساسی این است که تکمیل‌کننده «ادامه می‌دهد» ولی Agent «تعقیب می‌کند»؛ او یک کار کامل را تا رسیدن به نتیجه دنبال می‌کند."},{"k":"h","t":"چه‌وقت کدام؛ فرمان یا تفویض"},{"k":"p","t":"این دو برای حالت‌های متفاوت‌اند: تکمیل‌کننده برای وقتی است که می‌دانی چه می‌خواهی بنویسی و فقط سرعت می‌خواهی — فرمان جزئی دست توست. Agent برای وقتی است که می‌توانی یک کار مشخص و قابل‌سنجش را تعریف و تفویض کنی — مثل «این تست‌ها را پاس کن» یا «این باگ را با این خطا درست کن». ولی تفویض به Agent به معنی رهاکردن نیست؛ باید هدف و معیار «تمام‌شدن» را روشن بگویی و خروجی را مثل کار یک کارآموزِ باهوش ولی بی‌تجربه بازبینی کنی. هنر وایب کدینگ، دانستن این است که کدام کار را خودت بنویسی، کدام را تکمیل بگیری و کدام را تفویض کنی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","تکمیل‌کننده کد","Agent"],"rows":[["ورودی","زمینه و چند خط","یک هدف یا تسک"],["رفتار","ادامه‌دادن چند خط","حلقه برنامه‌ریزی، اجرا و اصلاح"],["قلمرو","چند خط، یک فایل","چند فایل، اجرای فرمان"],["نقش تو","نویسنده اصلی","تعریف هدف و بازبینی"]]},{"k":"warn","title":"دام رایج","t":"به Agent کارهای مبهم و بدون معیار نده؛ اگر نتوانی بگویی «تمام‌شدن یعنی چه»، Agent هم نمی‌تواند و معمولاً چیزی می‌سازد که «تقریباً» درست است و فهمیدنِ اشتباهش از نوشتنش سخت‌تر می‌شود. اول هدف و معیار را روشن کن، بعد تفویض کن."},{"k":"tip","title":"نکته منتور","t":"Agentها وقتی بهترین نتیجه را می‌دهند که بازخورد سریع و خودکار داشته باشند؛ اگر پروژه‌ات تست و lint و build خودکار دارد، Agent می‌تواند خودش خروجی‌اش را بررسی و اصلاح کند. پس سرمایه‌گذاری روی تست، مستقیماً قدرت Agent را هم بالا می‌برد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Copilot: تکمیل خط و تابع هنگام تایپ","Agent: هدف می‌گیرد، فایل می‌سازد، تست می‌زند","Agent به ترمینال و ابزار دسترسی دارد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"سطوح کمک AI","code":"تکمیل:     | نوشتن خط بعدی\nچت:        | جواب سوال کدی\nAgent:     | هدف → [برنامه‌ریزی → عمل → مشاهده] ×n"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Copilot: تکمیل خط و تابع هنگام تایپ بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت کلیدی Agent با تکمیل کد چیست؟","opts":["سرعت","Agent یک حلقه خودکار برنامه‌ریزی-عمل-مشاهده می‌بندد و چند فایل و ابزار را مدیریت می‌کند، نه فقط چند خط بعدی","اندازه","هزینه"],"ans":1,"why":"تکمیل‌کننده واکنشی و تک‌فایل است؛ Agent هدف‌گراست، خودش تصمیم می‌گیرد چه فایلی را تغییر دهد و نتیجه را بررسی می‌کند."},{"q":"تفاوت اساسی تکمیل‌کننده کد و Agent چیست؟","opts":["سرعت","تکمیل‌کننده چند خط بعدی را حدس می‌زند؛ Agent یک هدف می‌گیرد و با حلقه برنامه‌ریزی و اجرا، چند فایل را تا رسیدن به نتیجه دنبال می‌کند","قیمت","زبان"],"ans":1,"why":"تکمیل‌کننده «ادامه‌دهنده» است و فرمان دست توست؛ Agent «تعقیب‌کننده» است که خودش اجرا می‌کند، خطا می‌خواند و اصلاح می‌کند تا تسک تمام شود — سطح بالاتری از خودمختاری."},{"q":"قبل از تفویض کار به Agent، چه چیزی باید روشن باشد؟","opts":["سرعت اینترنت","هدف دقیق و معیار «تمام‌شدن»؛ وگرنه Agent چیزی تقریباً درست می‌سازد که بررسی‌اش سخت‌تر از نوشتن است","تعداد فایل","نوع فونت"],"ans":1,"why":"Agent بدون معیار نمی‌داند کی متوقف شود و چه چیزی را درست کند؛ با هدف و معیار روشن، هم نتیجه به خواسته تو نزدیک می‌شود و هم خودت می‌توانی سریع و قاطع بازبینی کنی."}]'::jsonb),
('vibe-b6', 'vibe', 'بازبینی خروجی AI', 56, 12, '[{"k":"p","t":"هر خروجی Agent باید مثل کد یک کارآموز باهوش ریویو شود: منطق، حذف‌های ناخواسته، وابستگی‌های جدید و الگوهای ناامن را چک کن."},{"k":"h","t":"خروجی Agent را مثل ریویوی یک هم‌تیمی ببین"},{"k":"p","t":"بزرگ‌ترین اشتباه در وایب کدینگ، پذیرش بی‌چون‌وچرای خروجی Agent است؛ چون کدش معمولاً تمیز و قابل‌اجرا به‌نظر می‌رسد، وسوسه می‌شوی فقط «اجرا شود» را چک کنی. ولی Agent مثل یک هم‌تیمی باهوش ولی بی‌تجربه است: می‌تواند منطق را اشتباه فهمیده باشد، یک حالت مرزی را نادیده گرفته باشد، یا وابستگی‌ای اضافه کرده باشد که لازم نبود. پس با همان جدیتی که Pull Request یک همکار را ریویو می‌کنی، خروجی Agent را هم ریویو کن — چه بسا بیشتر، چون او برعکس انسان، اشتباهش را با اعتمادبه‌نفس کامل تحویل می‌دهد."},{"k":"h","t":"چک‌لیست بازبینی؛ چه چیزی را نگاه کنی"},{"k":"p","t":"چند نقطه هست که Agentها در آن‌ها زیاد اشتباه می‌کنند و باید حتماً چک کنی: منطق اصلی (آیا واقعاً کاری که خواستم را می‌کند؟)، حالت‌های مرزی و خطا (ورودی خالی، عدد منفی، نبود داده)، وابستگی‌های جدید (آیا کتابخانه‌ای اضافه کرده که لازم بود؟ نسخه‌اش امن است؟)، و چیزهایی که حذف یا ساده کرده (گاهی برای راحت‌شدن، بخشی از منطق را می‌اندازد). ضمن اینکه از او بخواه توضیح بدهد چه کرد و چرا — توضیحش خیلی‌وقت‌ها فرض‌های اشتباهش را لو می‌دهد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["نقطه بررسی","سوال کلیدی"],"rows":[["منطق اصلی","آیا دقیقاً کاری که خواستم را می‌کند؟"],["حالت‌های مرزی","ورودی خالی/منفی/ناموجود چه می‌شود؟"],["وابستگی‌ها","کتابخانه جدید لازم بود و نسخه‌اش معتبر است؟"],["حذف‌ها","چیزی را برای ساده‌سازی نینداخته؟"]]},{"k":"warn","title":"دام رایج","t":"فقط «اجرا شدن» را معیار قبول خروجی نگیر؛ کدی که در حالت خوشحال اجرا می‌شود ولی با اولین ورودی عجیب می‌شکند یا منطقش نیمه‌درست است، از کدی که اصلاً اجرا نشود خطرناک‌تر است چون باگش دیرتر و بدتر خودش را نشان می‌دهد. همیشه حالت‌های مرزی را هم تست کن."},{"k":"tip","title":"نکته منتور","t":"یک عادت خوب: بعد از هر تسک، از Agent بخواه «چه چیزی را تغییر دادی و چرا، و چه چیزی را عمداً تغییر ندادی؟» — این خلاصه هم بازبینی‌ات را سریع می‌کند و هم خیلی‌وقت‌ها همین‌جا متوجه می‌شوی که فرضش با خواسته تو فرق داشته."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["git diff را خط‌به‌خط ببین — چه چیزی واقعاً عوض شد","وابستگی جدید نصب‌شده را قبل از قبول چک کن","APIها و importها را با مستندات راستی‌آزمایی کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"review.sh","code":"git diff --stat        # چه فایل‌هایی\ngit diff               # چه چیزی عوض شد\nnpm ls <package>       # وابستگی جدید چیست\ngrep -rn \"eval(\" src/  # الگوی ناامن"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: git diff را خط‌به‌خط ببین — چه چیزی واقعاً عوض شد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا باید حذف‌های Agent را هم چک کرد نه فقط اضافه‌ها؟","opts":["نیازی نیست","چون Agent گاهی برای حل مشکل، کد لازم را «تمیز» می‌کند و حذف‌ها نامرئی‌تر از اضافه‌ها هستند","سرعت","اجباری"],"ans":1,"why":"اضافه‌ها دیده می‌شوند؛ حذف‌ها نه. اگر فیچری ناگهان کار نکند، معمولاً چیزی پاک شده — diff را برای حذف‌ها هم بخوان."},{"q":"چرا نباید خروجی Agent را بدون بازبینی پذیرفت؟","opts":["چون کند است","چون ممکن است منطق را اشتباه فهمیده، حالت مرزی را نادیده گرفته یا وابستگی غیرضروری اضافه کرده باشد — و همه این‌ها را با اعتمادبه‌نفس تحویل می‌دهد","چون گران است","چون زشت است"],"ans":1,"why":"Agent برعکس انسان، هنگام اشتباه هم مطمئن به‌نظر می‌رسد و کدش تمیز اجرا می‌شود؛ پس فقط با بازبینی واقعی — مثل ریویوی یک هم‌تیمی — می‌توانی منطق و مرزها را تأیید کنی."},{"q":"در بازبینی خروجی Agent، کدام مورد جزو نقاط پرخطای رایج نیست؟","opts":["منطق اصلی","حالت‌های مرزی","رنگ پس‌زمینه IDE","وابستگی‌های جدید"],"ans":2,"why":"نقاط پرخطا جایی‌اند که Agent تصمیم می‌گیرد: منطق، مرزها، وابستگی‌ها و حذف‌ها. ظاهر IDE ربطی به خروجی او ندارد؛ پس گزینه سوم از بقیه جداست."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('vibe-b7', 'vibe', 'تست‌نویسی با کمک AI', 56, 13, '[{"k":"p","t":"Agent می‌تواند سناریو و تست بنویسد ولی سناریوهای مرزی از توست؛ الگو: سناریو و انتظار از تو، پیاده‌سازی تست از Agent، داوری با تو."},{"k":"h","t":"AI برای تست‌نویسی؛ نقطه قوت واقعی"},{"k":"p","t":"تست‌نویسی یکی از جایی است که کمک AI واقعاً می‌درخشد؛ چون تست کدی است با ساختار روشن و معیار درست/غلط مشخص. می‌توانی از Agent بخواهی برای یک تابع، تست‌های واحد بنویسد — شامل حالت‌های معمولی، مرزی و خطا. این هم سرعتت را چندبرابر می‌کند و هم پوششی می‌دهد که شاید دستی حوصله‌اش را نداشتی. ولی شرط مهم: سناریوها و انتظارات را تا جای ممکن خودت مشخص کن، چون Agent بهتر می‌تواند «تستِ چیزی که گفتی» را بنویسد تا اینکه خودش بفهمد چه چیزی مهم است."},{"k":"h","t":"مراقب تست‌های بی‌معنی و تکرار کد"},{"k":"p","t":"دو آفت رایج تست‌های AI-ساخته: اول، تست‌هایی که فقط کد را دوباره می‌نویسند و چیزی را نمی‌سنجند (مثلاً assert می‌کنند دقیقاً همان چیزی را که تابع برمی‌گرداند، بدون فکر به اینکه «درست» چیست)؛ دوم، تست‌های شکننده که به جزئیات پیاده‌سازی وابسته‌اند. پس بعد از تولید، تست‌ها را بازبینی کن: آیا واقعاً رفتار موردانتظار را می‌سنجند؟ آیا اگر کد را درست ریفکتور کنم می‌شکنند؟ و مهم‌تر، حتماً یک‌بار عمداً کد را خراب کن و ببین تست‌ها واقعاً قرمز می‌شوند — تستی که با کد خراب هم سبز بماند، بی‌ارزش است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["کار","سپردن به AI","نظارت تو"],"rows":[["نوشتن بدنه تست","بله — سرعت و پوشش","—"],["انتخاب سناریوهای مهم","کمک می‌گیرد","تصمیم نهایی با توست"],["تأیید اینکه واقعاً می‌سنجد","—","حتماً (خراب‌کردن عمدی کد)"]]},{"k":"warn","title":"دام رایج","t":"تستی که Agent نوشت و سبز شد را همین‌طور قبول نکن؛ حتماً یک‌بار رفتار موردنظر را عمداً نقض کن (مثلاً شرط را برعکس کن) و ببین تست قرمز می‌شود یا نه. اگر نشد، آن تست اصلاً چیزی را نمی‌سنجد و فقط یک assert تشریفاتی است."},{"k":"tip","title":"نکته منتور","t":"از Agent بخواه قبل از نوشتن تست، اول «سناریوهای مهم» را فهرست کند و تو تأیید یا اصلاح کنی؛ این یک مرحله کوچک، کیفیت تست‌ها را چند برابر می‌کند چون سناریوها — که مهم‌ترین بخش تست‌اند — از تو می‌آیند نه از حدس مدل."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سناریوهای مرزی را خودت بده (خالی، بزرگ، خطا)","از Agent بخواه تست را طوری بنویسد که اول شکست بخورد","خروجی تست را خودت اجرا و تأیید کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"پرامپت تست","code":"برای تابع normalize_phone این تست‌ها را بنویس:\n- ارقام فارسی «۰۹۱۲...» به انگلیسی\n- ''+98'' و ''0098'' به ''09''\n- ورودی کوتاه/بلند → None\nاول تست‌ها را بنویس (باید شکست بخورند)\nبعد تابع را اصلاح کن تا پاس شوند."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سناریوهای مرزی را خودت بده (خالی، بزرگ، خطا) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا سناریوی تست از تو و پیاده‌سازی از Agent؟","opts":["Agent نمی‌تواند","چون دانش مسئله و موارد مرزی واقعی نزد توست؛ اگر Agent هر دو را بدهد، سوءتفاهم مشترک تأیید می‌شود","سرعت","اجباری"],"ans":1,"why":"Agent کد را می‌فهمد ولی مسئله را نه؛ سناریوهای واقعی (مثل ارقام فارسی) را فقط کسی که کاربر را می‌شناسد می‌دهد."},{"q":"چرا تست‌نویسی برای کمک AI مناسب است؟","opts":["چون سخت است","چون تست ساختار روشن و معیار درست/غلط مشخص دارد و AI می‌تواند سریع حالت‌های متعدد را پوشش دهد","چون کوتاه است","چون نیاز به فکر ندارد"],"ans":1,"why":"تست برعکس طراحیِ باز، یک شکل مشخص دارد و نتیجه‌اش قابل‌سنجش است؛ پس AI می‌تواند با سرعت و پوشش بالا بنویسدش، درحالی‌که تو روی سناریوهای مهم نظارت می‌کنی."},{"q":"چطور می‌فهمی یک تستِ AI-ساخته واقعاً چیزی را می‌سنجد؟","opts":["اگر سبز شود","با عمداً خراب‌کردن رفتار کد و دیدن اینکه تست قرمز می‌شود؛ تستی که با کد خراب هم سبز بماند بی‌ارزش است","اگر طولانی باشد","اگر Agent تأیید کند"],"ans":1,"why":"تست‌های بی‌معنی حتی با کد اشتباه هم سبز می‌مانند چون واقعاً رفتار را چک نمی‌کنند؛ تنها راه مطمئن، نقض عمدی رفتار و دیدن قرمزشدن تست است — این تستِ خودِ تست است."}]'::jsonb),
('vibe-b8', 'vibe', 'Refactor با Agent', 56, 14, '[{"k":"p","t":"Agent برای refactor عالی است چون بی‌خستگی است؛ با شبکه اطمینان تست، می‌توانی استخراج متد، تغییر نام و ساده‌سازی را با اطمینان بسپاری."},{"k":"h","t":"Refactor با Agent؛ فرصت و احتیاط"},{"k":"p","t":"Refactor — تمیزکردن ساختار کد بدون تغییر رفتار — کاری است که Agent در آن خیلی خوب کمک می‌کند: استخراج متد، تغییر نام، ساده‌سازی شرط‌ها و جداسازی مسئولیت‌ها را سریع انجام می‌دهد. ولی دقیقاً همین‌جا خطر اصلی هم هست: مرز بین «تغییر ساختار» و «تغییر رفتار» باریک است و Agent گاهی هنگام تمیزکردن، ناخواسته رفتار را هم عوض می‌کند. پس شرط Refactor امن با Agent این است که قبلش تست‌های خوبی داشته باشی که رفتار فعلی را قفل کرده‌اند؛ آن‌وقت بعد از Refactor، سبزماندنِ همان تست‌ها یعنی رفتار عوض نشده."},{"k":"h","t":"گام‌های کوچک و تأیید در هر قدم"},{"k":"p","t":"به Agent نگو «کل این فایل را ریفکتور کن»؛ چون یک تغییر بزرگ، بررسی‌ناپذیر می‌شود و اگر رفتاری عوض شده باشد پیداکردنش سخت است. به‌جای آن، Refactor را به گام‌های کوچک و مستقل بشکن — هر بار یک استخراج یا یک تغییر نام — و بعد از هر گام، تست‌ها را اجرا و diff را بازبینی کن. این ریتم کوچک، هم بررسی را آسان می‌کند و هم اگر جایی رفتار عوض شد، دقیقاً می‌دانی کدام گام بوده. ضمن اینکه از Agent بخواه در هر گام بگوید «این تغییر چه چیزی را عوض کرد و چرا رفتار حفظ می‌شود»."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Refactor دستی","Refactor با Agent"],"rows":[["سرعت","کندتر","خیلی سریع"],["ریسک تغییر رفتار","تحت کنترل نویسنده","بالاتر؛ نیاز به تستِ قفل‌کننده رفتار"],["پیش‌نیاز مهم","—","تست‌های خوبی که رفتار فعلی را می‌سنجند"]]},{"k":"warn","title":"دام رایج","t":"روی کدی که تست ندارد Refactor بزرگ با Agent انجام نده؛ چون بعدش هیچ راهی نداری بفهمی رفتار عوض شده یا نه. اول چند تست برای رفتار فعلی بنویس (با کمک خود Agent)، مطمئن شو سبزند، و بعد ریفکتور کن — این ترتیب، امنیت را می‌سازد."},{"k":"tip","title":"نکته منتور","t":"بعد از هر Refactor با Agent، diff را با یک سوال بخوان: «آیا این تغییر فقط ساختار را عوض کرد؟» اگر جایی دیدی یک شرط، مقدار یا ترتیب عوض شده، همان‌جا مکث کن و از Agent بخواه توضیح بدهد — خیلی‌وقت‌ها همان یک خط، جایی است که رفتار ناخواسته عوض شده."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["قبل از refactor بزرگ، مطمئن شو تست داری","رفکتور را مرحله‌به‌مرحله بخواه نه همه‌جا یک‌دفعه","بعد از هر مرحله، تست‌ها را اجرا و diff را ببین"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"پرامپت refactor","code":"این تابع ۸۰ خطی را به توابع کوچک‌تر بشکن:\n- هر تابع یک مسئولیت\n- نام‌های گویا\n- رفتار دقیقاً همان بماند\nبعد از تغییر، توضیح بده چه چیزی جدا شد."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: قبل از refactor بزرگ، مطمئن شو تست داری بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا refactor را باید مرحله‌به‌مرحله از Agent خواست؟","opts":["محدودیت","تا هر مرحله قابل‌بررسی و قابل‌بازگشت باشد؛ refactor یک‌دفعه بزرگ، ریشه‌یابی تغییرات را غیرممکن می‌کند","سرعت","اجباری"],"ans":1,"why":"اگر Agent ده‌ها جا را یک‌دفعه عوض کند و تستی بشکند، نمی‌دانی کدام تغییر مقصر است؛ مراحل کوچک، هر تغییر را ایزوله می‌کند."},{"q":"پیش‌نیاز Refactor امن با Agent چیست؟","opts":["سرعت بالا","تست‌های خوبی که رفتار فعلی را قفل کرده‌اند؛ تا بعد از ریفکتور، سبزماندنشان یعنی رفتار عوض نشده","فایل کوچک","اینترنت پرسرعت"],"ans":1,"why":"چون Agent ممکن است هنگام تمیزکردن ناخواسته رفتار را عوض کند، تنها راه تشخیص، تست‌هایی است که رفتار قبلی را می‌سنجند؛ اگر بعد از ریفکتور سبز ماندند، خیالت راحت است که فقط ساختار عوض شده."},{"q":"چرا Refactor با Agent را باید گام‌به‌گام و کوچک انجام داد؟","opts":["چون Agent ضعیف است","چون تغییر بزرگ بررسی‌ناپذیر است و اگر رفتاری عوض شده باشد پیداکردنش سخت می‌شود؛ گام کوچک، بررسی و ریشه‌یابی را آسان می‌کند","چون کند می‌شود","اجباری است"],"ans":1,"why":"اگر ده تغییر در یک diff باشد و رفتار عوض شده باشد، نمی‌دانی کدام مقصر است؛ ولی با گام‌های کوچک و تست بعد از هر گام، هم بررسی آسان است و هم خطا دقیقاً به همان گام برمی‌گردد."}]'::jsonb),
('vibe-b9', 'vibe', 'دیباگ با Agent', 63, 15, '[{"k":"p","t":"Agent در دیباگ خوب است به‌شرط اطلاعات کافی؛ متن خطای کامل، کد مرتبط و کارهایی که امتحان شده را بده و از او بخواه فرضیه‌ها را بگوید نه فقط راه‌حل."},{"k":"h","t":"دیباگ با Agent؛ اطلاعات خوب، جواب خوب"},{"k":"p","t":"Agent در دیباگ فوق‌العاده است — به‌شرطی که اطلاعات کافی داشته باشد. بزرگ‌ترین اشتباه، فرستادن یک جمله مبهم مثل «کار نمی‌کند» است. در عوض، سه چیز را کامل بده: متن دقیق خطا همراه با stack trace، قطعه کدی که خطا در آن رخ داده (نه کل فایل)، و مهم‌تر از همه فهرست چیزهایی که قبلاً امتحان کرده‌ای. این آخری حیاتی است چون فضای جست‌وجو را کوچک می‌کند؛ وقتی Agent بداند optional chaining را امتحان کرده‌ای و جواب نداده، دیگر آن را پیشنهاد نمی‌دهد و سراغ فرضیه‌های قوی‌تر می‌رود."},{"k":"h","t":"فرضیه بخواه، نه فقط راه‌حل"},{"k":"p","t":"به‌جای اینکه بگویی «درستش کن»، بخواه فرضیه‌هایش را به ترتیب احتمال بگوید و برای هرکدام یک راه بررسی پیشنهاد دهد. این کار دو فایده دارد: اول اینکه خودت هم یاد می‌گیری چطور فکر کند، دوم اینکه اگر فرضیه اول غلط بود، بقیه آماده‌اند. یک الگوی خوب: «سه فرضیه محتمل را بگو، برای هرکدام یک فرمان یا تست بده که در ۳۰ ثانیه تأیید یا ردش کنم.» این‌طوری دیباگ از یک حدس بزرگ، به چند آزمایش کوچک و سریع تبدیل می‌شود — دقیقاً روش مهندسی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک پرامپت دیباگ واقعی","code":"خطا:\n  TypeError: Cannot read properties of undefined (reading ''map'')\n  در UserList.tsx:12\n\nکد اطراف خط ۱۲:\n  {users.map(u => <Row user={u} />)}\n\nstate:\n  const [users, setUsers] = useState();   // بدون مقدار اولیه!\n\nقبلاً امتحان شده:\n  - optional chaining روی users (خطا جابه‌جا شد ولی رفع نشد)\n  - console.log(users) → undefined در رندر اول\n\nفرضیه‌هایت را به ترتیب احتمال بگو و برای\nهرکدام یک راه بررسی ۳۰ ثانیه‌ای پیشنهاد بده."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["عنصر پرامپت دیباگ","چرا لازم است"],"rows":[["متن کامل خطا + stack","نقطه شروع دقیق؛ بدون آن Agent حدس می‌زند"],["کد مرتبط (نه همه)","تمرکز روی محل واقعی مشکل"],["چه چیزهایی امتحان شده","حذف راه‌های بن‌بست از فضای جست‌وجو"],["درخواست فرضیه رتبه‌بندی‌شده","تبدیل حدس بزرگ به آزمایش‌های کوچک"]]},{"k":"tip","title":"نکته منتور","t":"وقتی Agent راه‌حلی داد و کار کرد، یک لحظه بپرس «چرا کار کرد؟» — اگر نتواند توضیح قانع‌کننده بدهد، شاید فقط صورت‌مسئله را پاک کرده باشد و باگ اصلی هنوز آنجا باشد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["متن کامل خطا + stack trace را بده","بگو چه چیزی امتحان شده تا تکرار نکند","از Agent بخواه فرضیه‌ها را رتبه‌بندی و تست کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"پرامپت دیباگ","code":"خطا:\nTypeError: Cannot read properties of undefined (reading ''map'')\nدر UserList.tsx:12\n\nکد: [مقطعی مرتبط]\n\nقبلاً امتحان شده:\n- optional chaining روی user\nفرضیه‌هایت را به ترتیب احتمال بگو\nو برای هرکدام یک راه بررسی پیشنهاد بده."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: متن کامل خطا + stack trace را بده بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا گفتن «چه چیزهایی امتحان شده» در دیباگ مهم است؟","opts":["ادب","تا Agent همان راه‌های بی‌اثر را تکرار نکند و از اطلاعات حذف‌شده، فرضیه‌های قوی‌تری بسازد","اجباری","سرعت"],"ans":1,"why":"دانستن راه‌های شکست‌خورده، فضای جست‌وجو را کوچک می‌کند؛ Agent می‌تواند از حذف گزینه‌ها نتیجه بگیرد و مستقیم‌تر به علت برسد."},{"q":"چرا در پرامپت دیباگ می‌گوییم چه چیزهایی امتحان شده؟","opts":["برای ادب","تا Agent راه‌های بی‌اثر را تکرار نکند و از حذف آن‌ها فرضیه قوی‌تری بسازد","اجباری است","برای سرعت تایپ"],"ans":1,"why":"هر راه شکست‌خورده، یک شاخه از فضای جست‌وجو را حذف می‌کند؛ Agent با این اطلاعات مستقیم‌تر به علت اصلی می‌رسد."},{"q":"چرا درخواست «فرضیه رتبه‌بندی‌شده» بهتر از «راه‌حل» است؟","opts":["کوتاه‌تر است","چون دیباگ را به چند آزمایش کوچک و سریع تبدیل می‌کند و اگر اولی غلط بود بقیه آماده‌اند","Agent را خوشحال می‌کند","فرقی ندارد"],"ans":1,"why":"راه‌حلِ تنها یعنی یک حدس بزرگ؛ فرضیه‌های رتبه‌بندی‌شده یعنی روش علمی — آزمایش سریع، رد یا تأیید، حرکت به بعدی."}]'::jsonb),
('vibe-b10', 'vibe', 'MCP و اتصال Agent به ابزار', 63, 16, '[{"k":"p","t":"MCP پروتکل استانداردی است که به مدل اجازه می‌دهد به دیتابیس، فایل و API وصل شود؛ Agent به‌جای اینکه فقط متن تولید کند، مستقیم داده می‌خواند و عمل می‌کند."},{"k":"h","t":"MCP؛ پورت استانداردِ اتصال Agent به دنیای واقعی"},{"k":"p","t":"Model Context Protocol یا MCP پروتکلی است که به مدل‌ها اجازه می‌دهد به ابزارها و داده‌های واقعی وصل شوند — دیتابیس، فایل‌سیستم، APIهای داخلی، ترمینال. قبل از MCP، جریان کار این بود: کد را کپی کن، به چت paste کن، جواب را بگیر، دستی برگردان. با MCP، Agent مستقیم می‌پرسد و عمل می‌کند. این دقیقاً همان کاری است که USB برای دستگاه‌ها کرد: یک پورت استاندارد که همه‌چیز به آن وصل می‌شود و دیگر لازم نیست برای هر ابزار یک راه اختصاصی ساخت."},{"k":"h","t":"چرا MCP یک مهارت رو به رشد است"},{"k":"p","t":"Agent بدون اتصال به دنیای واقعی فقط متن تولید می‌کند؛ با اتصال، می‌تواند داده واقعی بخواند، کوئری بزند، نتیجه را ببیند و بر اساس آن تصمیم بگیرد. مثلاً یک Agent متصل به دیتابیس می‌تواند خودش schema را بخواند و کوئری درست بنویسد، بدون اینکه تو schema را دستی توضیح بدهی. ساختن MCP server برای سیستم‌های داخلی یک شرکت — یعنی وصل‌کردن Agent به داده‌های واقعی آن — دارد به یکی از پرتقاضاترین مهارت‌های مهندسی تبدیل می‌شود. کسی که بلد است Agent را به سیستم‌های واقعی وصل کند، یک اهرم چندبرابری نسبت به کسی دارد که فقط پرامپت می‌نویسد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"جریان کار قبل و بعد از MCP","code":"قبل از MCP:\n  تو → کد/schema را کپی کن → به چت paste کن\n     → جواب بگیر → دستی به پروژه برگردان\n  (همه‌چیز دستی، کند، و مستقیمِ خطا)\n\nبعد از MCP:\n  تو → «یک گزارش فروش این ماه بده»\n     → Agent → [MCP] → دیتابیس\n     → Agent کوئری می‌زند، نتیجه را می‌بیند، گزارش می‌سازد\n  (مستقیم، زنده، بدون کپی-پیست)"},{"k":"def","term":"MCP (Model Context Protocol)","t":"پروتکل استانداردی که به مدل‌های زبانی اجازه می‌دهد به ابزارها و منابع خارجی — دیتابیس، فایل، API — وصل شوند و با آن‌ها بخوانند و عمل کنند؛ معنای عملی‌اش تبدیل Agent از «تولیدکننده متن» به «عامل متصل به دنیای واقعی» است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","بدون MCP","با MCP"],"rows":[["دسترسی به داده","کپی-پیست دستی","اتصال مستقیم و زنده"],["به‌روزبودن","به تاریخ paste","همیشه الان"],["عمل کردن","تو دستی اجرا می‌کنی","Agent مستقیم عمل می‌کند"],["مقیاس","محدود به حافظه مدل","کل دیتابیس/API"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["MCP پورت استاندارد اتصال مدل به ابزار است","Agent مستقیم دیتابیس را می‌پرسد، نه با کپی-پیست","ساخت MCP server یک مهارت رو به رشد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"قبل و بعد MCP","code":"قبل: کد را کپی کن → به چت paste کن → جواب را برگردان\nبعد: Agent → [MCP] → دیتابیس/API/فایل\n     مستقیم می‌پرسد و عمل می‌کند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: MCP پورت استاندارد اتصال مدل به ابزار است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"MCP چه چیزی را برای Agent ممکن می‌کند؟","opts":["سریع‌تر شدن","اتصال استاندارد و امن به داده‌ها و ابزارهای واقعی تا مستقیم بخواند و عمل کند، نه فقط متن تولید کند","کمتر هزینه","UI بهتر"],"ans":1,"why":"بدون اتصال، Agent فقط متن می‌سازد و همه‌چیز باید دستی کپی شود؛ MCP آن را به دنیای واقعی وصل می‌کند."},{"q":"MCP چه چیزی را برای Agent ممکن می‌کند؟","opts":["سریع‌تر شدن مدل","اتصال استاندارد به داده‌ها و ابزارهای واقعی تا مستقیم بخواند و عمل کند، نه فقط متن تولید کند","کمتر شدن هزینه","رابط کاربری بهتر"],"ans":1,"why":"بدون اتصال، Agent فقط متن می‌سازد و همه داده‌ها باید دستی کپی شوند؛ MCP آن را به دنیای واقعی وصل می‌کند تا زنده بخواند و عمل کند."},{"q":"چرا «ساخت MCP server» یک مهارت ارزشمند است؟","opts":["چون سخت است","چون وصل‌کردن Agent به داده‌های داخلی یک سازمان، اهرمی چندبرابری می‌سازد که فراتر از پرامپت‌نویسی است","چون مد شده","چون مدل‌ها به آن نیاز دارند"],"ans":1,"why":"هر سازمان داده‌های داخلی خودش را دارد؛ کسی که بتواند Agent را به این داده‌ها وصل کند، ارزشی می‌سازد که با پرامپت‌نویسی خالص قابل‌رسیدن نیست."}]'::jsonb),
('vibe-b11', 'vibe', 'محدودیت‌ها و توهم Agent', 63, 17, '[{"k":"p","t":"Agentها گاهی با اعتمادبه‌نفس اشتباه می‌کنند: API خیالی، پکیج ناموجود، منطق درست‌نما ولی غلط. راه‌حل شک‌کردن سیستماتیک و راستی‌آزمایی است."},{"k":"h","t":"توهم Agent؛ اعتمادبه‌نفسِ بدون ضمانت"},{"k":"p","t":"Agentها یک ضعف ذاتی دارند: وقتی نمی‌دانند، با همان لحن مطمئنِ وقتی که می‌دانند جواب می‌دهند. رایج‌ترین شکل‌ها: فراخوانی API یا تابعی که وجود ندارد (چون شبیه چیزی است که هست)، پیشنهاد پکیجی که ساخته نشده یا مدت‌ها رها شده، و منطقی که درست به‌نظر می‌رسد ولی یک حالت مرزی را اشتباه رسیدگی می‌کند. نکته مهم این است که این‌ها باگ نیستند — طبیعتِ سیستم‌اند. پس راه‌حل، امید به بهترشدن مدل نیست؛ راه‌حل، شک‌کردن سیستماتیک و راستی‌آزمایی توسط توست."},{"k":"h","t":"چک‌لیست اعتماد؛ چهار سوال قبل از قبول هر خروجی"},{"k":"p","t":"قبل از merge کردن هر کدی که Agent نوشته، چهار سوال بپرس: آیا این تابع یا کلاس واقعاً در این کتابخانه وجود دارد؟ (با مستندات چک کن، نه حافظه). آیا این پکیج در npm یا PyPI موجود و فعال است؟ (تعداد دانلود و تاریخ آخرین نسخه را ببین). آیا منطقش را خودم خط‌به‌خط دنبال کردم و درست است؟ (به‌ویژه حالت‌های مرزی). و آیا تستش پاس می‌شود — نه فقط کامپایل می‌شود؟ این چهار سوال شاید دو دقیقه وقت بگیرند، ولی جلوی ساعت‌ها دیباگِ «چرا این کار نمی‌کند» را می‌گیرند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"چک‌لیست اعتماد قبل از قبول خروجی Agent","code":"□ این تابع/کلاس واقعاً در این نسخه کتابخانه هست؟\n    → چک در مستندات رسمی، نه حافظه\n□ این پکیج در npm/PyPI موجود و فعال است؟\n    → تعداد دانلود + تاریخ آخرین انتشار\n□ منطق را خودم دنبال کردم و درست است؟\n    → مخصوصاً حالت‌های مرزی (خالی، null، تکراری)\n□ تستش پاس می‌شود، نه فقط کامپایل می‌شود؟\n    → کامپایل یعنی «نوشتنی است»، تست یعنی «درست است»"},{"k":"warn","title":"دام رایج","t":"خطرناک‌ترین حالت وقتی است که Agent هم کد را نوشته و هم تست را. اگر سناریوی تست را خودت نداده باشی، ممکن است هر دو یک سوءتفاهم مشترک را تأیید کنند و سبزِ دروغین بگیری. همیشه سناریوی تست را خودت مشخص کن."},{"k":"tip","title":"نکته منتور","t":"اگر Agent پکیجی پیشنهاد کرد که نشناختی، بگو «مطمئنی این پکیج وجود دارد؟ لینک registry‌اش را بده». همین یک سوال ساده، نرخ پکیج‌های خیالی را به‌شدت پایین می‌آورد چون مدل را وادار می‌کند به‌جای حدس، بررسی کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["API و import را با مستندات چک کن","پکیج پیشنهادی را در registry جست‌وجو کن","کدی که نمی‌فهمی را قبول نکن — بپرس تا توضیح بدهد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"چک‌لیست اعتماد","code":"□ این تابع/کلاس واقعاً در این کتابخانه هست؟\n□ این پکیج در npm/PyPI موجود و فعال است؟\n□ این منطق را خودم دنبال کردم و درست است؟\n□ تستش پاس می‌شود (نه فقط کد کامپایل می‌شود)؟"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: API و import را با مستندات چک کن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا قبول کدی که خودت نمی‌فهمی خطرناک است؟","opts":["کند","چون وقتی مشکلی پیش بیاید، تنها کسی که باید نجاتش بدهد تویی و اگر نفهمیده باشی، نمی‌توانی دیباگش کنی","اجباری","هزینه"],"ans":1,"why":"کد Agent ممکن است کار کند تا روزی که نکند؛ اگر منطقش را نفهمیده باشی، در لحظه خرابی دست‌بسته‌ای — پس تا نفهمیدی تأیید نکن."},{"q":"چرا قبول کدی که خودت نمی‌فهمی خطرناک است؟","opts":["چون کند است","چون وقتی مشکلی پیش بیاید تنها کسی که باید نجاتش بدهد تویی، و اگر نفهمیده باشی نمی‌توانی دیباگش کنی","چون اجباری است","چون هزینه دارد"],"ans":1,"why":"کد Agent ممکن است ماه‌ها کار کند تا روزی که نکند؛ اگر منطقش را نفهمیده باشی، در لحظه خرابی دست‌بسته‌ای. پس تا نفهمیدی تأیید نکن."},{"q":"تفاوت «کامپایل می‌شود» و «تست پاس می‌شود» چرا مهم است؟","opts":["فرقی ندارند","کامپایل فقط یعنی کد نوشتنی است؛ تست یعنی منطق واقعاً درست رفتار می‌کند — و این دومیه که Agent گاهی اشتباه می‌کند","تست کندتر است","کامپایل مهم‌تر است"],"ans":1,"why":"Agent کدی می‌نویسد که کامپایل می‌شود ولی در یک حالت مرزی اشتباه است؛ فقط تست است که این را لو می‌دهد."}]'::jsonb),
('vibe-b12', 'vibe', 'جریان کار حرفه‌ای وایب', 63, 18, '[{"k":"p","t":"وایب حرفه‌ای یعنی Git قبل از هر ریسک، حلقه‌های کوچک، Spec برای کارهای بزرگ و بازبینی هر خروجی — سرعت بالا با ایمنی مهندسی."},{"k":"h","t":"وایب حرفه‌ای؛ سرعت بالا با ایمنی مهندسی"},{"k":"p","t":"تفاوت وایبِ تازه‌کار و حرفه‌ای در سرعت کدزدن نیست — در ایمنی است. وایب حرفه‌ای چهار عادت دارد: قبل از هر تغییر بزرگ commit می‌زند تا نقطه بازگشت داشته باشد؛ کارها را در حلقه‌های کوچک می‌شکند تا هر لحظه حداکثر یک چیز خراب باشد؛ برای کارهای بزرگ اول Spec می‌نویسد و بعد می‌سازد؛ و هر خروجی را بازبینی می‌کند. نتیجه، سرعتی است که پایدار می‌ماند — نه سرعتی که بعد از دو روز به یک گره کور تبدیل شود."},{"k":"h","t":"کارهای خطرناک را دستی نگه دار"},{"k":"p","t":"هرچه تغییر پرریسک‌تر باشد، نظارت انسانی باید بیشتر باشد. migration دیتابیس، refactor بزرگ ساختاری، حذف فایل‌ها، و تغییرات امنیتی — این‌ها را نباید بی‌چک به Agent سپرد. الگوی درست: Agent پیشنهاد بدهد و پیش‌نویس کند، ولی تأیید نهایی و اجرا با تو باشد. یک قاعده سرانگشتی: اگر نتوانی با یک فرمان git تغییر را کامل برگردانی، قبل از اجرا یک‌بار بیشتر فکر کن. سرعت در کارهای کم‌ریسک، دقت در کارهای پرریسک — این فرمول وایبِ ماندگار است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"الگوی checkpoint قبل از سپردن کار بزرگ","code":"# ۱) قبل از هر تغییر بزرگ، نقطه بازگشت بساز\ngit add -A && git commit -m \"checkpoint: قبل از refactor بزرگ\"\n\n# ۲) حالا Agent آزادانه تغییر بدهد...\n#    (صدها خط ممکن است عوض شود)\n\n# ۳) اگر مسیرش غلط بود، بازگشت یک فرمان است:\ngit checkout .        # یا git reset --hard HEAD\n\n# ۴) اگر درست بود، checkpoint بعدی:\ngit add -A && git commit -m \"refactor: ساختار جدید تأیید شد\""},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["نوع کار","میزان نظارت انسانی"],"rows":[["ساخت فیچر کوچک","کم — بازبینی سریع خروجی"],["refactor متوسط","متوسط — بازبینی diff قبل از commit"],["migration دیتابیس","زیاد — پیش‌نویس Agent، تأیید و اجرای انسانی"],["تغییر امنیتی/حذف","کامل — هیچ‌وقت بی‌چک به Agent سپرده نشود"]]},{"k":"tip","title":"نکته منتور","t":"عادت «commit قبل از ریسک» را حتی وقتی با دست خودت کد می‌زنی حفظ کن. این فقط برای Agent نیست — هر برنامه‌نویس حرفه‌ای می‌داند که ارزان‌ترین بیمه در برنامه‌نویسی، یک commit به‌موقع است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["قبل از هر تغییر بزرگ commit بزن (نقطه بازگشت)","Spec بنویس → بساز → بازبینی → تست","کارهای خطرناک (migration، refactor بزرگ) را دستی تأیید کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"workflow.sh","code":"git add . && git commit -m \"checkpoint: قبل از refactor\"\n# حالا Agent می‌تواند آزادانه تغییر بدهد\n# اگر خراب شد:\ngit checkout .        # بازگشت به checkpoint"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: قبل از هر تغییر بزرگ commit بزن (نقطه بازگشت) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا قبل از سپردن کار بزرگ به Agent، commit می‌زنیم؟","opts":["اجباری","چون Agent ممکن است مسیر را اشتباه برود؛ commit یک نقطه بازگشت امن است که ریسکِ تغییرات گسترده را صفر می‌کند","سرعت","زیبایی"],"ans":1,"why":"وقتی Agent صدها خط را عوض می‌کند، اگر مسیرش غلط باشد، بازگشت دستی سخت است؛ یک commit قبلش، بازگشت را یک فرمان می‌کند."},{"q":"چرا قبل از سپردن کار بزرگ به Agent، commit می‌زنیم؟","opts":["چون اجباری است","چون Agent ممکن است مسیر را اشتباه برود و commit یک نقطه بازگشت امن است که ریسک تغییرات گسترده را صفر می‌کند","برای سرعت","برای زیبایی تاریخچه"],"ans":1,"why":"وقتی Agent صدها خط را عوض می‌کند و مسیرش غلط باشد، بازگشت دستی سخت است؛ یک commit قبلش، بازگشت را یک فرمان می‌کند."},{"q":"کدام کار را نباید بی‌چک به Agent سپرد؟","opts":["ساخت یک کامپوننت کوچک","migration دیتابیس و تغییرات امنیتی — چون پرریسک‌اند و تأیید و اجرای انسانی می‌خواهند","نوشتن تست","تولید مستندات"],"ans":1,"why":"هرچه تغییر پرریسک‌تر و بازگشتش سخت‌تر باشد، نظارت انسانی باید بیشتر باشد؛ migration و امنیت دقیقاً همین‌اند."}]'::jsonb),
('ub-r1', 'linux', 'اوبونتو و دنیای گنو/لینوکس؛ چرا این سیستم‌عامل اینترنت را می‌گرداند', 45, 1, '[{"k":"p","t":"بیش از ۹۰٪ سرورهای ابری دنیا، همه ابررایانه‌های برتر جهان و میلیاردها دستگاه اندروید روی یک خانواده سیستم‌عامل می‌دوند: لینوکس. وقتی لینوکس را می‌فهمی، با «زیرزمین» دنیای نرم‌افزار آشنا شده‌ای — جایی که همه‌چیز واقعاً اتفاق می‌افتد."},{"k":"h","t":"لینوکس چیست و اوبونتو کجای آن است"},{"k":"p","t":"«لینوکس» در اصل فقط هسته (Kernel) است — برنامه‌ای که سخت‌افزار را مدیریت می‌کند. «گنو/لینوکس» یعنی هسته لینوکس به‌همراه هزاران ابزار آزاد گنو که یک سیستم‌عامل کامل می‌سازند. و «توزیع» (Distribution) یعنی یک بسته‌بندی آماده از این مجموعه: دبیان، فدورا، آرچ… اوبونتو توزیعی بر پایه دبیان است که از ۲۰۰۴ با شعار «لینوکس برای انسان‌ها» شروع شد و امروز متعادل‌ترین نقطه شروع است: جامعه بزرگ، مستندات فارسی و انگلیسی فراوان، و پشتیبانی تجاری Canonical."},{"k":"h","t":"LTS در برابر نسخه‌های میان‌مدت"},{"k":"p","t":"اوبونتو هر شش ماه یک نسخه و هر دو سال یک نسخه LTS (پشتیبانی بلندمدت) منتشر می‌کند. نسخه‌های LTS مثل 22.04 و 24.04 پنج سال به‌روزرسانی امنیتی رایگان می‌گیرند — برای سرور، همیشه LTS نصب کن. نسخه‌های میان‌مدت (مثل 24.10) فقط ۹ ماه پشتیبانی می‌شوند و برای میزکارِ علاقه‌مندان‌اند. این تصمیم ساده — LTS برای سرور — جلوی بخش بزرگی از دردهای آینده را می‌گیرد."},{"k":"h","t":"میزکار یا سرور؟ هر دو را بشناس"},{"k":"p","t":"Ubuntu Desktop با رابط گرافیکی GNOME برای لپ‌تاپ و توسعه روزانه است؛ Ubuntu Server بدون گرافیک، سبک و آماده برای تولید. مهم‌تر از انتخاب اولیه: مهارت کار با سرور یعنی SSH به یک ماشین بدون گرافیک — و این مهارتی است که حتی توسعه‌دهنده فرانت‌اند هم هر روز استفاده می‌کند. پس از همین ابتدا به ترمینال به‌عنوان خانه اصلی‌ات نگاه کن، نه مهمان‌خانه."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"اولین گفتگو با سیستم","code":"lsb_release -a        # نسخه دقیق اوبونتو\nuname -r              # نسخه هسته لینوکس\nuptime                # از کی روشن است و چقدر بار دارد\nhostnamectl           # نام ماشین و سیستم‌عامل\nfree -h               # حافظه به شکل خوانا\ndf -h /               # فضای دیسک روت"},{"k":"list","items":["این شش فرمان، «کارت شناسایی» هر سیستم لینوکسی‌اند؛ قبل از هر کاری روی سرور جدید، اول این‌ها را بزن تا بدانی کجایی.","uname -r نسخه هسته را می‌گوید — وقتی درایوری نصب نمی‌شود یا ویژگی‌ای نیست، اول همین را چک کن.","آرگومان h- یعنی human-readable؛ بدون آن اعداد به بایت‌اند و خواندنشان عذاب است."]},{"k":"def","term":"هسته (Kernel)","t":"برنامه مرکزی سیستم‌عامل که مستقیم با سخت‌افزار حرف می‌زند: مدیریت پردازنده، حافظه، دیسک و شبکه. همه برنامه‌های دیگر از طریق «فراخوانی سیستمی» (syscall) از هسته خدمت می‌خواهند — و این مرز دقیقاً جایی است که امنیت سیستم‌عامل شروع می‌شود."},{"k":"table","head":["","Ubuntu LTS","نسخه میان‌مدت"],"rows":[["پشتیبانی","۵ سال (با Pro تا ۱۲ سال)","۹ ماه"],["مخاطب","سرور و محیط تولید","میزکار علاقه‌مندان"],["نرم‌افزار","پایدار و آزمایش‌شده","جدیدتر، پرریسک‌تر"],["قاعده عملی","سرور: همیشه LTS","لپ‌تاپ: سلیقه‌ای"]]},{"k":"warn","title":"دام رایج","t":"نصب نسخه غیر-LTS روی سرور و مواجهه با پایان پشتیبانی بعد از ۹ ماه — یعنی ارتقای اجباری در بدترین زمان. روی سرور، شماره نسخه مهم‌تر از تاریخ نصب است: همیشه .04 زوج سال‌های LTS."},{"k":"tip","title":"نکته حرفه‌ای","t":"اگر ویندوز داری، لازم نیست پارتیشن را پاک کنی: WSL2 یک اوبونتوی کامل و واقعی داخل ویندوز می‌دهد و برای شروع عالی است. ولی هدف نهایی را فراموش نکن — روزی باید با یک سرور واقعی ابری (حتی رایگان) کار کنی، چون WSL بخش‌هایی مثل systemd و شبکه را ساده‌سازی می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["لینوکس هسته است؛ اوبونتو توزیعی بر پایه دبیان با جامعه و مستندات عالی.","برای سرور همیشه نسخه LTS نصب کن — پنج سال پشتیبانی رایگان.","ترمینال خانه اصلی مهندس است؛ از روز اول با آن راحت شو."]}]'::jsonb, '[{"q":"تفاوت اصلی «لینوکس» و «اوبونتو» چیست؟","opts":["فرقی ندارند","لینوکس فقط هسته است؛ اوبونتو یک توزیع کامل از هسته + ابزارها + بسته‌ها","اوبونتو جدیدتر است","لینوکس تجاری است"],"ans":1,"why":"هسته به‌تنهایی قابل‌استفاده نیست؛ توزیع‌ها مثل اوبونتو آن را با ابزار گنو، مدیریت بسته و تنظیمات بسته‌بندی می‌کنند."},{"q":"چرا برای سرور نسخه LTS توصیه می‌شود؟","opts":["رایگان‌تر است","۵ سال به‌روزرسانی امنیتی پایدار می‌گیرد و از ارتقای اجباری زودهنگام جلوگیری می‌کند","سریع‌تر است","گرافیک بهتری دارد"],"ans":1,"why":"سرور باید سال‌ها بدون تغییر بزرگ امن بماند؛ LTS دقیقاً این ضمانت را می‌دهد."},{"q":"uname -r چه چیزی را نشان می‌دهد؟","opts":["نسخه اوبونتو","نسخه هسته لینوکس","نام کاربر","آدرس IP"],"ans":1,"why":"برای نسخه توزیع از lsb_release و برای نسخه هسته از uname -r استفاده می‌شود — دانستن نسخه هسته برای سازگاری درایورها حیاتی است."}]'::jsonb),
('ub-r2', 'linux', 'سلسله‌مراتب فایل‌سیستم؛ نقشه شهرِ لینوکس', 50, 2, '[{"k":"p","t":"در لینوکس همه‌چیز فایل است — حتی سخت‌افزار و اطلاعات سیستم. و این فایل‌ها در یک ساختار استاندارد (FHS) چیده شده‌اند. کسی که این نقشه را بلد است، در هر سیستم لینوکسی غریبه نیست؛ کسی که بلد نیست، در هر سیستم گم می‌شود."},{"k":"h","t":"«همه‌چیز فایل» یعنی چه"},{"k":"visual","visual":"fhsTree","title":"شبیه‌ساز: نقشه فایل‌سیستم FHS"},{"k":"p","t":"یک سند متنی فایل است؛ دایرکتوری هم فایلی است که فهرست بچه‌هایش را نگه می‌دارد؛ /dev/sda نماینده دیسک است؛ /proc/cpuinfo اطلاعات لحظه‌ای پردازنده. این یکسان‌سازی شاهکار یونیکس است: چون همه‌چیز فایل است، یک ابزار ساده مثل cat یا grep می‌تواند متن بخواند، سخت‌افزار را بخواند و وضعیت سیستم را بخواند — بدون API جداگانه برای هر کدام."},{"k":"h","t":"دایرکتوری‌هایی که باید از حفظ باشی"},{"k":"p","t":"/etc خانه تنظیمات سیستمی است — هر سرویسی که پیکربندی دارد، اینجاست. /home خانه کاربران است و /root خانه کاربر مدیر (که عمداً از /home جداست). /var جای داده‌های متغیر است: لاگ‌ها، صف‌ها، دیتابیس‌ها. /tmp برای فایل‌های موقتی که ممکن است پاک شوند. /bin و /sbin فرمان‌های اصلی (و sbin برای فرمان‌های مدیریتی). و /usr دنیای نرم‌افزارهای نصبی: برنامه‌ها در /usr/bin و کتابخانه‌ها در /usr/lib."},{"k":"h","t":"دنیای مجازی: /proc و /sys"},{"k":"p","t":"/proc و /sys فایل‌سیستم‌های واقعی نیستند — پنجره‌ای زنده به درون هسته‌اند. cat /proc/meminfo وضعیت حافظه را در همین لحظه نشان می‌دهد و /sys کلاسی برای تنظیم پارامترهای هسته است (مثل روشن‌کردن IP forwarding با نوشتن یک ۱ در یک فایل). این دو دایرکتوری جایی‌اند که «همه‌چیز فایل» به اوج می‌رسد: وضعیت سیستم با خواندن فایل، و تغییرش با نوشتن فایل."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"خواندن وضعیت سیستم از فایل‌ها","code":"cat /proc/cpuinfo | grep ''model name'' | head -1\n# مدل پردازنده — بدون هیچ نرم‌افزار جانبی!\n\ncat /proc/meminfo | head -3\n# حافظه کل، آزاد و در دسترس\n\ncat /etc/os-release\n# مشخصات توزیع — فایل، نه فرمان خاص\n\nls /var/log | head\n# خانه لاگ‌ها — اولین مقصد هر دیباگ"},{"k":"list","items":["این سه فایل در هر لینوکسی هستند — نیازی به نصب ابزار نیست؛ حتی در حداقلی‌ترین کانتینر.","grep ''model name'' فقط خط‌های مدل را نگه می‌دارد و head -1 اولین را — نمونه‌ای از ترکیب ابزارهای ساده برای کار دقیق.","/var/log اولین مقصد هر مشکل است؛ عادت کن قبل از گوگل‌کردن، اینجا را نگاه کنی."]},{"k":"def","term":"FHS (Filesystem Hierarchy Standard)","t":"استانداردی که می‌گوید هر نوع فایل کجا زندگی کند: تنظیمات در etc، داده‌های متغیر در var، نرم‌افزارهای سیستمی در usr. این قرارداد باعث می‌شود ساختار دبیان، ردحت، آرچ و همه توزیع‌های دیگر قابل‌پیش‌بینی و مشابه باشد."},{"k":"table","head":["دایرکتوری","محتوا","مثال کاربردی"],"rows":[["/etc","تنظیمات سیستمی","sudoedit /etc/ssh/sshd_config"],["/home","فایل‌های کاربران","cd ~/Documents"],["/var","لاگ‌ها و داده‌های متغیر","less /var/log/syslog"],["/tmp","فایل‌های موقت","فایل‌های نصب و کش"],["/proc و /sys","پنجره زنده به هسته","cat /proc/uptime"],["/usr","نرم‌افزارهای نصبی","فایل‌های apt install"]]},{"k":"warn","title":"دام رایج","t":"ذخیره فایل مهم در /tmp و از دست‌دادنش بعد از ری‌استارت — systemd-tmpfiles محتوای /tmp را به‌طور منظم پاک می‌کند. هر چیزی که باید بماند، در خانه کاربر یا زیر /var یا /opt است؛ /tmp فقط برای چیزهایی است که از دست‌رفتنشان مهم نیست."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای پیداکردن تنظیمات هر سرویس، الگوی «نام سرویس + etc» را امتحان کن: nginx → /etc/nginx، ssh → /etc/ssh. این الگو در ۹۰٪ موارد جواب می‌دهد و بقیه را dpkg -L <بسته> لو می‌دهد که فهرست همه فایل‌های یک بسته را چاپ می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["در لینوکس همه‌چیز فایل است — حتی سخت‌افزار و وضعیت سیستم.","etc تنظیمات، home کاربران، var داده‌های متغیر و لاگ‌ها، usr نرم‌افزارها.","/proc و /sys پنجره زنده به هسته‌اند؛ خواندن‌شان یعنی وضعیت لحظه‌ای سیستم."]}]'::jsonb, '[{"q":"تنظیمات سرویس SSH در کجا قرار دارد؟","opts":["/usr/ssh","/etc/ssh","/var/ssh","/home/ssh"],"ans":1,"why":"قانون FHS: تنظیمات سیستمی در /etc؛ پس تنظیمات sshd در /etc/ssh/sshd_config است."},{"q":"/proc چه نوع فایل‌سیستمی است؟","opts":["پارتیشن دیسک","نمای مجازی و زنده از وضعیت هسته و processها","کش مرورگر","شبکه"],"ans":1,"why":"فایل‌های /proc روی دیسک نیستند؛ هسته آن‌ها را لحظه‌ای تولید می‌کند — خواندن‌شان یعنی پرسیدن مستقیم از هسته."},{"q":"لاگ‌های سیستمی معمولاً کجا هستند؟","opts":["/tmp/log","/var/log","/etc/log","/usr/log"],"ans":1,"why":"لاگ داده‌ای است که مدام تغییر می‌کند؛ جای داده‌های متغیر /var است، پس /var/log."}]'::jsonb),
('ub-r3', 'linux', 'ترمینال و فرمان‌های ضروری؛ دست‌های مهندس', 55, 3, '[{"k":"p","t":"رابط گرافیکی برای «یک کاربر» طراحی شده؛ ترمینال برای «مهندسی که هزار ماشین را مدیریت می‌کند». هر فرمانی که یاد می‌گیری یک اهرم است — و ترکیب فرمان‌ها با pipe، قدرتی می‌سازد که هیچ رابط گرافیکی‌ای ندارد."},{"k":"h","t":"ناوبری؛ گم‌نشدن ممنوع"},{"k":"p","t":"pwd می‌گوید کجایی، ls خانه را نشان می‌دهد (با la- برای دیدن مخفی‌ها)، cd جابه‌جا می‌کند: cd ~ خانه، cd .. یک سطح بالا، cd - برگشت به جای قبلی — همین یکی فرمان کوچک نیمی از ناوبری روزانه است. مسیرها یا مطلق‌اند (/etc/nginx) یا نسبی (./src). و Tab برای تکمیل خودکار و فلش بالا برای تاریخچه — دو کلیدی که سرعتت را ده برابر می‌کنند."},{"k":"h","t":"دست‌کاری فایل؛ پنج فرمانی که ۹۰٪ کار است"},{"k":"p","t":"mkdir ساختن دایرکتوری (با p- برای ساخت زنجیره‌ای)، cp کپی (r- برای درخت کامل)، mv جابه‌جایی و تغییر نام، rm حذف — که بی‌رحم است: در لینوکس «سطل بازیافت» معنایی ندارد و rm -rf اشتباه، درس‌هایی می‌دهد که هیچ‌وقت فراموش نمی‌شود. cat نمایش کامل فایل، less نمایش صفحه‌ای با امکان جست‌وجو (/عبارت)، head و tail ابتدا و انتها — و tail -f برای دیدن زنده لاگ‌ها، فرمانی که هر مدیر سرور روزانه استفاده می‌کند."},{"k":"h","t":"قدرت واقعی: pipe و ترکیب ابزارها"},{"k":"p","t":"فلسفه یونیکس: هر ابزار یک کار را خوب انجام دهد و خروجی‌اش متن باشد تا ابزار بعدی بخواندش. علامت | خروجی فرمان چپ را ورودی فرمان راست می‌کند. ps aux | grep nginx یعنی «از فهرست همه processها فقط خط‌های nginx». و > و >> خروجی را به فایل می‌ریزند (جایگزین و افزودن). وقتی یاد گرفتی grep و find و xargs و sort را ترکیب کنی، کارهایی می‌کنی که در ویندوز نیاز به نوشتن برنامه دارند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"پنج خط فرمان، پنج پاسخ واقعی","code":"# بزرگ‌ترین فایل‌های این دایرکتوری کدام‌اند؟\ndu -h --max-depth=1 . | sort -rh | head -5\n\n# کدام processها پورت ۸۰ را گرفته‌اند؟\nss -tulpn | grep '':80''\n\n# همه فایل‌های .log قدیمی‌تر از ۷ روز را پیدا کن\nfind /var/log -name ''*.log'' -mtime +7\n\n# شمارش خطاهای امروز در لاگ\ngrep -c ''ERROR'' /var/log/app.log\n\n# پشتیبان‌گیری فوری از تنظیمات\ntar -czf etc-backup-$(date +%F).tar.gz /etc/nginx"},{"k":"list","items":["خط اول سه ابزار را ترکیب می‌کند: du اندازه می‌گیرد، sort -rh مرتب می‌کند (بزرگ اول، خوانا)، head فقط ۵ تای اول — فلسفه یونیکس در یک خط.","ss جایگزین مدرن netstat است؛ tulpn یعنی TCP+UDP+پروسه‌ها+اسامی+عددی.","find با شرط mtime +7 یعنی «بیش از ۷ روز پیش تغییرکرده» — پایه پاک‌سازی خودکار لاگ‌ها.","$(date +%F) فرمان را اجرا و نتیجه را وسط نام فایل می‌گذارد: etc-backup-2026-03-14.tar.gz — تاریخ‌دار، بدون زحمت."]},{"k":"def","term":"Pipe (|)","t":"مکانیزمی که خروجی متنی یک فرمان را بدون واسطه فایل، به‌عنوان ورودی به فرمان بعدی می‌دهد. Pipe همان چیزی است که ابزارهای کوچک یونیکسی را به یک «زبان برنامه‌نویسی پردازش متن» تبدیل می‌کند."},{"k":"table","head":["فرمان","کار","نکته حیاتی"],"rows":[["ls -la","فهرست با مخفی‌ها","فایل‌های . نقطه‌دار، تنظیمات مخفی‌اند"],["rm -rf","حذف بازگشت‌ناپذیر","قبل از Enter، دوباره مسیر را بخوان"],["tail -f","دیدن زنده لاگ","خروج با Ctrl+C"],["grep -r","جست‌وجو در همه فایل‌ها","n- شماره خط هم می‌دهد"],["history","تاریخچه فرمان‌ها","!۱۲۳ یعنی اجرای فرمان شماره ۱۲۳"]]},{"k":"warn","title":"دام رایج","t":"اجرای rm -rf با متغیر خالی: rm -rf $DIR/ وقتی DIR خالی باشد یعنی rm -rf / — فاجعه‌ای که بارها در تاریخ تکرار شده. راه‌حل حرفه‌ای‌ها: set -u در اسکریپت‌ها که متغیر تعریف‌نشده را خطا می‌کند، و همیشه نقل‌قول: \"$DIR\"/."},{"k":"tip","title":"نکته حرفه‌ای","t":"فرمان man را دست‌کم نگیر: man grep همه گزینه‌ها را با مثال می‌گوید. و tldr یک نسخه خلاصه و مثال‌محور از man است (tldr tar) — برای شروع سریع‌تر است، ولی man مرجع نهایی می‌ماند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["ناوبری با pwd/ls/cd و تکمیل خودکار با Tab — پایه سرعت.","پنج فرمان cp/mv/rm/mkdir/less بیشترین استفاده روزانه را دارند؛ rm بی‌رحم است.","قدرت واقعی لینوکس در pipe است: ترکیب ابزارهای کوچک برای کارهای بزرگ."]}]'::jsonb, '[{"q":"فرمان ps aux | grep nginx چه می‌کند؟","opts":["nginx را نصب می‌کند","از فهرست همه processها فقط خط‌های مربوط به nginx را نشان می‌دهد","nginx را متوقف می‌کند","فایل‌های nginx را پاک می‌کند"],"ans":1,"why":"ps aux فهرست کامل processها را تولید می‌کند و grep فقط خط‌های دارای nginx را نگه می‌دارد — الگوی کلاسیک «پیداکن و فیلتر کن»."},{"q":"تفاوت > و >> چیست؟","opts":["> سریع‌تر است","> محتوای فایل را جایگزین می‌کند؛ >> به انتهای آن می‌افزاید","هیچ فرقی ندارند",">> فقط برای لاگ است"],"ans":1,"why":"اگر اشتباه کنی، > نتیجه ساعت‌ها کار را پاک می‌کند؛ برای افزودن به لاگ همیشه >>."},{"q":"tail -f چه کاربردی دارد؟","opts":["انتهای فایل را یک‌بار نشان می‌دهد","فایل را زنده دنبال می‌کند و خط‌های جدید را به‌محض آمدن چاپ می‌کند","فایل را می‌بندد","فایل را مرتب می‌کند"],"ans":1,"why":"برای دیدن همزمان لاگ سرویس هنگام تست — پرکاربردترین فرمان دیباگ سمت سرور."}]'::jsonb),
('ub-r4', 'linux', 'کاربران و مجوزها؛ چه کسی حق دارد چه کاری بکند', 55, 4, '[{"k":"p","t":"لینوکس از روز اول برای چند کاربر ساخته شده — و امنیتش نه به دیوار آتش، که به یک مدل ساده ریاضی متکی است: هر فایل یک مالک دارد، یک گروه، و سه عدد سه‌رقمی که دقیقاً می‌گویند چه کسی چه کاری می‌تواند بکند."},{"k":"h","t":"کاربر، گروه و sudo"},{"k":"visual","visual":"chmodCalc","title":"شبیه‌ساز: ماشین‌حساب chmod"},{"k":"p","t":"هر کاربر یک شناسه عددی (UID) دارد؛ کاربر ۰ یعنی root که همه‌کاره است — و به همین دلیل تقریباً هیچ‌وقت نباید مستقیم root باشی. در اوبونتو به‌جای ورود به root، از sudo استفاده می‌کنی: فرمان را با امتیاز مدیر اجرا می‌کند، همه‌چیز را در /var/log/auth.log ثبت می‌کند و بعد از ۱۵ دقیقه منقضی می‌شود. گروه‌ها (مثل sudo و www-data) راه دادن امتیاز به چند کاربرند: کاربر را به گروه sudo اضافه کن، مدیر شده — بدون دادن رمز root."},{"k":"h","t":"سه‌تایی rwx؛ زبان مجوزها"},{"k":"p","t":"هر فایل سه دسته مجوز دارد: مالک (user)، گروه (group) و بقیه (others) — و برای هر کدام سه حق: خواندن r، نوشتن w و اجرا x. خروجی ls -l مثل -rwxr-xr-- خوانده می‌شود: حرف اول نوع فایل (– عادی، d دایرکتوری، l لینک) و سه‌تایی‌های بعدی مجوز سه دسته. برای دایرکتوری، x معنایش تغییر می‌کند: «حق ورود» — بدون آن، حتی خواندن فهرست ممکن نیست."},{"k":"h","t":"اعداد هشتایی؛ چرا 755 و 644"},{"k":"p","t":"هر حق یک عدد است: r=4، w=2، x=1 — و مجموع‌شان مجوز یک دسته را می‌سازد: rwx = 7، r-x = 5، r-- = 4. پس 755 یعنی «مالک همه‌کاره، گروه و بقیه فقط خواندن و اجرا». سه عدد پرکاربرد صنعت: 755 برای دایرکتوری‌ها و اسکریپت‌ها، 644 برای فایل‌های معمولی (مالک ویرایش، بقیه فقط خواندن) و 600 برای اسرار (فقط مالک). chmod 600 ~/.ssh/id_rsa تنها راهی است که SSH کلیدت را می‌پذیرد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"مدیریت مجوزها در عمل","code":"ls -l deploy.sh\n# -rw-r--r--  → هنوز قابل‌اجرا نیست\n\nchmod 755 deploy.sh\n# -rwxr-xr-x  → مالک کامل، بقیه خواندن+اجرا\n\nchown www-data:www-data /var/www/site -R\n# مالکیت درخت وب را به کاربر سرویس بده\n\nuseradd -m -s /bin/bash deployer\nusermod -aG sudo deployer     # اضافه به گروه sudo\n# و در /etc/sudoers.d فقط فرمان‌های خاص:\n# deployer ALL=(ALL) NOPASSWD: /bin/systemctl restart app"},{"k":"list","items":["قبل از chmod، خروجی ls -l را بخوان تا بدانی دقیقاً چه چیزی تغییر کرد — عادت حرفه‌ای‌ها.","chown -R بازگشتی است: مالکیت کل درخت /var/www یکجا عوض می‌شود — نیاز همیشگی بعد از آپلود با کاربر دیگر.","usermod -aG بدون a- خطرناک است: گروه‌های قبلی کاربر را پاک می‌کند! همیشه -aG (افزودن به گروه).","sudoers.d یعنی دادن امتیاز sudo فقط برای فرمان‌های خاص — اصل حداقل امتیاز به شکل لینوکسی."]},{"k":"def","term":"اصل حداقل امتیاز (Least Privilege)","t":"هر کاربر و هر سرویس فقط امتیازهایی داشته باشد که برای کارش لازم است — نه بیشتر. سرویس وب به‌جای root با کاربر www-data اجرا می‌شود تا اگر هک شد، مهاجم صاحب سیستم نشود؛ و کاربر deploy فقط systemctl restart حق دارد، نه همه sudo."},{"k":"table","head":["مجوز","معنی","کاربرد معمول"],"rows":[["755","مالک کامل؛ بقیه خواندن+اجرا","دایرکتوری‌ها و اسکریپت‌ها"],["644","مالک خواندن+نوشتن؛ بقیه خواندن","فایل‌های متنی و تنظیمات"],["600","فقط مالک","کلید SSH و فایل‌های رمز"],["777","همه همه‌کاره","تقریباً همیشه اشتباه است!"]]},{"k":"warn","title":"دام رایج","t":"chmod 777 برای «حل» مشکل دسترسی — رایج‌ترین اشتباه امنیت لینوکس. اسکریپتی که همه حق نوشتنش را دارند یعنی هر کاربر (و هر بدافزاری) می‌تواند کدش را عوض کند. راه‌حل واقعی، تغییر مالک (chown) یا گروه است، نه بازکردن درها روی همه."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای دیدن سریع «چه کسی چه چیزی است»: id نام‌کاربر همه گروه‌ها و UID را نشان می‌دهد؛ sudo -l می‌گوید همین کاربر چه فرمان‌هایی را با sudo می‌تواند بزند. قبل از هر تغییر دسترسی، اول این دو را بزن."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هر فایل: یک مالک، یک گروه و سه دسته مجوز rwx.","اعداد هشتایی جمع r=4+w=2+x=1 هستند؛ 755 و 644 و 600 سه استاندارد صنعت.","sudo + گروه‌ها + امتیاز حداقلی، جایگزین امن ورود مستقیم به root."]}]'::jsonb, '[{"q":"معنی دقیق chmod 640 report.txt چیست؟","opts":["همه فقط بخوانند","مالک خواندن+نوشتن، گروه فقط خواندن، بقیه هیچ","مالک هیچ، گروه خواندن، بقیه نوشتن","فایل مخفی می‌شود"],"ans":1,"why":"6=rw برای مالک، 4=r برای گروه، 0=هیچ برای بقیه — ترکیبی متداول برای فایل‌هایی که تیم می‌خواند ولی فقط مالک ویرایش می‌کند."},{"q":"چرا usermod -aG مهم‌تر از usermod -G است؟","opts":["سریع‌تر است","با a- کاربر را به گروه «اضافه» می‌کند؛ بدون آن فهرست گروه‌های قبلی جایگزین و حذف می‌شود","فرقی ندارد","فقط برای root است"],"ans":1,"why":"حذف ناخواسته از گروه‌ها (مثل sudo یا docker) یکی از رایج‌ترین قفل‌شدن‌های مدیران تازه‌کار است."},{"q":"برای دایرکتوری، حق x چه معنایی دارد؟","opts":["حذف دایرکتوری","حق ورود و پیمایش داخل آن","اجرای همه فایل‌هایش","معنایی ندارد"],"ans":1,"why":"بدون x روی دایرکتوری، حتی cd کردن و خواندن فایل‌های داخلش ممکن نیست — حتی با خواندن کامل فهرست."}]'::jsonb)
